check('PARCELLE_SUBTYPES is exactly the three documented sub-types', () => {
  assert.deepStrictEqual(openaiService.PARCELLE_SUBTYPES, ['maison_type_locataire', 'villa', 'terrain_nu']);
});
check('parcelle_subtype/units_count/reference are present in the strict schema and required', () => {
  const props = schema.properties.extracted_data.properties;
  const required = schema.properties.extracted_data.required;
  for (const field of ['parcelle_subtype', 'units_count', 'reference']) {
    assert.ok(props[field], `schema missing property "${field}"`);
    assert.ok(required.includes(field), `"${field}" not in required (violates strict mode)`);
  }
  assert.deepStrictEqual(props.parcelle_subtype.enum, ['maison_type_locataire', 'villa', 'terrain_nu', null]);
});
check('the three "3 + 1 + 1" entry costs are separate nullable integers in the strict schema', () => {
  const props = schema.properties.extracted_data.properties;
  const required = schema.properties.extracted_data.required;
  for (const field of ['deposit_months', 'advance_months', 'commission_months']) {
    assert.ok(props[field], `schema missing property "${field}"`);
    assert.ok(required.includes(field), `"${field}" not in required (violates strict mode)`);
    assert.deepStrictEqual(props[field].type, ['integer', 'null'], `"${field}" must be a nullable integer`);
  }
  // No "total"/"upfront" field: a sum is derived at render time from the
  // three real postes. Storing it too would let it drift from its parts —
  // and a stored total is exactly what produced the "Garantie : 5 mois" bug.
  assert.ok(!props.total_upfront_months, 'the total must stay derived, not stored');
});
check('system prompt forbids summing "3 + 1 + 1" into deposit_months', () => {
  const prompt = openaiService.SYSTEM_PROMPT;
  // The convention itself, the three destination fields, and an explicit
  // prohibition — the actual bug was the model summing them to 5.
  for (const needle of [
    '3 + 1 + 1', 'advance_months', 'commission_months',
    'Ne les additionne JAMAIS dans deposit_months',
    "ne veut PAS dire 5 mois de garantie",
  ]) {
    assert.ok(prompt.includes(needle), `prompt missing "${needle}"`);
  }
});
check('every entry-cost line says WHO receives the money', () => {
  // A tenant reading the card must know which part goes to the landlord,
  // which part comes back, and which part is the agency's fee. The card is
  // rendered from the stored row (services/listingCard.js), not by the model.
  const prompt = require('fs').readFileSync(require('path').join(__dirname, '..', 'services', 'listingCard.js'), 'utf8');
  for (const needle of [
    'Payable au Bailleur',
    'Retenu par le Bailleur',
    "Payable à l'Agent / Agence",
    'remboursable en fin de bail',
  ]) {
    assert.ok(prompt.includes(needle), `prompt missing "${needle}"`);
  }
});
check('the prompt carries the unqualified "N mois" Kinshasa convention', () => {
  const prompt = openaiService.SYSTEM_PROMPT;
  assert.ok(prompt.includes('DURÉE NON QUALIFIÉE'));
  // The convention itself, and the exception that protects a named poste.
  assert.ok(prompt.includes('(N-1) mois d\'avance + 1 mois de garantie'));
  assert.ok(prompt.includes('Le mot écrit par l\'agent l\'emporte toujours sur la convention'));
});
check('normaliseEntryCosts re-derives additive syntax from the agent\'s own words', () => {
  // The model is not trusted alone on the three most consequential numbers in
  // a listing — the raw text wins wherever it is unambiguous.
  const summed = openaiService.normaliseEntryCosts(
    { deposit_months: 5, advance_months: null, commission_months: null },
    'Belle villa, Garantie 3 + 1 + 1',
  );
  assert.strictEqual(summed.deposit_months, 3, 'the total must never land in deposit_months');
  assert.strictEqual(summed.advance_months, 1);
  assert.strictEqual(summed.commission_months, 1);

  const twoTerms = openaiService.normaliseEntryCosts(
    { deposit_months: null, advance_months: null, commission_months: 9 },
    'GARANTIE 4+1',
  );
  assert.strictEqual(twoTerms.deposit_months, 4);
  assert.strictEqual(twoTerms.advance_months, 1);
  assert.strictEqual(twoTerms.commission_months, null, 'an unstated commission stays NULL, never 0');
});
check('an unqualified "N mois" becomes (N-1) advance + 1 guarantee', () => {
  const split = openaiService.normaliseEntryCosts(
    { deposit_months: 4, advance_months: null, commission_months: null },
    'Appartement Limete 1000$ 4mois',
  );
  assert.strictEqual(split.advance_months, 3);
  assert.strictEqual(split.deposit_months, 1);
  assert.strictEqual(split.commission_months, null);
});
check('a NAMED poste always beats the convention', () => {
  // "garantie 3 mois" is the agent telling us exactly what that 3 is.
  const named = openaiService.normaliseEntryCosts(
    { deposit_months: 3, advance_months: null, commission_months: null },
    'Villa Ngaliema, garantie 3 mois',
  );
  assert.strictEqual(named.deposit_months, 3);
  assert.strictEqual(named.advance_months, null);
});
check('a correction naming only the rent never rewrites a stated garantie', () => {
  // Correction mode hands normaliseEntryCosts the MERGED draft, whose
  // "garantie 3 mois" came from an earlier turn; "par mois" is the rent's
  // period. This used to become 2 avance + 1 garantie.
  const merged = openaiService.normaliseEntryCosts(
    { price: 600, deposit_months: 3, advance_months: null, commission_months: null },
    "non le loyer c'est 600$ par mois",
  );
  assert.strictEqual(merged.deposit_months, 3);
  assert.strictEqual(merged.advance_months, null);
});
check('"pas 3+1+1 mais 2+1+1" keeps the model\'s reading, never the first match', () => {
  // The first match is the OLD terms: storing it put figures on the site that
  // the agent had just corrected, while the reply showed them the new ones.
  const corrected = openaiService.normaliseEntryCosts(
    { deposit_months: 2, advance_months: 1, commission_months: 1 },
    'non pas 3+1+1 mais 2+1+1',
  );
  assert.deepStrictEqual(
    [corrected.deposit_months, corrected.advance_months, corrected.commission_months],
    [2, 1, 1],
  );
  const repeated = openaiService.normaliseEntryCosts(
    { deposit_months: 5, advance_months: null, commission_months: null },
    'garantie 3+1+1 (oui 3+1+1)',
  );
  assert.strictEqual(repeated.deposit_months, 3, 'one expression written twice is still unambiguous');
});
check('short approvals publish without a model call; refusals and edits never do', () => {
  for (const yes of ['OK', 'ok merci', 'Oui, merci !', "c'est correct", '👍', '👍🏾', 'oui vous pouvez publier']) {
    assert.ok(webhookRouter.isAffirmative(yes), `"${yes}" should confirm`);
  }
  for (const no of ['non', 'pas correct', "c'est pas correct", 'ok mais 3ch', 'ok 570', 'correct?']) {
    assert.ok(!webhookRouter.isAffirmative(no), `"${no}" must not confirm`);
  }
});
check('the intake card is rendered from the stored row, never the model\'s retelling', () => {
  const listingCard = require('../services/listingCard');
  // The model said 3 months of garantie; the row (what gets published) says 2.
  const reply = listingCard.composeIntakeReply(
    'Merci pour la correction.\n\n*Garantie* : 3 mois\n*Loyer* : 500$\n\nRépondez "OK" pour publier.',
    { transaction_type: 'location', property_type: 'appartement', commune: 'Limete', price: 500, currency: 'USD',
      price_period: 'mois', deposit_months: 2, advance_months: 1, commission_months: 1, bedrooms: 2, photos: ['a.jpg'] },
  );
  assert.ok(reply.startsWith('Merci pour la correction.'), 'the model keeps the greeting');
  assert.ok(reply.includes('*Garantie* : 2 mois (1 000 $)'), reply);
  assert.ok(!reply.includes('3 mois'), 'the model\'s figure never reaches the agent');
  assert.ok(reply.includes('*Total à prévoir à l\'entrée* : 4 mois (2 000 $)'));
  assert.strictEqual((reply.match(/OK/g) || []).length, 1, 'one instruction to reply OK, not two');
  const noPhoto = listingCard.renderListingCard({ commune: 'Gombe', photos: [] });
  assert.ok(noPhoto.includes('*Photos* : aucune'));
  assert.deepStrictEqual(listingCard.missingFields({ property_type: 'terrain', commune: 'Gombe', price: 9 }), ['transaction_type']);
  assert.ok(!listingCard.composeIntakeReply('Bonjour', { commune: 'Gombe' }, { mode: 'onboarding' }).includes('OK'));
});
check('the correction prompt covers "pas X mais Y" and a bare "non"', () => {
  const prompt = openaiService.SYSTEM_PROMPT;
  assert.ok(prompt.includes('"pas X mais Y"'));
  assert.ok(prompt.includes('NE TOUCHE QU\'À CE QUE LE MESSAGE CORRIGE'));
  assert.ok(prompt.includes('NON SANS PRÉCISION'));
});
check('a listing that states no entry costs at all is left completely alone', () => {
  const untouched = openaiService.normaliseEntryCosts(
    { deposit_months: null, advance_months: null, commission_months: null },
    'Villa 3 chambres Gombe 1500$/mois',
  );
  assert.strictEqual(untouched.deposit_months, null);
  assert.strictEqual(untouched.advance_months, null);
  // NULL is "not stated", which is a different claim from 0 = "none required".
  assert.notStrictEqual(untouched.advance_months, 0);
});
check('a bare month count that is not an entry cost is not rewritten', () => {
  const lease = openaiService.normaliseEntryCosts(
    { deposit_months: null, advance_months: null, commission_months: null },
    'Bureau à louer, bail de 2 ans',
  );
  assert.strictEqual(lease.deposit_months, null);
});
check('the WhatsApp card shows the three entry costs on their own lines', () => {
  // "*Garantie*" must carry deposit_months alone — the agent-facing half of
  // the same bug, where the confirmation read back "Garantie : 5 mois". The
  // card is drawn from the stored row (services/listingCard.js); the model
  // only writes the greeting above it, so the prompt carries no card template
  // (2026-11-03: ~200 output tokens, ~2 s, saved per reply).
  const card = require('../services/listingCard').renderListingCard({
    transaction_type: 'location', property_type: 'appartement', price: 750, currency: 'USD',
    price_period: 'mois', deposit_months: 3, advance_months: 1, commission_months: 1,
  });
  assert.match(card, /\*Garantie\* : 3 mois/);
  assert.match(card, /\*Loyer d'avance\* : 1 mois/);
  assert.match(card, /\*Commission d'agence\* : 1 mois/);
  assert.match(card, /\*Total à prévoir à l'entrée\* : 5 mois/);
  assert.ok(!openaiService.SYSTEM_PROMPT.includes('{deposit_months} mois'), 'the model must not write the card');
});

check('system prompt carries the chaos-tolerance and correction-loop rules', () => {
  const prompt = openaiService.SYSTEM_PROMPT;
  for (const needle of [
    'TOLÉRANCE AU CHAOS',
    'BROUILLON EN COURS — BOUCLE DE CORRECTION',
    'CONFIRMATION (champ is_confirmed)',
    'IDENTITÉ ET AGENCE',
    // The typo examples are the point of the section, not decoration.
    'Slaongo', '3ch', 'Kkimmo',
  ]) {
    assert.ok(prompt.includes(needle), `prompt missing "${needle}"`);
  }
});
check('a pending draft flips the is_listing:false reply from a rejection to a re-render', () => {
  const prompt = openaiService.SYSTEM_PROMPT;
  // The bug this fixes: a two-word correction was answered with "send me the
  // listing details" because the only is_listing:false rule was that ask.
  assert.ok(
    prompt.includes("Si is_listing est false ET qu'un BROUILLON EN COURS est fourni"),
    'prompt has no draft-aware branch for is_listing:false',
  );
  assert.ok(
    prompt.includes("Si is_listing est false et qu'aucun brouillon n'est en cours"),
    'the no-draft ask must survive as its own explicit branch',
  );
  assert.ok(
    prompt.includes('Ne demande JAMAIS à l\'agent de renvoyer son annonce quand un brouillon existe'),
    'prompt must forbid re-asking for a listing it already holds',
  );
});
check('a correction must restate the merged draft, not just the changed field', () => {
  // Keeps the reply and services/db.js's SQL merge from disagreeing.
  assert.ok(openaiService.SYSTEM_PROMPT.includes('renvoie le brouillon COMPLET après fusion'));
});
check('multi-unit fields are in the strict schema and required', () => {
  const props = schema.properties.extracted_data.properties;
  const required = schema.properties.extracted_data.required;
  for (const field of ['is_multi_unit', 'building_name', 'units']) {
    assert.ok(props[field], `schema missing property "${field}"`);
    assert.ok(required.includes(field), `"${field}" not in required (violates strict mode)`);
  }
  // strict mode applies to nested objects too — a missing additionalProperties
  // or an unlisted property here is a 400 from the API, not a soft failure.
  const unit = props.units.items;
  assert.strictEqual(unit.additionalProperties, false);
  for (const field of Object.keys(unit.properties)) {
    assert.ok(unit.required.includes(field), `unit field "${field}" not in required`);
  }
  for (const field of ['bedrooms', 'bathrooms', 'price', 'floor', 'quantity']) {
    assert.ok(unit.properties[field], `unit schema missing "${field}"`);
  }
});
check('the prompt tells the model to split a building instead of picking one price', () => {
  const prompt = openaiService.SYSTEM_PROMPT;
  for (const needle of [
    'IMMEUBLE À PLUSIEURS LOGEMENTS',
    'is_multi_unit = true',
    'ne choisis jamais un seul prix',
    "typologies d'appartements détectées",
    'annonces liées',
  ]) {
    assert.ok(prompt.includes(needle), `prompt missing "${needle}"`);
  }
  // The parcelle rule must not be swallowed by the new one: "4 Portes" is a
  // rental plot (units_count), NOT a multi-unit building.
  assert.ok(prompt.includes("n'est PAS un immeuble multi-unités"));
});
check('is_confirmed / agent_name / agency_name are in the strict schema and required', () => {
  const props = schema.properties.extracted_data.properties;
  const required = schema.properties.extracted_data.required;
  for (const field of ['is_confirmed', 'agent_name', 'agency_name']) {
    assert.ok(props[field], `schema missing property "${field}"`);
    assert.ok(required.includes(field), `"${field}" not in required (violates strict mode)`);
  }
  assert.strictEqual(props.is_confirmed.type, 'boolean', 'is_confirmed must never be null');
  assert.deepStrictEqual(props.agent_name.type, ['string', 'null']);
  assert.deepStrictEqual(props.agency_name.type, ['string', 'null']);
});

