  // -------------------------------------------------------------------------
  // 6. End-to-end through the live HTTP endpoint
  // -------------------------------------------------------------------------

  console.log('\n6. End-to-end: POST /webhook -> openai -> db -> chakra');

  /**
   * @param {Object} [options]
   * @param {string|null} [options.signature] Override the X-Chakra-Signature-256
   *        header. Omit for a correctly-signed request (the normal case);
   *        pass a bad value to test rejection, or null to omit the header.
   */
  function post(pathname, body, options = {}) {
    const payload = JSON.stringify(body);
    const headers = {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
    };
    if (pathname === '/webhook') {
      const signature = 'signature' in options
        ? options.signature
        : require('crypto')
            .createHmac('sha256', process.env.CHAKRA_WEBHOOK_HMAC_SECRET)
            .update(payload)
            .digest('hex');
      if (signature !== null) {
        headers['X-Chakra-Signature-256'] = signature;
      }
    }
    return new Promise((resolve) => {
      const req = http.request(
        { host: 'localhost', port: 3200, path: pathname, method: 'POST', headers },
        (res) => { res.resume(); res.on('end', () => resolve(res.statusCode)); },
      );
      req.end(payload);
    });
  }
  const settle = (ms = 400) => new Promise((r) => setTimeout(r, ms));

  function inbound(wamid, text, from = '243840000000') {
    return {
      object: 'whatsapp_business_account',
      entry: [{ id: '1', changes: [{ field: 'messages', value: {
        metadata: { phone_number_id: '987654321' },
        contacts: [{ wa_id: from, profile: { name: 'Agent Kimwenza' } }],
        messages: [{ from, id: wamid, timestamp: '1', type: 'text', text: { body: text } }],
      } }] }],
    };
  }

  function inboundImage(wamid, mediaId, caption, from = '243850000000') {
    const image = caption ? { id: mediaId, caption } : { id: mediaId };
    return {
      object: 'whatsapp_business_account',
      entry: [{ id: '1', changes: [{ field: 'messages', value: {
        metadata: { phone_number_id: '987654321' },
        contacts: [{ wa_id: from, profile: { name: 'Agent Photo' } }],
        messages: [{ from, id: wamid, timestamp: '1', type: 'image', image }],
      } }] }],
    };
  }

  /** Give a draft a photo, as if the agent had sent one earlier in the thread.
   *  Publication now requires it — see section 6f. */
  function attachPhoto(listingId, name = 'seed') {
    dbService.applyListingCorrection(listingId, null, null, [], [`/uploads/listings/${name}.jpg`]);
  }

  // -------------------------------------------------------------------------
  // 6a. Webhook HMAC signature verification (X-Chakra-Signature-256)
  // -------------------------------------------------------------------------

  console.log('\n6a. POST /webhook signature verification');

  const sigRowsBefore = dbService.countListings();
  const sigAiBefore = openaiCalls.length;

  const missingSigStatus = await post(
    '/webhook',
    inbound('wamid.NOSIG', 'Villa a louer Ngaliema'),
    { signature: null },
  );
  check('rejects a request with no signature header', () => assert.strictEqual(missingSigStatus, 401));

  const badSigStatus = await post(
    '/webhook',
    inbound('wamid.BADSIG', 'Villa a louer Ngaliema'),
    { signature: 'deadbeef'.repeat(8) },
  );
  check('rejects a request with a wrong signature', () => assert.strictEqual(badSigStatus, 401));

  await settle(200);
  check('neither rejected request reached the model or the DB', () => {
    assert.strictEqual(openaiCalls.length, sigAiBefore);
    assert.strictEqual(dbService.countListings(), sigRowsBefore);
  });

  // -------------------------------------------------------------------------
  // 6a2. A video with no caption that cannot be fetched: "renvoyez", never
  // silence (videos are kept since 2026-10-21 — §63 covers the stored path)
  // -------------------------------------------------------------------------

  console.log('\n6a2. POST /webhook unsupported media reply');

  const vidRowsBefore = dbService.countListings();
  const vidAiBefore = openaiCalls.length;
  httpCalls.length = 0;

  const vidStatus = await post('/webhook', {
    object: 'whatsapp_business_account',
    entry: [{ id: '1', changes: [{ field: 'messages', value: {
      metadata: { phone_number_id: '987654321' },
      contacts: [{ wa_id: '243870000000', profile: { name: 'Agent Video' } }],
      messages: [{ from: '243870000000', id: 'wamid.VIDEO', timestamp: '1', type: 'video', video: { id: 'v1', mime_type: 'video/mp4' } }],
    } }] }],
  });
  await settle(200);

  check('acknowledges the video message with 200', () => assert.strictEqual(vidStatus, 200));
  check('a captionless video never reaches gpt-4o or the DB', () => {
    assert.strictEqual(openaiCalls.length, vidAiBefore);
    assert.strictEqual(dbService.countListings(), vidRowsBefore);
  });
  check('a video that cannot be fetched (not a video) is answered with "renvoyez", not silence', () => {
    // (any earlier reply is the "un instant" ack every media burst gets)
    const replies = httpCalls.filter((c) => c.method === 'post' && c.data?.text?.body);
    const last = replies[replies.length - 1];
    assert.strictEqual(last.data.to, '243870000000');
    assert.strictEqual(last.data.text.body, webhookRouter.VIDEO_DOWNLOAD_FAILED_REPLY);
  });

  const rowsBefore = dbService.countListings();
  const aiBefore = openaiCalls.length;
  httpCalls.length = 0;

  const status = await post('/webhook', inbound('wamid.E2E', 'Villa a louer Ngaliema 4 chambres 2500$/mois'));
  await settle();

  check('acknowledges with 200', () => assert.strictEqual(status, 200));
  check('called gpt-4o exactly once', () => assert.strictEqual(openaiCalls.length - aiBefore, 1));
  check('saved exactly one listing', () =>
    assert.strictEqual(dbService.countListings() - rowsBefore, 1));
  check('sent exactly one Chakra reply', () => assert.strictEqual(httpCalls.length, 1));
  check('reply went to the sender with the model-written text', () => {
    assert.strictEqual(httpCalls[0].data.to, '243840000000');
    assert.ok(httpCalls[0].data.text.body.includes('Annonce reçue'));
  });
  check('stored row is linked to the inbound wamid', () => {
    const found = dbService.findByWamid('wamid.E2E');
    assert.ok(found, 'no row found for wamid.E2E');
  });
  check('quartier is normalised end-to-end ("Ma Campagne" -> "Macampagne")', () => {
    const found = dbService.findByWamid('wamid.E2E');
    const row = dbService.getListing(found.id);
    assert.strictEqual(row.commune, 'Ngaliema');
    assert.strictEqual(row.quartier, 'Macampagne');
  });

  // A parcelle listing carrying all three new classification fields, driven
  // through the real HTTP endpoint end-to-end (webhook -> openai -> db), not
  // just a direct services/db.js call — confirms extraction, coercion (a
  // string "4" for units_count must still land as an integer) and storage
  // all agree on these fields, not just each in isolation.
  nextCompletion = cannedCompletion({
    choices: [{ finish_reason: 'stop', message: { refusal: null, content: JSON.stringify({
      extracted_data: {
        is_listing: true, intent: 'listing', transaction_type: 'vente', property_type: 'parcelle',
        parcelle_subtype: 'maison_type_locataire', commune: 'Mont-Ngafula', quartier: 'Kimwenza',
        price: 45000, currency: 'USD', price_period: 'total', deposit_months: null,
        bedrooms: null, bathrooms: null, surface_area_sqm: 95.4, units_count: '4',
        furnished: null, amenities: [], reference: 'LKP-2026-0091',
        summary_fr: 'Parcelle avec maison type locataire, 4 portes, a Kimwenza.',
        missing_fields: [], confidence: 0.92,
      },
      whatsapp_reply: '*Annonce reçue* ✅\nParcelle a Kimwenza. Répondez *OK* pour publier.',
    }) } }],
  });
  await post(
    '/webhook',
    // A distinct sender is deliberate: wamid.E2E (above) is still pending on
    // the default sender, awaiting the 'OK' the next block below sends — a
    // second listing landing on that same sender would out-rank it as "most
    // recent pending" and steal that confirmation.
    inbound(
      'wamid.PARCELLE_E2E',
      'A vendre parcelle clôturée, Maison Type Locataire 4 Portes, Kimwenza Mont-Ngafula. 5,30m sur 18m. 45000$. Réf: LKP-2026-0091',
      '243845550001',
    ),
  );
  await settle();

  check('parcelle_subtype/units_count/reference reach SQLite end-to-end through the real webhook route', () => {
    const found = dbService.findByWamid('wamid.PARCELLE_E2E');
    assert.ok(found, 'no row found for wamid.PARCELLE_E2E');
    const parcelleRow = dbService.getListing(found.id);
    assert.strictEqual(parcelleRow.property_type, 'parcelle');
    assert.strictEqual(parcelleRow.parcelle_subtype, 'maison_type_locataire');
    assert.strictEqual(parcelleRow.units_count, 4, 'a numeric string from the model must still coerce to an integer');
    assert.strictEqual(parcelleRow.reference, 'LKP-2026-0091');
    assert.strictEqual(parcelleRow.commune, 'Mont-Ngafula');
    assert.strictEqual(parcelleRow.quartier, 'Kimwenza');
  });

  // Confirming with 'OK' — the actual multi-turn confirmation loop, end to end
  // through the HTTP endpoint (not just the services/db.js unit checks above).
  const aiBeforeConfirm = openaiCalls.length;
  httpCalls.length = 0;
  // Publication requires at least one photo (section 6f); this test is about
  // the confirmation path, so give the draft the photo it would really have.
  attachPhoto(dbService.findByWamid('wamid.E2E').id, 'e2e');
  await post('/webhook', inbound('wamid.CONFIRM', 'OK'));
  await settle();

  check("'OK' publishes without calling gpt-4o again", () =>
    assert.strictEqual(openaiCalls.length - aiBeforeConfirm, 0));
  check("'OK' gets the exact published-confirmation reply", () => {
    assert.strictEqual(httpCalls.length, 1);
    assert.match(httpCalls[0].data.text.body, /^✅ \*Annonce bien reçue et en cours de modération !\*\n• /);
  });
  check('the listing is now published', () => {
    const found = dbService.findByWamid('wamid.E2E');
    assert.strictEqual(dbService.getListing(found.id).status, 'published');
  });

  // Redelivery must not re-bill gpt-4o or re-reply.
  const aiBeforeRetry = openaiCalls.length;
  const rowsBeforeRetry = dbService.countListings();
  httpCalls.length = 0;
  await post('/webhook', inbound('wamid.E2E', 'Villa a louer Ngaliema 4 chambres 2500$/mois'));
  await settle();

  check('redelivery makes no gpt-4o call', () =>
    assert.strictEqual(openaiCalls.length - aiBeforeRetry, 0));
  check('redelivery inserts no row', () =>
    assert.strictEqual(dbService.countListings() - rowsBeforeRetry, 0));
  check('redelivery sends no second reply', () => assert.strictEqual(httpCalls.length, 0));

  // Non-listing chatter: reply, but do not store — and, since
  // services/quickReplies.js landed, without paying for a model call at all.
  // Deliberately queues NO completion: if the fast path ever regressed into
  // calling the model, it would consume the next test's canned response and
  // fail there instead of here, so the absence is itself part of the check.
  const rowsBeforeGreeting = dbService.countListings();
  const aiBeforeGreeting = openaiCalls.length;
  httpCalls.length = 0;
  await post('/webhook', inbound('wamid.GREET', 'Bonjour'));
  await settle();

  check('a bare greeting is answered without any gpt-4o call', () =>
    assert.strictEqual(openaiCalls.length - aiBeforeGreeting, 0));
  check('the greeting reply welcomes the agent and asks for a listing', () => {
    const body = httpCalls[0].data.text.body;
    assert.ok(body.includes('Lukka Place'));
    assert.ok(/photo/i.test(body), 'it must mention the mandatory photo up front');
  });

  check('greeting stores no listing', () =>
    assert.strictEqual(dbService.countListings() - rowsBeforeGreeting, 0));
  check('greeting still gets a reply', () => {
    assert.strictEqual(httpCalls.length, 1);
    assert.ok(httpCalls[0].data.text.body.includes('Bonjour'));
  });

  // A payload with nothing usable must not crash or call anything.
  const aiBeforeJunk = openaiCalls.length;
  httpCalls.length = 0;
  const junkStatus = await post('/webhook', { object: 'whatsapp_business_account', entry: [] });
  await settle(200);
  check('junk payload is acked and ignored', () => {
    assert.strictEqual(junkStatus, 200);
    assert.strictEqual(openaiCalls.length - aiBeforeJunk, 0);
    assert.strictEqual(httpCalls.length, 0);
  });

  // -------------------------------------------------------------------------
  // 6a3. PDF flyer end-to-end, through the real webhook
  //
  // 5f drives services/documentText.js directly. That is the half that always
  // worked. The half that did NOT was routes/webhook.js's own PDF branch:
  // `text` and `hasText` were declared `const` and then assigned to when a
  // readable text layer came back, so EVERY flyer carrying real text threw
  // `TypeError: Assignment to constant variable.` inside processGroup's try.
  // The agent got no reply and the listing was never stored, while the
  // no-text-layer branch beside it worked fine — which is exactly why it read
  // as intermittent rather than total.
  //
  // A module-level test could never have caught this. The assertion has to run
  // the request through the webhook.
  // -------------------------------------------------------------------------

  console.log('\n6a3. PDF flyer end-to-end (regression: const reassignment)');

  const pdfRowsBefore = dbService.countListings();
  const pdfAiBefore = openaiCalls.length;
  const savedMediaBytes = mediaBinaryResponse;
  const savedMediaType = mediaContentType;
  mediaBinaryResponse = flyerPdf;
  mediaContentType = 'application/pdf';
  httpCalls.length = 0;

  const pdfStatus = await post('/webhook', {
    object: 'whatsapp_business_account',
    entry: [{ id: '1', changes: [{ field: 'messages', value: {
      metadata: { phone_number_id: '987654321' },
      contacts: [{ wa_id: '243850000777', profile: { name: 'Agence Flyer' } }],
      messages: [{
        from: '243850000777',
        id: 'wamid.PDFFLYER',
        timestamp: '1',
        type: 'document',
        document: { id: 'media.flyer.1', mime_type: 'application/pdf', filename: 'annonce.pdf' },
      }],
    } }] }],
  });
  await settle(400);

  check('a PDF flyer with a real text layer does not crash the pipeline', () => {
    assert.strictEqual(pdfStatus, 200);
    assert.strictEqual(
      openaiCalls.length - pdfAiBefore,
      1,
      'the flyer never reached the model — processGroup threw before extraction',
    );
  });
  check("the flyer's text layer is what the model was asked about", () => {
    const parts = lastUserParts();
    const sent = typeof parts === 'string'
      ? parts
      : parts.map((p) => p.text || '').join('\n');
    assert.ok(/NGALIEMA/i.test(sent), `the PDF text never reached the model: ${sent.slice(0, 200)}`);
  });
  check('the flyer is stored as a real listing', () =>
    assert.strictEqual(dbService.countListings() - pdfRowsBefore, 1));
  check('the agent is answered rather than left in silence', () => {
    assert.ok(httpCalls.length >= 1, 'no reply was sent for a readable flyer');
    const replies = httpCalls.filter((c) => c.method === 'post' && c.data?.text?.body);
    assert.ok(replies.length >= 1, 'no text reply reached the agent');
    assert.ok(
      !replies.some((r) => r.data.text.body === webhookRouter.PDF_UNREADABLE_REPLY),
      'a readable flyer must never get the "send a photo instead" refusal',
    );
  });

  mediaBinaryResponse = savedMediaBytes;
  mediaContentType = savedMediaType;

  // -------------------------------------------------------------------------
  // 6a4. Voice notes — transcribed, then the ordinary pipeline
  // -------------------------------------------------------------------------

  console.log('\n6a4. Voice notes: download -> transcript -> extraction');

  const voiceNotesService = require('../services/voiceNotes');
  const voiceAiBefore = openaiCalls.length;
  const voiceRowsBefore = dbService.countListings();
  mediaBinaryResponse = Buffer.from('OggS-fake-opus');
  mediaContentType = 'audio/ogg';
  let transcribedMime = null;
  voiceNotesService.setTranscriber(async (buffer, mime) => {
    transcribedMime = mime;
    return { ok: true, text: 'Appartement à louer à Kintambo, deux chambres, 600 dollars, garantie trois plus un plus un' };
  });
  const voiceMessage = (wamid, from) => ({
    object: 'whatsapp_business_account',
    entry: [{ id: '1', changes: [{ field: 'messages', value: {
      metadata: { phone_number_id: '987654321' },
      contacts: [{ wa_id: from, profile: { name: 'Agent Vocal' } }],
      messages: [{ from, id: wamid, timestamp: '1', type: 'audio', audio: { id: 'media.voice.1', mime_type: 'audio/ogg; codecs=opus', voice: true } }],
    } }] }],
  });
  httpCalls.length = 0;
  await post('/webhook', voiceMessage('wamid.VOICE1', '243850000888'));
  await settle(500);

  check('a voice note is transcribed and extracted like typed text', () => {
    assert.ok(/audio\/ogg/.test(transcribedMime || ''), 'the audio reached the transcriber');
    assert.strictEqual(openaiCalls.length - voiceAiBefore, 1, 'the transcript reached the model');
    const parts = lastUserParts();
    const sent = typeof parts === 'string' ? parts : parts.map((p) => p.text || '').join('\n');
    assert.ok(/Kintambo/.test(sent), sent.slice(0, 200));
    assert.strictEqual(dbService.countListings() - voiceRowsBefore, 1);
  });
  check('a voice note is never answered with "format not supported"', () => {
    const bodies = httpCalls.filter((c) => c.data?.text?.body).map((c) => c.data.text.body);
    assert.ok(bodies.length >= 1);
    assert.ok(!bodies.some((b) => b === webhookRouter.UNSUPPORTED_MEDIA_REPLY));
  });

  voiceNotesService.setTranscriber(async () => ({ ok: false, reason: 'no_speech' }));
  httpCalls.length = 0;
  const silentAiBefore = openaiCalls.length;
  await post('/webhook', voiceMessage('wamid.VOICE2', '243850000889'));
  await settle(400);
  check('an inaudible voice note gets a clear ask, and costs no extraction', () => {
    assert.strictEqual(openaiCalls.length - silentAiBefore, 0);
    const bodies = httpCalls.filter((c) => c.data?.text?.body).map((c) => c.data.text.body);
    assert.ok(bodies.includes(webhookRouter.VOICE_UNREADABLE_REPLY), bodies.join(' | '));
  });
  voiceNotesService.setTranscriber(null);
  mediaBinaryResponse = savedMediaBytes;
  mediaContentType = savedMediaType;

  // -------------------------------------------------------------------------
  // 6b. Photo listings end-to-end
  // -------------------------------------------------------------------------

  console.log('\n6b. Photo listings: media download -> vision -> db -> reply');

  let rowsBeforeImg = dbService.countListings();
  let aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;

  await post('/webhook', inboundImage('wamid.PHOTO', 'media_777', 'Villa a louer Ngaliema'));
  await settle(600);

  check('downloads the media then calls gpt-4o once', () => {
    const gets = httpCalls.filter((c) => c.method === 'get');
    assert.strictEqual(gets.length, 1, 'expected a single one-hop download');
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 1);
  });
  check('sends the photo to the vision model as an image part', () => {
    const parts = lastUserParts();
    const imgs = parts.filter((p) => p.type === 'image_url');
    assert.strictEqual(imgs.length, 1);
    assert.strictEqual(imgs[0].image_url.url, `data:image/jpeg;base64,${REAL_JPEG_BYTES.toString('base64')}`);
  });
  check('passes the caption alongside the photo', () => {
    const parts = lastUserParts();
    assert.ok(parts[0].text.includes('Villa a louer Ngaliema'));
    assert.ok(/1 image\(s\)/.test(parts[0].text));
  });
  check('stores the photo listing', () =>
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 1));
  check('persists the downloaded photo and links its path to the listing', () => {
    const row = dbService.getRecentListings(1)[0];
    assert.strictEqual(row.photos.length, 1);
    assert.ok(row.photos[0].startsWith('/uploads/listings/'), row.photos[0]);
    assert.ok(
      fs.existsSync(path.join(mediaStorage.UPLOADS_ROOT, row.photos[0].replace('/uploads/', ''))),
      `${row.photos[0]} was not written to disk`,
    );
  });
  check('replies to the agent', () => {
    // A photo submission now gets two replies: the immediate burst-start ack
    // (fired at enqueue time, before extraction even runs), then the real
    // listing summary once gpt-4o/db work finishes — see routes/webhook.js's
    // enqueueMessage. Text-only messages (greetings, buyer chat) don't get
    // the ack — see the 'media' gate there — so this is specific to photo
    // submissions, not a change to every reply in this suite.
    const posts = httpCalls.filter((c) => c.method === 'post');
    assert.strictEqual(posts.length, 2, 'expected an immediate ack plus the real listing reply');
    assert.strictEqual(posts[0].data.to, '243850000000');
    assert.ok(posts[0].data.text.body.includes('Message reçu'), 'first post should be the burst-start ack');
    assert.strictEqual(posts[1].data.to, '243850000000');
  });

  // Photo with no caption at all — the case that used to be dropped entirely.
  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;
  await post('/webhook', inboundImage('wamid.NOCAPTION', 'media_888'));
  await settle(600);

  check('a caption-less photo still reaches the vision model', () => {
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 1);
    const parts = lastUserParts();
    assert.strictEqual(parts.filter((p) => p.type === 'image_url').length, 1);
    assert.ok(/images uniquement/.test(parts[0].text));
  });
  check('caption-less photo is stored and answered', () => {
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 1);
    assert.strictEqual(httpCalls.filter((c) => c.method === 'post').length, 1);
  });

  // Download fails but there IS a caption: degrade to text-only rather than drop.
  mediaDownloadError = true;
  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;
  await post('/webhook', inboundImage('wamid.BADMEDIA', 'media_gone', 'Villa Gombe 1800$'));
  await settle(600);

  check('failed download degrades to caption-only extraction', () => {
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 1, 'should still call the model');
    const parts = lastUserParts();
    assert.strictEqual(parts.filter((p) => p.type === 'image_url').length, 0);
    assert.ok(parts[0].text.includes('Villa Gombe 1800$'));
  });
  check('caption-only fallback still stores and replies', () => {
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 1);
    assert.strictEqual(httpCalls.filter((c) => c.method === 'post').length, 1);
  });

  // Download fails and there is NO caption: nothing to read, skip cleanly.
  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;
  await post('/webhook', inboundImage('wamid.HOPELESS', 'media_gone2'));
  await settle(600);

  check('unreadable photo with no caption makes no gpt-4o call', () => {
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 0);
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 0);
    assert.strictEqual(httpCalls.filter((c) => c.method === 'post').length, 0);
  });
  mediaDownloadError = null;

  // Redelivered photo must not re-download or re-bill.
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;
  await post('/webhook', inboundImage('wamid.PHOTO', 'media_777', 'Villa a louer Ngaliema'));
  await settle(400);
  check('redelivered photo skips download, model and reply', () => {
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 0);
    assert.strictEqual(httpCalls.length, 0, 'no HTTP calls at all');
  });

  // -------------------------------------------------------------------------
  // 6c. Photo burst grouping
  // -------------------------------------------------------------------------

  console.log('\n6c. Burst grouping: 4 photos -> one listing');

  function burstPhoto(wamid, mediaId, caption) {
    return inboundImage(wamid, mediaId, caption);
  }

  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;

  // Caption on the first photo only, as agents usually send it.
  await post('/webhook', burstPhoto('wamid.B1', 'media_b1', 'Villa a louer Ma Campagne 2500$/mois'));
  await settle(40);
  await post('/webhook', burstPhoto('wamid.B2', 'media_b2'));
  await settle(40);
  await post('/webhook', burstPhoto('wamid.B3', 'media_b3'));
  await settle(40);
  await post('/webhook', burstPhoto('wamid.B4', 'media_b4'));
  await settle(900);   // let the idle window close and processing finish

  check('4 photos become ONE gpt-4o call', () =>
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 1));
  check('4 photos become ONE database row', () =>
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 1));
  check('4 photos get ONE reply', () =>
    assert.strictEqual(httpCalls.filter((c) => c.method === 'post').length, 1));
  check('all 4 images are sent to the vision model together', () => {
    const parts = lastUserParts();
    assert.strictEqual(parts.filter((p) => p.type === 'image_url').length, 4);
    assert.ok(/4 image\(s\)/.test(parts[0].text));
  });
  check("the first photo's caption is used for the group", () => {
    const parts = lastUserParts();
    assert.ok(parts[0].text.includes('Villa a louer Ma Campagne 2500$/mois'));
  });

  const burstRow = dbService.getRecentListings(1)[0];
  check('row records every wamid in the burst', () => {
    assert.strictEqual(burstRow.wamid, 'wamid.B1');
    assert.deepStrictEqual(burstRow.group_wamids, ['wamid.B1', 'wamid.B2', 'wamid.B3', 'wamid.B4']);
  });
  check('findByWamid matches a NON-primary id from the burst', () => {
    for (const id of ['wamid.B2', 'wamid.B3', 'wamid.B4']) {
      const found = dbService.findByWamid(id);
      assert.ok(found, `${id} should resolve to the stored listing`);
      assert.strictEqual(found.id, burstRow.id);
    }
  });
  check('findByWamid still returns undefined for an unrelated id', () =>
    assert.strictEqual(dbService.findByWamid('wamid.NEVER_SEEN'), undefined));

  // The whole point: redelivery of photo #3 must not create a second listing.
  aiBeforeImg = openaiCalls.length;
  rowsBeforeImg = dbService.countListings();
  httpCalls.length = 0;
  await post('/webhook', burstPhoto('wamid.B3', 'media_b3'));
  await settle(600);
  check('redelivery of a non-primary burst photo is ignored', () => {
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 0);
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 0);
    assert.strictEqual(httpCalls.length, 0);
  });

  // Text then photos: the typed listing and its pictures belong together.
  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;
  // Same sender for both, or they are two separate listings by definition.
  await post('/webhook', inbound('wamid.T1', 'Studio a louer Lemba 400$/mois', '243850000000'));
  await settle(40);
  await post('/webhook', burstPhoto('wamid.T2', 'media_t2'));
  await settle(900);
  check('a text message and following photos merge into one listing', () => {
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 1);
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 1);
    const parts = lastUserParts();
    assert.ok(parts[0].text.includes('Studio a louer Lemba'));
    assert.strictEqual(parts.filter((p) => p.type === 'image_url').length, 1);
  });

  // Two different senders must never be merged with each other.
  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;
  await post('/webhook', inbound('wamid.S1', 'Villa Gombe 1800$'));            // 243840000000
  await post('/webhook', burstPhoto('wamid.S2', 'media_s2', 'Parcelle Limete')); // 243850000000
  await settle(900);
  check('separate senders produce separate listings', () => {
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 2);
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 2);
    assert.strictEqual(httpCalls.filter((c) => c.method === 'post').length, 2);
  });

  // Max-wait ceiling: a slow trickle still gets flushed.
  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  const trickleStart = Date.now();
  await post('/webhook', burstPhoto('wamid.M1', 'media_m1', 'Villa Ngaliema'));
  for (let i = 0; i < 20; i += 1) {
    await settle(90);   // keep re-arming the 120ms idle timer
    await post('/webhook', burstPhoto(`wamid.M${i + 2}`, `media_m${i + 2}`));
  }
  await settle(700);
  check('max-wait ceiling flushes a continuous trickle', () => {
    assert.ok(openaiCalls.length - aiBeforeImg >= 1, 'nothing was ever flushed');
    assert.strictEqual(dbService.countListings() - rowsBeforeImg >= 1, true);
    assert.ok(
      Date.now() - trickleStart < 6000,
      'flush took far longer than the 1200ms max-wait allows',
    );
  });
  check('the image cap still applies to a large burst', () => {
    const parts = lastUserParts();
    assert.ok(
      parts.filter((p) => p.type === 'image_url').length <= openaiService.MAX_IMAGES,
      'a burst must not exceed MAX_IMAGES',
    );
  });

  // Grouping disabled -> immediate processing, one row per message.
  process.env.GROUP_IDLE_MS = '0';
  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  await post('/webhook', inbound('wamid.D1', 'Villa Gombe 1000$'));
  await settle(400);
  check('GROUP_IDLE_MS=0 processes immediately without buffering', () => {
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 1);
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 1);
  });
  // An "OK" to a pending draft is answered at once, not after the idle wait.
  process.env.GROUP_IDLE_MS = '5000';
  httpCalls.length = 0;
  aiBeforeImg = openaiCalls.length;
  await post('/webhook', inbound('wamid.OK1', 'OK'));
  await settle(400);
  check('an OK to a draft skips the burst wait and makes no model call', () => {
    assert.strictEqual(httpCalls.filter((c) => c.method === 'post').length, 1, 'no reply within 400ms of a 5s idle window');
    assert.strictEqual(openaiCalls.length, aiBeforeImg);
  });
  process.env.GROUP_IDLE_MS = '120';

  check('flushAll is exported for graceful shutdown', () =>
    assert.strictEqual(typeof webhookRouter.flushAll, 'function'));

  // -------------------------------------------------------------------------
  // 6d. Chakra's real envelope, end to end
  // -------------------------------------------------------------------------

  console.log("\n6d. message.received envelope through the whole pipeline");

  // Mirrors the live payload captured from Chakra.
  function chakraEvent(id, text, messageExtra = {}) {
    return {
      event: 'message',
      payload: {
        wabaId: '2745491532518223',
        messageId: id,
        externalId: id,
        timestamp: 1786649606000,
        message: {
          from: '+243860000000',
          id,
          timestamp: '1786649606',
          type: messageExtra.image ? 'image' : 'text',
          ...(text ? { text: { body: text } } : {}),
          ...messageExtra,
        },
        contacts: [{ profile: { name: 'Agent Chakra' }, wa_id: '243860000000' }],
      },
    };
  }

  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;

  await post('/webhook', chakraEvent('wamid.CE1', 'Villa a louer Gombe 1800$/mois 3 chambres'));
  await settle(700);

  check("event:'message' reaches the model and is stored", () => {
    assert.strictEqual(openaiCalls.length - aiBeforeImg, 1);
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 1);
  });
  check("sender is normalised without the '+' in the stored row", () => {
    const row = dbService.getRecentListings(1)[0];
    assert.strictEqual(row.wa_id, '243860000000');
    assert.strictEqual(row.wamid, 'wamid.CE1');
    assert.strictEqual(row.agent_name, 'Agent Chakra');
  });
  check('reply is addressed to the msisdn', () => {
    const posts = httpCalls.filter((c) => c.method === 'post');
    assert.strictEqual(posts.length, 1);
    assert.strictEqual(posts[0].data.to, '243860000000');
  });
  await checkAsync('redelivery of the same messageId is deduped', async () => {
    const before = openaiCalls.length;
    await post('/webhook', chakraEvent('wamid.CE1', 'Villa a louer Gombe 1800$/mois 3 chambres'));
    await settle(600);
    assert.strictEqual(openaiCalls.length - before, 0);
  });

  // Real image event: id AND a signed lookaside URL. The URL (proxied through
  // Chakra by its `mid`) should be used, not the two-hop by-id route.
  const LOOKASIDE_URL = 'https://lookaside.fbsbx.com/whatsapp_business/attachments/?mid=2565531760616440';
  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;
  await post(
    '/webhook',
    chakraEvent('wamid.CE2', null, {
      image: {
        id: '2565531760616440',
        mime_type: 'image/jpeg',
        url: LOOKASIDE_URL,
      },
    }),
  );
  await settle(700);

  check('the direct media URL is fetched in ONE authenticated hop', () => {
    const gets = httpCalls.filter((c) => c.method === 'get');
    assert.strictEqual(gets.length, 1, 'should not use the media-id route');
    assert.strictEqual(gets[0].url, chakra.mediaAttachmentUrl('2565531760616440'));
    assert.strictEqual(gets[0].config.headers.Authorization, 'Bearer chakra-test-token');
  });
  check('the fetched photo reaches the vision model as base64', () => {
    const parts = lastUserParts();
    const imgs = parts.filter((p) => p.type === 'image_url');
    assert.strictEqual(imgs.length, 1);
    assert.strictEqual(
      imgs[0].image_url.url,
      `data:image/jpeg;base64,${REAL_JPEG_BYTES.toString('base64')}`,
    );
  });
  check('caption-less photo event is stored and answered', () => {
    assert.strictEqual(dbService.countListings() - rowsBeforeImg, 1);
    assert.strictEqual(httpCalls.filter((c) => c.method === 'post').length, 1);
  });

  // If the signed URL fails, fall back to the media-id route rather than lose it.
  const savedDownloadError = mediaDownloadError;
  rowsBeforeImg = dbService.countListings();
  aiBeforeImg = openaiCalls.length;
  httpCalls.length = 0;
  mediaDownloadError = null;
  await post(
    '/webhook',
    chakraEvent('wamid.CE3', 'Villa avec piscine', {
      image: { id: '999', mime_type: 'image/jpeg', url: 'https://lookaside.fbsbx.example/forbidden' },
    }),
  );
  await settle(800);
  check('a failing direct URL falls back to the media-id route', () => {
    const gets = httpCalls.filter((c) => c.method === 'get');
    // no `mid` in this fixture -> direct fetch attempted -> fails -> one-hop by-id fallback
    assert.strictEqual(gets.length, 2, `expected a fallback download, saw ${gets.length} GETs`);
    const parts = lastUserParts();
    assert.strictEqual(parts.filter((p) => p.type === 'image_url').length, 1);
  });
  mediaDownloadError = savedDownloadError;

  // -------------------------------------------------------------------------
  // 6e. Conversational edit loop, end to end
  //
  // The regression that started this: a correction was answered with "envoyez
  // l'annonce avec le type de bien, la commune..." — a rejection — even though
  // the merge had actually worked. Plus the confirmation fallback: a plain 'OK'
  // must still publish with no model call, while "c'est bon, publiez" now
  // publishes via the model's is_confirmed verdict.
  // -------------------------------------------------------------------------

  console.log('\n6e. End-to-end conversational edit loop + confirmation fallback');

  const loopE2EWaId = '243940000007';

  /** One canned intake completion, with the full extracted_data shape. */
  function intakeCompletion(extractedOverrides, reply) {
    return {
      model: 'gpt-4o-2024-08-06',
      usage: { prompt_tokens: 900, completion_tokens: 180, total_tokens: 1080 },
      choices: [{ finish_reason: 'stop', message: { refusal: null, content: JSON.stringify({
        extracted_data: {
          is_listing: false,
          is_confirmed: false,
          intent: 'listing',
          transaction_type: 'location',
          property_type: 'villa',
          parcelle_subtype: null,
          commune: 'Ngaliema',
          quartier: 'Macampagne',
          price: 1200,
          currency: 'USD',
          price_period: 'mois',
          deposit_months: 3,
          advance_months: 1,
          commission_months: 1,
          bedrooms: 3,
          bathrooms: 2,
          surface_area_sqm: null,
          units_count: null,
          furnished: null,
          amenities: [],
          reference: null,
          agent_name: null,
          agency_name: null,
          summary_fr: 'Villa 3 chambres à Macampagne.',
          missing_fields: [],
          confidence: 0.9,
          ...extractedOverrides,
        },
        whatsapp_reply: reply,
      }) } }],
    };
  }

  // Turn 1 — the original submission.
  completionQueue.push(intakeCompletion(
    { is_listing: true },
    'Voici les informations extraites :\n*Loyer* : 1200$ mois\n*Chambres* : 3\nRépondez *OK* pour publier.',
  ));
  await post('/webhook', inbound('wamid.LOOPE2E0', 'Villa Macampagne 3ch 1200$/mois', loopE2EWaId));
  await settle(400);

  const e2eDraft = dbService.findLatestPendingListing(loopE2EWaId);
  check('setup: turn 1 leaves a real pending draft', () => assert.ok(e2eDraft));

  // Turn 2 — a bare price correction, the exact shape that used to be rejected.
  const rowsBeforeEdit = dbService.countListings();
  httpCalls.length = 0;
  completionQueue.push(intakeCompletion(
    { price: 1100, summary_fr: 'Villa 3 chambres à Macampagne, 1100 USD/mois.' },
    'C\'est noté ✅\n*Loyer* : 1100$ mois\n*Chambres* : 3\n*Garantie* : 3 mois (3300 $)\nRépondez *OK* pour publier.',
  ));
  await post('/webhook', inbound('wamid.LOOPE2E1', "Non pas 1200$ c'est 1100$", loopE2EWaId));
  await settle(400);

  const editCall = openaiCalls[openaiCalls.length - 1];
  check('the correction reaches the model WITH the pending draft attached', () => {
    assert.strictEqual(editCall.messages[1].role, 'system');
    assert.ok(editCall.messages[1].content.includes('annonce déjà enregistrée'));
    assert.ok(editCall.messages[1].content.includes('"price":1200'), 'the draft must carry the pre-correction price');
  });
  check('a bare correction amends the draft instead of opening a second one', () => {
    assert.strictEqual(dbService.countListings(), rowsBeforeEdit);
    assert.strictEqual(dbService.getListing(e2eDraft.id).price, 1100);
  });
  check('the agent gets the re-rendered summary, NOT the "send me a listing" rejection', () => {
    assert.strictEqual(httpCalls.length, 1);
    const body = httpCalls[0].data.text.body;
    assert.ok(body.includes('1100'), 'the reply must show the corrected value back');
    assert.ok(
      !/envoyez l'annonce avec le type de bien/i.test(body),
      'this is the regression: a working correction answered as if the message were junk',
    );
  });
  check('the draft is still pending after a correction — the loop stays open', () =>
    assert.strictEqual(dbService.getListing(e2eDraft.id).status, 'pending_confirmation'));

  // Turn 3 — approval wording carrying a real change. Must NOT publish.
  httpCalls.length = 0;
  completionQueue.push(intakeCompletion(
    { price: 1100, bedrooms: 4, is_confirmed: false },
    'Mise à jour ✅\n*Loyer* : 1100$ mois\n*Chambres* : 4\nRépondez *OK* pour publier.',
  ));
  await post('/webhook', inbound('wamid.LOOPE2E2', 'ok mais 4 chambres', loopE2EWaId));
  await settle(400);

  check('"ok mais 4 chambres" is a correction, not a confirmation', () => {
    const row = dbService.getListing(e2eDraft.id);
    assert.strictEqual(row.status, 'pending_confirmation', 'must not publish');
    assert.strictEqual(row.bedrooms, 4, 'the correction inside it must still land');
  });
  check('the agent gets the updated card back, not a publication notice', () => {
    assert.strictEqual(httpCalls.length, 1);
    assert.doesNotMatch(httpCalls[0].data.text.body, /^✅ \*Annonce bien reçue et en cours de modération !\*\n• /);
  });

  // Turn 4 — conversational approval. The model fallback publishes.
  httpCalls.length = 0;
  attachPhoto(e2eDraft.id, 'loop');
  completionQueue.push(intakeCompletion(
    { price: 1100, bedrooms: 4, is_confirmed: true },
    'Parfait, je publie.',
  ));
  await post('/webhook', inbound('wamid.LOOPE2E3', "c'est bon vous pouvez mettre en ligne svp", loopE2EWaId));
  await settle(400);

  check('is_confirmed publishes the pending draft', () =>
    assert.strictEqual(dbService.getListing(e2eDraft.id).status, 'published'));
  check('a conversational confirmation gets the same published reply as "OK"', () => {
    assert.strictEqual(httpCalls.length, 1);
    assert.match(httpCalls[0].data.text.body, /^✅ \*Annonce bien reçue et en cours de modération !\*\n• /);
  });
  check('the published listing kept every correction from the loop', () => {
    const row = dbService.getListing(e2eDraft.id);
    assert.strictEqual(row.price, 1100);
    assert.strictEqual(row.bedrooms, 4);
    assert.strictEqual(row.commune, 'Ngaliema', 'untouched fields survived the whole conversation');
  });

  // The regex fast path must be exactly as it was: no model call at all.
  completionQueue.push(intakeCompletion(
    { is_listing: true },
    'Voici les informations extraites :\n*Loyer* : 800$ mois\nRépondez *OK* pour publier.',
  ));
  await post('/webhook', inbound('wamid.LOOPE2E4', 'Appartement Kalamu 800$/mois', loopE2EWaId));
  await settle(400);
  const regexDraft = dbService.findLatestPendingListing(loopE2EWaId);

  attachPhoto(regexDraft.id, 'regex');
  const aiBeforeRegex = openaiCalls.length;
  httpCalls.length = 0;
  await post('/webhook', inbound('wamid.LOOPE2E5', 'OK', loopE2EWaId));
  await settle(400);

  check('a plain "OK" still publishes with zero model calls — the fast path is intact', () => {
    assert.strictEqual(openaiCalls.length - aiBeforeRegex, 0);
    assert.strictEqual(dbService.getListing(regexDraft.id).status, 'published');
    assert.match(httpCalls[0].data.text.body, /^✅ \*Annonce bien reçue et en cours de modération !\*\n• /);
  });

  // -------------------------------------------------------------------------
  // 6f. Mandatory photo gate on every confirmation path
  //
  // A storefront card with no image is worse than no card. All three publish
  // paths refuse: the regex 'OK', the conversational is_confirmed fallback,
  // and agent onboarding (where answering the name question is the
  // confirmation). In every case the draft STAYS pending — refusing must not
  // cost the agent the listing they already sent.
  // -------------------------------------------------------------------------

  console.log('\n6f. Mandatory photo enforcement (WhatsApp intake)');

  const noPhotoWaId = '243950000011';
  completionQueue.push(intakeCompletion(
    { is_listing: true },
    'Voici les informations extraites :\n*Loyer* : 900$ mois\nRépondez *OK* pour publier.',
  ));
  await post('/webhook', inbound('wamid.NOPIC0', 'Villa Kalamu 3ch 900$/mois', noPhotoWaId));
  await settle(400);

  const noPhotoDraft = dbService.findLatestPendingListing(noPhotoWaId);
  check('setup: a text-only listing is still accepted and stored', () => {
    assert.ok(noPhotoDraft, 'a listing with no photo must still be RECEIVED');
    assert.deepStrictEqual(noPhotoDraft.photos, [], 'and it genuinely has no photos');
  });

  httpCalls.length = 0;
  const aiBeforeNoPhotoOk = openaiCalls.length;
  await post('/webhook', inbound('wamid.NOPIC1', 'OK', noPhotoWaId));
  await settle(400);

  check('a plain "OK" on a photoless draft does NOT publish', () =>
    assert.strictEqual(dbService.getListing(noPhotoDraft.id).status, 'pending_confirmation'));
  check('the agent is told a photo is required, in the exact agreed wording', () => {
    assert.strictEqual(httpCalls.length, 1);
    assert.strictEqual(httpCalls[0].data.text.body, webhookRouter.PHOTO_REQUIRED_REPLY);
    assert.ok(httpCalls[0].data.text.body.includes('Photo ou vidéo obligatoire'));
  });
  check('refusing costs no model call — the regex path is still free', () =>
    assert.strictEqual(openaiCalls.length - aiBeforeNoPhotoOk, 0));

  // The conversational path must refuse identically, not slip through.
  httpCalls.length = 0;
  completionQueue.push(intakeCompletion({ is_confirmed: true }, 'Parfait, je publie.'));
  await post('/webhook', inbound('wamid.NOPIC2', "c'est bon vous pouvez mettre en ligne svp", noPhotoWaId));
  await settle(400);

  check('is_confirmed cannot bypass the photo gate either', () => {
    assert.strictEqual(dbService.getListing(noPhotoDraft.id).status, 'pending_confirmation');
    assert.strictEqual(httpCalls[0].data.text.body, webhookRouter.PHOTO_REQUIRED_REPLY);
  });

  // The model is told how many photos the draft has, so it can refuse itself.
  const photoCtxCall = openaiCalls[openaiCalls.length - 1];
  check('the draft context reports photos_count so the model can refuse too', () =>
    assert.ok(photoCtxCall.messages[1].content.includes('"photos_count":0')));
  check('the prompt carries the mandatory-photo rule', () =>
    assert.ok(openaiService.SYSTEM_PROMPT.includes('PHOTO OU VIDÉO OBLIGATOIRE')));

  // Sending the photo unblocks it — the draft was never lost.
  httpCalls.length = 0;
  check('the draft survived both refusals intact, still pending and still complete', () => {
    const stillThere = dbService.getListing(noPhotoDraft.id);
    assert.strictEqual(stillThere.status, 'pending_confirmation');
    assert.strictEqual(stillThere.price, 1200, 'the draft kept its data through two refusals');
  });

  // Sending the photo WITH the confirmation unblocks it — the agent should not
  // have to send the photo, then say OK a second time.
  httpCalls.length = 0;
  await post('/webhook', inboundImage('wamid.NOPIC3', 'media_777', 'OK', noPhotoWaId));
  await settle(800);

  check('a photo arriving WITH the "OK" is attached and the listing publishes', () => {
    const row = dbService.getListing(noPhotoDraft.id);
    assert.ok(row.photos.length > 0, 'the photo sent with the OK must be stored on the draft');
    assert.strictEqual(row.status, 'published');
    assert.match(httpCalls[httpCalls.length - 1].data.text.body, /^✅ \*Annonce bien reçue et en cours de modération !\*\n• /);
  });

  // -------------------------------------------------------------------------
  // 6g. Multi-unit building, end to end
  //
  // The screenshot case: one paste, four apartments, four prices. Before this
  // the engine replied with a single listing at $600/2 bedrooms and silently
  // dropped the other three.
  // -------------------------------------------------------------------------

  console.log('\n6g. End-to-end multi-unit building paste');

  const bldWaId = '243970000031';
  const bldUnits = [
    { bedrooms: 3, bathrooms: 3, price: 1500, price_period: 'mois', surface_area_sqm: null,
      floor: 'Étage élevé', furnished: null, amenities: ['balcon', 'climatisation'],
      quantity: null, summary_fr: '3 ch / 3 sdb.' },
    { bedrooms: 3, bathrooms: 1, price: 900, price_period: 'mois', surface_area_sqm: null,
      floor: null, furnished: null, amenities: ['parking'], quantity: null, summary_fr: '3 ch / 1 sdb.' },
    { bedrooms: 2, bathrooms: 2, price: 700, price_period: 'mois', surface_area_sqm: null,
      floor: null, furnished: null, amenities: [], quantity: 3, summary_fr: '2 ch / 2 sdb.' },
    { bedrooms: 2, bathrooms: 1, price: 600, price_period: 'mois', surface_area_sqm: null,
      floor: 'Rez-de-chaussée', furnished: null, amenities: [], quantity: null, summary_fr: '2 ch / 1 sdb.' },
  ];

  completionQueue.push(intakeCompletion(
    {
      is_listing: true, property_type: 'appartement', commune: 'Kasa-Vubu', quartier: 'Salongo',
      price: 600, bedrooms: 2, bathrooms: 1,
      is_multi_unit: true, building_name: 'Résidence Kin Marché', units: bldUnits,
    },
    'Résidence Kin Marché (Kasa-Vubu)\n🏢 4 typologies d\'appartements détectées :\n\n'
      + '1️⃣ 3 Chambres / 3 Salles de bain — 1500$\n2️⃣ 3 Chambres / 1 Salle de bain — 900$ (Parking)\n'
      + '3️⃣ 2 Chambres / 2 Salles de bain — 700$ (3 unités disponibles)\n'
      + '4️⃣ 2 Chambres / 1 Salle de bain — 600$ (Rez-de-chaussée)\n\n'
      + 'Répondez "OK" pour publier ces 4 annonces liées.',
  ));
  httpCalls.length = 0;
  await post('/webhook', inbound(
    'wamid.BLDE2E0',
    'Résidence Kin Marché Kasa-Vubu: 3 chambres 1500$, 3 chambres 900$, 2 chambres 700$, 2 chambres 600$',
    bldWaId,
  ));
  await settle(400);

  const bldDraft = dbService.findLatestPendingListing(bldWaId);
  check('a multi-unit paste is stored as ONE pending draft carrying all four units', () => {
    assert.ok(bldDraft);
    assert.strictEqual(bldDraft.parsed_json.is_multi_unit, true);
    assert.strictEqual(bldDraft.parsed_json.units.length, 4);
  });
  check('the agent gets an itemised recap, not a single collapsed listing', () => {
    const body = httpCalls[0].data.text.body;
    for (const needle of ['4 typologies', '1500$', '900$', '700$', '600$', '4 annonces liées']) {
      assert.ok(body.includes(needle), `recap missing "${needle}"`);
    }
  });

  attachPhoto(bldDraft.id, 'building');
  const rowsBeforeBldOk = dbService.countListings();
  httpCalls.length = 0;
  await post('/webhook', inbound('wamid.BLDE2E1', 'OK', bldWaId));
  await settle(600);

  check('confirming publishes FOUR linked listings from one message', () => {
    assert.strictEqual(dbService.countListings(), rowsBeforeBldOk + 3);
    assert.strictEqual(dbService.getListing(bldDraft.id).status, 'published');
    assert.ok(dbService.getListing(bldDraft.id).parent_building_id, 'the draft is now unit #1 of a building');
  });
  const bldReceipt = httpCalls[httpCalls.length - 1].data.text.body;
  check('the confirmation says four annonces and lists each one', () => {
    assert.match(bldReceipt, /^✅ \*4 annonces bien reçues et en cours de modération !\*/);
    for (const n of [1, 2, 3, 4]) assert.match(bldReceipt, new RegExp(`\\n${n}\\. Appartement à `));
    assert.doesNotMatch(bldReceipt, /\n5\. /);
  });
  check('with no listing to name, the receipt falls back to the original wording', () =>
    assert.strictEqual(webhookRouter.publishedReply([]), webhookRouter.PUBLISHED_REPLY));
  check('the confirmation never claims the listing is already visible (it waits for moderation)', () => {
    for (const body of [bldReceipt, webhookRouter.PUBLISHED_REPLY]) {
      assert.ok(!/visible|publiée|publiées/i.test(body), body);
      assert.ok(/modération|après validation/.test(body), body);
    }
  });

  // -------------------------------------------------------------------------
  // 7. Read API still serves what the pipeline wrote
  // -------------------------------------------------------------------------

  console.log('\n7. GET /listings reflects pipeline writes');

  function getListings(headers = {}) {
    return new Promise((resolve) => {
      http.get(
        { host: 'localhost', port: 3200, path: '/listings?commune=Ngaliema&limit=100', headers },
        (res) => {
          let b = '';
          res.on('data', (c) => (b += c));
          res.on('end', () => resolve({ status: res.statusCode, body: b ? JSON.parse(b) : null }));
        },
      );
    });
  }

  const noKey = await getListings();
  check('rejects a request with no API key', () => assert.strictEqual(noKey.status, 401));

  const wrongKey = await getListings({ 'X-API-Key': 'not-the-real-key' });
  check('rejects a request with the wrong API key', () => assert.strictEqual(wrongKey.status, 401));

  const bearerForm = await getListings({ Authorization: `Bearer ${process.env.API_SECRET}` });
  check('accepts the key via Authorization: Bearer too', () => assert.strictEqual(bearerForm.status, 200));

  const listedResponse = await getListings({ 'X-API-Key': process.env.API_SECRET });
  const listed = listedResponse.body;
  check('returns the paginated envelope', () => {
    assert.strictEqual(listedResponse.status, 200);
    assert.strictEqual(listed.success, true);
    assert.ok(typeof listed.total === 'number');
    assert.strictEqual(listed.limit, 100);
    assert.strictEqual(listed.offset, 0);
  });
  check('includes rows written by the Chakra pipeline', () =>
    assert.ok(listed.data.some((d) => d.wamid === 'wamid.E2E')));

  // -------------------------------------------------------------------------
  // 8. GET /locations — commune/quartier hierarchy for cascading selects
  // -------------------------------------------------------------------------

  console.log('\n8. GET /locations');

  function getJSON(pathname) {
    return new Promise((resolve) => {
      http.get({ host: 'localhost', port: 3200, path: pathname }, (res) => {
        let b = '';
        res.on('data', (c) => (b += c));
        res.on('end', () => resolve({ status: res.statusCode, body: b ? JSON.parse(b) : null }));
      });
    });
  }

  const allLocations = await getJSON('/locations');
  check('GET /locations returns 200 with no auth required (reference data, like /uploads)', () =>
    assert.strictEqual(allLocations.status, 200));
  check('GET /locations returns all 24 communes and the full hierarchy', () => {
    assert.strictEqual(allLocations.body.success, true);
    assert.strictEqual(allLocations.body.communes.length, 24);
    assert.deepStrictEqual(allLocations.body.locations.Ngaliema, locationsService.LOCATIONS.Ngaliema);
  });

  const ngaliemaQuartiers = await getJSON('/locations/Ngaliema/quartiers');
  check('GET /locations/:commune/quartiers returns that commune\'s exact list', () => {
    assert.strictEqual(ngaliemaQuartiers.status, 200);
    assert.strictEqual(ngaliemaQuartiers.body.commune, 'Ngaliema');
    assert.ok(ngaliemaQuartiers.body.quartiers.includes('Macampagne'));
  });

