    assert.strictEqual(simpleTurn.reply, 'Bonjour ! Quel budget souhaitez-vous prévoir ?');
    assert.strictEqual(simpleTurn.iterations, 1);
    assert.deepStrictEqual(simpleTurn.toolCalls, []);
