  // ===========================================================================
  console.log('\n18. Daily alert scheduler (services/scheduler.js)');
  // ===========================================================================
  //
  // Daily since saved searches carry their own frequency (daily / weekly /
  // off); the web sweep decides per search whether it is due.

  const scheduler = require('../services/scheduler');

  check('the sweep fires in its configured hour, on any day', () => {
    const when = new Date();
    // Walk forward to the configured hour so this does not depend on when the
    // suite happens to run.
    while (when.getHours() !== scheduler.ALERT_HOUR) when.setHours(when.getHours() + 1);
    assert.strictEqual(scheduler.shouldRunNow(when), true);
    const nextDay = new Date(when);
    nextDay.setDate(nextDay.getDate() + 1);
    assert.strictEqual(scheduler.shouldRunNow(nextDay), true, 'a weekly day gate would silence "chaque jour"');
  });

  check('it does not fire outside that hour', () => {
    const when = new Date();
    while (when.getHours() === scheduler.ALERT_HOUR) when.setHours(when.getHours() + 1);
    assert.strictEqual(scheduler.shouldRunNow(when), false);
  });

  check('a successful run blocks a second sweep inside the same window', () => {
    dbService.recordJobRun(scheduler.JOB_NAME, { ok: true, detail: '{}' });
    const when = new Date();
    while (when.getHours() !== scheduler.ALERT_HOUR) when.setHours(when.getHours() + 1);
    assert.strictEqual(
      scheduler.shouldRunNow(when),
      false,
      'a deploy landing inside the firing window must not re-send every customer their alerts',
    );
    assert.ok(scheduler.MIN_GAP_MS >= 20 * 60 * 60 * 1000, 'the gap must outlast the firing hour by far');
  });

  await checkAsync('the sweep follows the web cursor chunk by chunk until done', async () => {
    const saved = process.env.CRON_SECRET;
    process.env.CRON_SECRET = 'verify-cron-secret';
    const sentCursors = [];
    const pages = [
      { done: false, cursor: 200, checked: 200, notifiedSearches: 3, notifiedListings: 5, errors: [] },
      { done: true, cursor: null, checked: 40, notifiedSearches: 1, notifiedListings: 1, errors: [{ savedSearchId: 9 }] },
    ];
    const fakeFetch = async (url, init) => {
      sentCursors.push(JSON.parse(init.body).cursor);
      return { ok: true, status: 200, json: async () => pages.shift() };
    };
    try {
      const totals = await scheduler.runSearchAlertSweep({ fetchImpl: fakeFetch });
      assert.deepStrictEqual(sentCursors, [null, 200]);
      assert.deepStrictEqual(totals, { chunks: 2, checked: 240, notifiedSearches: 4, notifiedListings: 6, errors: 1 });
    } finally {
      process.env.CRON_SECRET = saved;
    }
  });

  await checkAsync('a cursor that does not advance ends the sweep instead of looping', async () => {
    const saved = process.env.CRON_SECRET;
    process.env.CRON_SECRET = 'verify-cron-secret';
    let calls = 0;
    const stuck = async () => {
      calls += 1;
      return { ok: true, status: 200, json: async () => ({ done: false, cursor: 7, checked: 1 }) };
    };
    try {
      await scheduler.runSearchAlertSweep({ fetchImpl: stuck });
      assert.strictEqual(calls, 2);
    } finally {
      process.env.CRON_SECRET = saved;
    }
  });

  check('a FAILED run does not count as having run — the next tick retries', () => {
    // Reset to a clean slate, then record only a failure.
    dbService.recordJobRun('scheduler-failure-probe', { ok: false, detail: 'boom' });
    const probe = dbService.getLastJobRun('scheduler-failure-probe');
    assert.strictEqual(probe.succeeded_at, null);
    assert.match(probe.last_error, /boom/);
  });

  await checkAsync('the sweep refuses to run without CRON_SECRET rather than calling an open endpoint', async () => {
    const saved = process.env.CRON_SECRET;
    process.env.CRON_SECRET = '';
    await assert.rejects(() => scheduler.runSearchAlertSweep(), /CRON_SECRET/);
    process.env.CRON_SECRET = saved;
  });

  // ===========================================================================
  // 19. Auto-attribution of an incoming listing to a recognised agent
  //     (services/agentOnboarding.js's identifySender + routes/webhook.js)
  // ===========================================================================

  console.log('\n19. Auto-attribution of incoming listings to a recognised agent');

  // --- The identity decision itself -----------------------------------------

  const VERIFIED_AGENT = {
    id: '91',
    username: '243997123456',
    phone: '+243 997-123-456',
    phone_verified_at: '2026-08-01T09:00:00.000Z',
    agency_name: 'Agence Horizon',
    first_name: 'Sarah',
  };

  check('a phone-verified agent is recognised, with a numeric agents.id and a first name', () => {
    const identity = onboarding.senderIdentityFrom(VERIFIED_AGENT);
    assert.strictEqual(identity.registered, true);
    // Postgres hands bigint ids back as strings; properties.agent_id and the
    // local agent_id column are both numeric, so this must not stay '91'.
    assert.strictEqual(identity.agentId, 91);
    assert.strictEqual(identity.firstName, 'Sarah');
  });

  // The same gate services/postgres.js's resolveAgentId applies (section 3c).
  // The two have to agree: telling an agent their listing is linked to their
  // account is a promise the sync then has to keep, and resolveAgentId refuses
  // an unverified account.
  check('an existing but UNVERIFIED account is not recognised and claims nothing', () => {
    const identity = onboarding.senderIdentityFrom({ ...VERIFIED_AGENT, phone_verified_at: null });
    assert.strictEqual(identity.registered, false);
    assert.strictEqual(identity.agentId, null);
    // Still handed back, so shouldOnboard() knows not to ask them to register again.
    assert.ok(identity.agent, 'the row itself must still be reported');
  });

  check('a sender with no account at all is simply unknown', () => {
    assert.deepStrictEqual(onboarding.senderIdentityFrom(null), {
      registered: false, agentId: null, firstName: null, agent: null,
    });
  });

  check('agent_infos.first_name is preferred over username for the greeting', () =>
    assert.strictEqual(onboarding.displayFirstName({ first_name: 'Sarah', username: 'Kabeya' }), 'Sarah'));

  // upsertAgentFromWhatsApp defaults `username` to the phone digits when the
  // sender gave no name, and "Bonjour 243997123456 !" is worse than no greeting.
  check('a username that is only the phone number never becomes a greeting', () => {
    assert.strictEqual(onboarding.displayFirstName({ username: '243997123456' }), null);
    assert.strictEqual(onboarding.displayFirstName({ username: '+243 997-123-456' }), null);
    assert.strictEqual(onboarding.displayFirstName({}), null);
  });

  check('a real username is used when agent_infos has no first name', () =>
    assert.strictEqual(onboarding.displayFirstName({ username: 'Jean Kabeya' }), 'Jean'));

  await checkAsync('identifySender degrades to "unknown" without Postgres rather than throwing', async () => {
    const identity = await onboarding.identifySender('243997123456');
    assert.strictEqual(identity.registered, false);
    assert.strictEqual(identity.agentId, null);
  });

  // --- The message ----------------------------------------------------------

  check('the recognition note greets the agent by name and points at their dashboard', () => {
    const note = onboarding.recognitionNote(
      { firstName: 'Sarah' },
      { commune: 'Ngaliema', price: 2500, currency: 'USD', transaction_type: 'location', bedrooms: 4 },
      2,
    );
    assert.match(note, /Bonjour Sarah/);
    assert.match(note, /lié à votre compte/);
    assert.match(note, /Commune : Ngaliema/);
    assert.match(note, /compte\/agent\/biens/);
  });

  check('with no usable name the sentence drops the name instead of printing a blank', () => {
    const note = onboarding.recognitionNote({ firstName: null }, {}, 0);
    assert.doesNotMatch(note, /undefined|null|Bonjour\s*!/);
    assert.match(note, /lié à votre compte/);
  });

  // --- The local attribution write ------------------------------------------

  const attributed = dbService.insertListing(
    { is_listing: true, property_type: 'villa', commune: 'Gombe' },
    '243997123456',
    { wamid: 'wamid.ATTR' },
  );

  check('a listing starts unattributed', () =>
    assert.strictEqual(dbService.getListing(attributed.id).agent_id, null));

  check('attributeListingToAgent stamps the agents.id on the row', () => {
    assert.strictEqual(dbService.attributeListingToAgent(attributed.id, 91), true);
    assert.strictEqual(dbService.getListing(attributed.id).agent_id, 91);
  });

  // A redelivery or a correction must never move a listing between accounts.
  check('an attribution already on the row is never overwritten', () => {
    assert.strictEqual(dbService.attributeListingToAgent(attributed.id, 42), false);
    assert.strictEqual(dbService.getListing(attributed.id).agent_id, 91);
  });

  check('attributing to a missing agent id is a no-op, not a NULL write', () => {
    const fresh = dbService.insertListing(
      { is_listing: true, property_type: 'villa' }, '243997000111', { wamid: 'wamid.ATTR2' },
    );
    assert.strictEqual(dbService.attributeListingToAgent(fresh.id, null), false);
    assert.strictEqual(dbService.getListing(fresh.id).agent_id, null);
  });

  // --- End to end through the real webhook route ----------------------------
  //
  // The case the whole feature exists for: a registered agent WhatsApps a
  // property, it lands on their account, and the reply says so.
  //
  // identifySender is stubbed because the recognition it performs is a real
  // Supabase query and this suite deliberately runs with no database
  // credentials (see the top of this file). Everything downstream of it — the
  // route, the parser, SQLite, the reply — is the real code path.

  const realIdentifySender = onboarding.identifySender;

  httpCalls.length = 0;
  onboarding.identifySender = async () => onboarding.senderIdentityFrom(VERIFIED_AGENT);

  const recognisedStatus = await post(
    '/webhook',
    inbound('wamid.RECOGNISED', 'Villa a louer Ngaliema 4 chambres 2500$/mois', '243997123456'),
  );
  await settle();

  const recognisedFound = dbService.findByWamid('wamid.RECOGNISED');

  check('the webhook accepts the listing', () => assert.strictEqual(recognisedStatus, 200));

  check('a listing from a registered agent is stored against their agent_id', () => {
    assert.ok(recognisedFound, 'no listing row was created for wamid.RECOGNISED');
    const row = dbService.getListing(recognisedFound.id);
    assert.strictEqual(row.wa_id, '243997123456');
    assert.strictEqual(row.agent_id, 91);
  });

  check('the agent is greeted by name and told the listing is on their account', () => {
    assert.strictEqual(httpCalls.length, 1, 'expected exactly one Chakra reply');
    const body = httpCalls[0].data.text.body;
    assert.match(body, /Annonce reçue/);
    assert.match(body, /Bonjour Sarah/);
    assert.match(body, /lié à votre compte/);
  });

  check('a recognised agent is never also asked to register', () => {
    assert.doesNotMatch(httpCalls[0].data.text.body, /nom de votre agence/);
  });

  httpCalls.length = 0;
  onboarding.identifySender = async () => onboarding.senderIdentityFrom(null);

  await post('/webhook', inbound('wamid.UNKNOWNSENDER', 'Villa a louer Ngaliema', '243997999888'));
  await settle();

  check('a listing from an unrecognised sender is stored with no attribution', () => {
    const found = dbService.findByWamid('wamid.UNKNOWNSENDER');
    assert.ok(found, 'no listing row was created for wamid.UNKNOWNSENDER');
    assert.strictEqual(dbService.getListing(found.id).agent_id, null);
  });

  onboarding.identifySender = realIdentifySender;

  // ===========================================================================
  // 20. Viewing-request notifications (services/viewingNotifications.js)
  //
  //     The listing page tells a visitor "l'agent vous répondra sur WhatsApp"
  //     the moment the row commits. Before this module existed, both creation
  //     paths wrote the row and sent nothing at all — confirmed in production,
  //     where viewing_requests #1..#3 each had zero outbound sends. These
  //     checks are here so that silence can never come back unnoticed.
  // ===========================================================================

  console.log('\n20. Viewing-request notifications');

  const viewingNotifications = require('../services/viewingNotifications');
  const propertyRepo = require('../services/propertyRepository');

  // getListingContactById is a real Supabase read and this suite runs with no
  // database credentials (see the top of this file), so it is stubbed — the
  // message building, the verification gate, the ops copy and the real Chakra
  // send underneath are all the genuine code path.
  const realGetListingContact = propertyRepo.getListingContactById;

  const ATTRIBUTED_LISTING = {
    id: '303',
    reference: 'Notre Dame',
    title: '2 chambres — Appartement à louer à Lingwala',
    slug: '2-chambres-appartement-a-louer-a-lingwala-303',
    commune: 'Lingwala',
    agent_id: '43',
    agent_phone: '243821122937',
    phone_verified_at: '2026-09-09T17:46:02.802Z',
    agent_name: 'Kkimmo',
  };

  const viewingLead = dbService.createLead({
    wa_id: '243990111222',
    name: 'Henoc Mimbo',
    source: 'listing-visit-request',
    property_id: 303,
  });
  const viewingRow = dbService.createViewingRequest({
    leadId: viewingLead.id,
    propertyId: 303,
    requestedTime: 'Tuesday 10 am',
  });

  // --- The agent send -------------------------------------------------------

  propertyRepo.getListingContactById = async () => ATTRIBUTED_LISTING;
  httpCalls.length = 0;

  const notifiedAgent = await viewingNotifications.notifyViewingRequest({
    viewingRequest: viewingRow,
    lead: viewingLead,
    propertyId: 303,
  });

  check('a viewing request on an attributed listing really sends to that agent', () => {
    assert.strictEqual(notifiedAgent.agentNotified, true);
    assert.strictEqual(httpCalls.length, 1, 'expected exactly one Chakra send');
    assert.strictEqual(httpCalls[0].data.to, '243821122937');
    // Interactive, not text: the alert carries the three response buttons.
    assert.strictEqual(httpCalls[0].data.type, 'interactive');
  });

  check('the agent message carries the customer, the slot and the listing', () => {
    const body = httpCalls[0].data.interactive.body.text;
    assert.match(body, /Henoc Mimbo/);
    assert.match(body, /\+243990111222/);
    assert.match(body, /Tuesday 10 am/);
    assert.match(body, /Lingwala/);
  });

  // The three options, with the request id embedded in each — an agent
  // holding two open requests has to be able to answer the older one.
  check('the alert carries all three response buttons, each naming the request', () => {
    const buttons = httpCalls[0].data.interactive.action.buttons;
    assert.strictEqual(buttons.length, 3);
    assert.deepStrictEqual(
      buttons.map((b) => b.reply.id),
      [`viewing_accept:${viewingRow.id}`, `viewing_reschedule:${viewingRow.id}`, `viewing_decline:${viewingRow.id}`],
    );
    assert.deepStrictEqual(
      buttons.map((b) => b.reply.title),
      ['✅ Accepter', '🕒 Autre créneau', '❌ Décliner'],
    );
  });

  // No template is approved for this yet, so VIEWING_REQUEST_TEMPLATE is
  // unset by default and the send must go straight out as a session message
  // rather than burning a guaranteed-failing template round trip first — the
  // exact cost AGENT_OTP_TEMPLATE pays on every OTP today.
  check('with no template configured, no template call is attempted at all', () =>
    assert.strictEqual(httpCalls.filter((c) => c.data && c.data.type === 'template').length, 0));

  // --- The verification gate ------------------------------------------------

  propertyRepo.getListingContactById = async () => ({
    ...ATTRIBUTED_LISTING,
    phone_verified_at: null,
  });
  httpCalls.length = 0;

  const unverifiedContact = await viewingNotifications.notifyViewingRequest({
    viewingRequest: viewingRow,
    lead: viewingLead,
    propertyId: 303,
  });

  // Same gate as postgres.js's resolveAgentId and identifySender: an
  // unverified number is somebody's claim, and messaging it would tell a
  // stranger who is asking to visit an agency's properties.
  check('an unverified agent number is never messaged', () => {
    assert.strictEqual(unverifiedContact.agentNotified, false);
    assert.strictEqual(httpCalls.length, 0);
  });

  propertyRepo.getListingContactById = async () => ({
    ...ATTRIBUTED_LISTING,
    agent_id: null,
    agent_phone: null,
    phone_verified_at: null,
    agent_name: null,
  });
  httpCalls.length = 0;

  const unattributedContact = await viewingNotifications.notifyViewingRequest({
    viewingRequest: viewingRow,
    lead: viewingLead,
    propertyId: 303,
  });

  check('a listing with no agent notifies nobody rather than guessing a recipient', () => {
    assert.strictEqual(unattributedContact.agentNotified, false);
    assert.strictEqual(httpCalls.length, 0);
  });

  // --- Failure posture ------------------------------------------------------

  propertyRepo.getListingContactById = async () => {
    throw new Error('Postgres unreachable');
  };
  httpCalls.length = 0;

  await checkAsync('a failing listing lookup degrades to "nobody notified", never a throw', async () => {
    const result = await viewingNotifications.notifyViewingRequest({
      viewingRequest: viewingRow,
      lead: viewingLead,
      propertyId: 303,
    });
    assert.strictEqual(result.agentNotified, false);
  });

  propertyRepo.getListingContactById = async () => ATTRIBUTED_LISTING;
  httpCalls.length = 0;

  await checkAsync('a request with no property tells nobody and reports why', async () => {
    const result = await viewingNotifications.notifyViewingRequest({
      viewingRequest: { id: 99, property_id: null },
      lead: viewingLead,
    });
    assert.strictEqual(result.reason, 'no-property');
    assert.strictEqual(httpCalls.length, 0);
  });

  // --- Message building, without the network --------------------------------

  check('displayPhone prints a dialable number and never a blank', () => {
    assert.strictEqual(viewingNotifications.displayPhone('243821122937'), '+243821122937');
    assert.strictEqual(viewingNotifications.displayPhone(null), 'numéro inconnu');
  });

  check('listingLabel falls back title -> reference -> id, never to an empty string', () => {
    assert.strictEqual(viewingNotifications.listingLabel({ title: 'Villa' }, 7), 'Villa');
    assert.strictEqual(viewingNotifications.listingLabel({ reference: 'LKP-1' }, 7), 'Réf: LKP-1');
    assert.strictEqual(viewingNotifications.listingLabel(null, 7), 'bien #7');
  });

  // The desk copy's whole job is saying whether anyone else was told, so a
  // request on an unattributed listing has to read as needing a human.
  // Branding is the FIRST line on purpose: WhatsApp's chat list and push
  // preview only show the opening characters, so a signature at the bottom is
  // branding the recipient never sees before deciding whether to open it.
  check('both messages open with the Lukka Place system-alert header', () => {
    const agentBody = viewingNotifications.agentMessage({
      listing: ATTRIBUTED_LISTING, lead: viewingLead, viewingRequest: viewingRow, propertyId: 303,
    });
    const deskBody = viewingNotifications.opsMessage({
      listing: ATTRIBUTED_LISTING, lead: viewingLead, viewingRequest: viewingRow,
      propertyId: 303, agentNotified: true,
    });
    assert.strictEqual(viewingNotifications.HEADER, '\u{1F3E0} [Lukka Place] Demande de visite');
    assert.ok(agentBody.startsWith(viewingNotifications.HEADER), 'agent message does not open with the header');
    assert.ok(agentBody.includes('https://lukkaplace.com/compte/agent/visites'), 'the agent is told where to confirm');
    assert.ok(deskBody.startsWith(viewingNotifications.HEADER), 'ops message does not open with the header');
  });

  check('the ops copy flags a request that reached no agent', () => {
    const body = viewingNotifications.opsMessage({
      listing: null,
      lead: viewingLead,
      viewingRequest: viewingRow,
      propertyId: 303,
      agentNotified: false,
      agentSkipReason: 'aucun agent rattaché à cette annonce',
    });
    assert.match(body, /NON prévenu/);
    assert.match(body, /manuellement/);
  });

  check('the ops copy names the agent when one was reached', () => {
    const body = viewingNotifications.opsMessage({
      listing: ATTRIBUTED_LISTING,
      lead: viewingLead,
      viewingRequest: viewingRow,
      propertyId: 303,
      agentNotified: true,
    });
    assert.match(body, /Agent prévenu : Kkimmo/);
  });

  // --- Through the real route -----------------------------------------------

  propertyRepo.getListingContactById = async () => ATTRIBUTED_LISTING;
  httpCalls.length = 0;

  const viewingRouteResponse = await adminRequest('POST', '/admin/viewing-requests', {
    lead_id: viewingLead.id,
    property_id: 303,
    requested_time: 'samedi 11h',
  });
  await settle();

  check('POST /admin/viewing-requests still returns 201 for the visitor', () =>
    assert.strictEqual(viewingRouteResponse.status, 201));

  check('POST /admin/viewing-requests now actually notifies the agent', () => {
    assert.strictEqual(httpCalls.length, 1, 'expected exactly one Chakra send from the route');
    assert.strictEqual(httpCalls[0].data.to, '243821122937');
    assert.match(httpCalls[0].data.interactive.body.text, /samedi 11h/);
  });

  propertyRepo.getListingContactById = realGetListingContact;

  // ===========================================================================
  // 21. The agent feedback loop — Accept / Autre créneau / Décliner
  //
  //     Three buttons, a decline survey, closing-price capture, and the
  //     customer's recovery path. The property under test throughout is the
  //     one every handler shares: nothing may act on a viewing request unless
  //     the sender is genuinely that listing's agent.
  // ===========================================================================

  console.log('\n21. Agent feedback loop (accept / reschedule / decline)');

  const realMatchProperties = propertyMatching.matchProperties;

  const AGENT_WA = '243821122937';
  const STRANGER_WA = '243999000111';

  propertyRepo.getListingContactById = async () => ATTRIBUTED_LISTING;

  function freshViewingRequest(requestedTime = 'Tuesday 10 am') {
    const lead = dbService.createLead({
      wa_id: '243990111222',
      name: 'Henoc Mimbo',
      source: 'listing-visit-request',
      property_id: 303,
    });
    return dbService.createViewingRequest({ leadId: lead.id, propertyId: 303, requestedTime });
  }

  // --- Parsers --------------------------------------------------------------

  check('a button id names both the action and the request it applies to', () => {
    assert.deepStrictEqual(
      viewingNotifications.parseViewingButtonId('viewing_accept:7'),
      { action: 'accept', viewingRequestId: 7 },
    );
    assert.deepStrictEqual(
      viewingNotifications.parseViewingButtonId('viewing_reschedule:12'),
      { action: 'reschedule', viewingRequestId: 12 },
    );
    assert.deepStrictEqual(
      viewingNotifications.parseViewingButtonId('viewing_decline:1'),
      { action: 'decline', viewingRequestId: 1 },
    );
  });

  // Another feature's button must pass straight through untouched.
  check('an id that is not ours parses to null rather than being claimed', () => {
    for (const id of ['viewing_bogus:3', 'viewing_accept:', 'viewing_accept:abc', 'other_flow:3', '', null]) {
      assert.strictEqual(viewingNotifications.parseViewingButtonId(id), null, `claimed ${id}`);
    }
  });

  // The keycap emoji 1️⃣ is U+0031 + U+FE0F + U+20E3 — an agent tapping the
  // emoji keyboard sends that, not a plain "1".
  check('a numbered answer is read from digits, keycaps, punctuation and words', () => {
    for (const [input, expected] of [
      ['1', 1], ['2', 2], ['3', 3],
      ['1.', 1], ['2)', 2], ['3]', 3],
      ['1️⃣', 1], ['2️⃣', 2],
      ['un', 1], ['deux', 2], ['trois', 3],
      ['  3  ', 3],
    ]) {
      assert.strictEqual(viewingNotifications.parseNumberedChoice(input), expected, `for ${JSON.stringify(input)}`);
    }
  });

  check('anything that is not a numbered answer parses to null', () => {
    for (const input of ['4', '0', 'bonjour', 'villa a louer', '', null, '12']) {
      assert.strictEqual(viewingNotifications.parseNumberedChoice(input), null, `for ${JSON.stringify(input)}`);
    }
  });

  // The survey parser, which is what agents actually answer in words.
  check('the decline survey reads the words agents really type, not just digits', () => {
    for (const [input, expected] of [
      ['1', 1], ['déjà loué', 1], ['deja loue', 1], ['c\'est vendu', 1], ['DÉJÀ LOUÉE', 1],
      ['2', 2], ['pas disponible', 2], ['indisponible', 2], ['non disponible', 2], ['autre date', 2],
      ['3', 3], ['autre raison', 3], ['autre', 3],
    ]) {
      assert.strictEqual(viewingNotifications.parseDeclineReason(input), expected, `for ${JSON.stringify(input)}`);
    }
  });

  // THE important one. A survey being open must not turn the next real
  // listing into a survey answer — same posture as the sale-price follow-up.
  check('a real property advert is never read as a survey answer', () => {
    for (const input of [
      'Villa a louer Ngaliema 4 chambres 2500$/mois',
      'Appartement 2 chambres Gombe, 1200 USD',
      'bonjour',
      'Maison à louer type locataire 3 portes',
    ]) {
      assert.strictEqual(viewingNotifications.parseDeclineReason(input), null, `swallowed ${JSON.stringify(input)}`);
    }
  });

  check('a closing price is read from the shapes agents write it in', () => {
    assert.strictEqual(viewingNotifications.parseClosingPrice('700$'), 700);
    assert.strictEqual(viewingNotifications.parseClosingPrice('700 $'), 700);
    assert.strictEqual(viewingNotifications.parseClosingPrice('1 200'), 1200);
    assert.strictEqual(viewingNotifications.parseClosingPrice('1.200 USD'), 1200);
    assert.strictEqual(viewingNotifications.parseClosingPrice('bonjour'), null);
    assert.strictEqual(viewingNotifications.parseClosingPrice('0'), null);
  });

  check('"passer" declines to state the price, and only that', () => {
    assert.strictEqual(viewingNotifications.isPriceDeclined('passer'), true);
    assert.strictEqual(viewingNotifications.isPriceDeclined('non'), true);
    assert.strictEqual(viewingNotifications.isPriceDeclined('700'), false);
  });

  // --- Authorisation --------------------------------------------------------

  const strangerTarget = freshViewingRequest();
  httpCalls.length = 0;

  const strangerOutcome = await viewingNotifications.handleViewingButtonReply({
    from: STRANGER_WA,
    replyId: `viewing_accept:${strangerTarget.id}`,
  });

  // A button id is a guessable string. Without this check anyone could
  // confirm, reschedule or kill somebody else's viewing by typing one.
  check('a tap from someone who is not the listing\'s agent changes nothing', () => {
    assert.strictEqual(strangerOutcome.ignored, 'not-this-listings-agent');
    assert.strictEqual(dbService.getViewingRequest(strangerTarget.id).status, 'PENDING');
  });

  // Answering "that request belongs to someone else" would confirm the id is
  // real, so the refusal is silent to the sender.
  check('the refusal tells the stranger nothing', () =>
    assert.strictEqual(httpCalls.length, 0));

  const unknownOutcome = await viewingNotifications.handleViewingButtonReply({
    from: AGENT_WA,
    replyId: 'viewing_accept:999999',
  });
  check('a tap naming a request that does not exist is absorbed, not crashed on', () =>
    assert.strictEqual(unknownOutcome.ignored, 'unknown-request'));

  check('a reply id belonging to another feature is left for it to handle', async () => {
    const other = await viewingNotifications.handleViewingButtonReply({
      from: AGENT_WA,
      replyId: 'some_other_feature:3',
    });
    assert.strictEqual(other.handled, false);
  });

  // --- Accept ---------------------------------------------------------------

  const acceptTarget = freshViewingRequest('samedi 14h');
  httpCalls.length = 0;

  const acceptOutcome = await viewingNotifications.handleViewingButtonReply({
    from: AGENT_WA,
    replyId: `viewing_accept:${acceptTarget.id}`,
  });

  check('[✅ Accepter] confirms the request', () => {
    assert.strictEqual(acceptOutcome.status, 'CONFIRMED');
    assert.strictEqual(dbService.getViewingRequest(acceptTarget.id).status, 'CONFIRMED');
  });

  check('accepting messages BOTH the agent and the client', () => {
    // Three sends now, not two: the agent gets an ack AND the slot-confirmation
    // question, the client gets the confirmation. "samedi 14h" parses, so the
    // agent is asked to confirm a concrete instant rather than to type one.
    assert.strictEqual(
      httpCalls.length,
      3,
      'expected an ack + slot question to the agent, and a confirmation to the client',
    );
    assert.deepStrictEqual(
      httpCalls.map((c) => c.data.to).sort(),
      ['243821122937', '243821122937', '243990111222'],
    );
  });

  check('accepting pins the visit to a real instant the check-in can count from', () => {
    // requested_time stays the customer's own free text; scheduled_at is the
    // agent-confirmed instant, stored in UTC so the check-in sweep's
    // `scheduled_at <= ?` comparison is a real ordering rather than a string
    // coincidence.
    const stored = dbService.getViewingRequest(acceptTarget.id);
    assert.strictEqual(stored.requested_time, 'samedi 14h', 'the customer wording is untouched');
    assert.ok(stored.scheduled_at, 'a parseable slot must be stored on accept');
    assert.match(stored.scheduled_at, /Z$/, 'scheduled_at must be UTC, never a local offset');
    assert.strictEqual(acceptOutcome.scheduledAt, stored.scheduled_at);
  });

  check('the client is told the visit is confirmed, with the slot and the agent', () => {
    const toClient = httpCalls.find((c) => c.data.to === '243990111222').data.text.body;
    assert.match(toClient, /confirmé votre visite/);
    assert.match(toClient, /samedi 14h/);
    assert.match(toClient, /Kkimmo/);
  });

  // --- Reschedule -----------------------------------------------------------

  const reschedTarget = freshViewingRequest('lundi 9h');
  httpCalls.length = 0;

  const reschedOutcome = await viewingNotifications.handleViewingButtonReply({
    from: AGENT_WA,
    replyId: `viewing_reschedule:${reschedTarget.id}`,
  });

  check('[🕒 Autre créneau] marks it rescheduled and asks the agent for a slot', () => {
    assert.strictEqual(reschedOutcome.status, 'RESCHEDULED');
    assert.strictEqual(dbService.getViewingRequest(reschedTarget.id).status, 'RESCHEDULED');
    assert.strictEqual(httpCalls.length, 1);
    assert.match(httpCalls[0].data.text.body, /Quel créneau proposez-vous/);
  });

  // The agent's NEXT message is the answer — without this claim it would fall
  // into the listing-intake pipeline instead.
  check('the agent\'s next message is claimed for the slot', () => {
    const pending = dbService.getPendingAgentAction(AGENT_WA);
    assert.strictEqual(pending.kind, 'RESCHEDULE_TIME');
    assert.strictEqual(pending.viewing_request_id, reschedTarget.id);
  });

  httpCalls.length = 0;
  const proposedOutcome = await viewingNotifications.handleAgentTextReply({
    from: AGENT_WA,
    text: 'samedi 16h',
  });

  check('the proposed slot is stored and forwarded to the client', () => {
    assert.strictEqual(proposedOutcome.action, 'reschedule-proposed');
    assert.strictEqual(dbService.getViewingRequest(reschedTarget.id).requested_time, 'samedi 16h');
    // Since §89 it goes with the customer's two answer buttons (interactive).
    const sent = httpCalls.find((c) => c.data.to === '243990111222').data;
    const toClient = sent.text?.body || sent.interactive?.body?.text;
    assert.match(toClient, /samedi 16h/);
    assert.match(toClient, /propose un autre créneau/);
  });

  check('the question is closed once answered', () =>
    assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA), undefined));

  // --- Decline --------------------------------------------------------------

  propertyMatching.matchProperties = async () => ({
    data: [
      { id: 401, title: 'Appartement 2 chambres à Lingwala', price: 950, slug: 'appt-401' },
      { id: 303, title: 'The one they just declined', price: 1000, slug: 'appt-303' },
      { id: 402, title: 'Studio meublé à Gombe', price: 800, slug: 'studio-402' },
      { id: 403, title: 'Villa 3 chambres à Limete', price: 1500, slug: 'villa-403' },
      { id: 404, title: 'Un quatrième bien', price: 1100, slug: 'appt-404' },
    ],
    total: 5,
    widened: false,
    error: false,
  });

  const declineTarget = freshViewingRequest();
  httpCalls.length = 0;

  const declineOutcome = await viewingNotifications.handleViewingButtonReply({
    from: AGENT_WA,
    replyId: `viewing_decline:${declineTarget.id}`,
  });

  check('[❌ Décliner] marks it declined — a state distinct from cancelled', () => {
    assert.strictEqual(declineOutcome.status, 'DECLINED');
    assert.strictEqual(dbService.getViewingRequest(declineTarget.id).status, 'DECLINED');
  });

  check('declining sends the agent the three-option survey', () => {
    const toAgent = httpCalls.find((c) => c.data.to === AGENT_WA).data.text.body;
    assert.match(toAgent, /Pourquoi déclinez-vous cette visite/);
    assert.match(toAgent, /Bien déjà loué \/ vendu/);
    assert.match(toAgent, /Non disponible aux dates demandées/);
    assert.match(toAgent, /Autre raison/);
  });

  // The client should not wait on the agent filling in a questionnaire to
  // learn this particular visit is not happening.
  check('the client gets three real alternatives, at the same time', () => {
    assert.strictEqual(declineOutcome.alternatives, 3);
    const toClient = httpCalls.find((c) => c.data.to === '243990111222').data.text.body;
    assert.match(toClient, /n'est pas disponible pour ce bien/);
    assert.match(toClient, /Appartement 2 chambres à Lingwala/);
    assert.match(toClient, /Studio meublé à Gombe/);
    assert.match(toClient, /Villa 3 chambres à Limete/);
  });

  // Offering the listing they were just turned down for would be absurd.
  check('the declined listing is never offered back as an alternative', () => {
    const toClient = httpCalls.find((c) => c.data.to === '243990111222').data.text.body;
    assert.doesNotMatch(toClient, /The one they just declined/);
    assert.doesNotMatch(toClient, /Un quatrième bien/);
  });

  // --- The survey answer, and the fall-through that protects real listings --

  httpCalls.length = 0;
  const notAnAnswer = await viewingNotifications.handleAgentTextReply({
    from: AGENT_WA,
    text: 'Villa a louer Ngaliema 4 chambres 2500$/mois',
  });

  check('a real listing sent while the survey is open falls through untouched', () => {
    assert.strictEqual(notAnAnswer.handled, false);
    assert.strictEqual(httpCalls.length, 0);
    // Still open: the survey was not silently consumed either.
    assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA).kind, 'DECLINE_REASON');
  });

  httpCalls.length = 0;
  const reason2 = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: '2' });

  check('answering 2 records the reason and closes the question', () => {
    assert.strictEqual(reason2.reason, 2);
    assert.match(dbService.getViewingRequest(declineTarget.id).decline_reason, /Non disponible/);
    assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA), undefined);
  });

  // --- Answer 1: the property is gone ---------------------------------------

  const soldTarget = freshViewingRequest();
  await viewingNotifications.handleViewingButtonReply({
    from: AGENT_WA,
    replyId: `viewing_decline:${soldTarget.id}`,
  });

  httpCalls.length = 0;
  const reason1 = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: 'déjà loué' });

  check('answering "déjà loué" asks the agent what it closed at', () => {
    assert.strictEqual(reason1.action, 'declined-already-taken');
    const toAgent = httpCalls.find((c) => c.data.to === AGENT_WA).data.text.body;
    assert.match(toAgent, /Quel a été le prix final conclu \(en USD\) \? \(Exemple: 700\)/);
    assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA).kind, 'CLOSING_PRICE');
  });

  httpCalls.length = 0;
  const priced = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: '700$' });

  check('the closing price is captured as a real number', () => {
    assert.strictEqual(priced.action, 'closing-price-recorded');
    assert.strictEqual(priced.amount, 700);
    assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA), undefined);
  });

  // markPropertySold needs live Postgres, which this suite deliberately runs
  // without — `recorded: false` is the honest answer, not a silent success.
  check('with no database configured the close is reported as not written', () =>
    assert.strictEqual(priced.recorded, false));

  const skipTarget = freshViewingRequest();
  await viewingNotifications.handleViewingButtonReply({
    from: AGENT_WA,
    replyId: `viewing_decline:${skipTarget.id}`,
  });
  await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: '1' });
  httpCalls.length = 0;
  const skipped = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: 'passer' });

  // Off the market, transaction not recorded — which keeps the market export
  // free of a fabricated price.
  check('an agent who will not give a price is not pressed, and none is invented', () => {
    assert.strictEqual(skipped.action, 'closing-price-skipped');
    assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA), undefined);
  });

  // --- The typed fallback, for when buttons never arrive --------------------

  const fallbackTarget = freshViewingRequest();
  dbService.setPendingAgentAction({
    waId: AGENT_WA,
    kind: 'VIEWING_RESPONSE',
    viewingRequestId: fallbackTarget.id,
  });
  httpCalls.length = 0;

  const typedAccept = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: '1' });

  check('a typed "1" accepts, exactly as tapping the button would', () => {
    assert.strictEqual(typedAccept.status, 'CONFIRMED');
    assert.strictEqual(dbService.getViewingRequest(fallbackTarget.id).status, 'CONFIRMED');
    assert.ok(httpCalls.some((c) => c.data.to === '243990111222'), 'the client was not told');
  });

  check('with no question open, a bare number is nobody\'s answer', async () => {
    dbService.clearPendingAgentAction(AGENT_WA);
    const orphan = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: '1' });
    assert.strictEqual(orphan.handled, false);
  });

  // --- When there is genuinely nothing to offer -----------------------------

  propertyMatching.matchProperties = async () => ({ data: [], total: 0, widened: false, error: false });

  const emptyTarget = freshViewingRequest();
  httpCalls.length = 0;
  await viewingNotifications.handleViewingButtonReply({
    from: AGENT_WA,
    replyId: `viewing_decline:${emptyTarget.id}`,
  });

  // "Voici 3 logements similaires :" followed by nothing is worse than
  // saying plainly that we have nothing right now.
  check('with no alternatives the client gets an honest message, not an empty list', () => {
    const toClient = httpCalls.find((c) => c.data.to === '243990111222').data.text.body;
    assert.match(toClient, /n'avons pas d'équivalent disponible/);
    assert.doesNotMatch(toClient, /Voici \d/);
  });

  // --- End to end, through the real webhook route ---------------------------
  //
  // The piece most likely to be wrong in production: a tapped button arrives
  // as type 'interactive' with no text and no media, and before this feature
  // normaliseMessage produced nothing usable for it — the tap was dropped in
  // silence, which is exactly how a feedback loop appears to work while doing
  // nothing at all.

  function inboundButton(wamid, buttonId, from) {
    return {
      object: 'whatsapp_business_account',
      entry: [{ id: '1', changes: [{ field: 'messages', value: {
        metadata: { phone_number_id: '987654321' },
        contacts: [{ wa_id: from, profile: { name: 'Kkimmo' } }],
        messages: [{
          from,
          id: wamid,
          timestamp: '1',
          type: 'interactive',
          interactive: { type: 'button_reply', button_reply: { id: buttonId, title: '✅ Accepter' } },
        }],
      } }] }],
    };
  }

  const e2eTarget = freshViewingRequest('dimanche 10h');
  httpCalls.length = 0;

  const buttonStatus = await post(
    '/webhook',
    inboundButton('wamid.BUTTONTAP', `viewing_accept:${e2eTarget.id}`, AGENT_WA),
  );
  await settle();

  check('the webhook accepts an interactive button payload', () =>
    assert.strictEqual(buttonStatus, 200));

  check('a real tap, delivered by the real route, confirms the request', () =>
    assert.strictEqual(dbService.getViewingRequest(e2eTarget.id).status, 'CONFIRMED'));

  check('and the client hears about it', () =>
    assert.ok(
      httpCalls.some((c) => c.data.to === '243990111222' && /confirmé votre visite/.test(c.data.text.body)),
      'no confirmation reached the client',
    ));

  // A tap must never be mistaken for a property advert.
  check('the tap was not also parsed as a listing', () =>
    assert.strictEqual(dbService.findByWamid('wamid.BUTTONTAP'), undefined));

  // The typed route, all the way through — this is what agents fall back to
  // whenever the interactive payload doesn't reach them.
  const e2eTyped = freshViewingRequest('mardi 11h');
  dbService.setPendingAgentAction({
    waId: AGENT_WA,
    kind: 'VIEWING_RESPONSE',
    viewingRequestId: e2eTyped.id,
  });
  httpCalls.length = 0;

  await post('/webhook', inbound('wamid.TYPEDTHREE', '3', AGENT_WA));
  await settle();

  check('a typed "3" through the real route declines and starts the survey', () => {
    assert.strictEqual(dbService.getViewingRequest(e2eTyped.id).status, 'DECLINED');
    assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA).kind, 'DECLINE_REASON');
  });

  // The guarantee that makes the whole interception safe to sit in front of
  // the intake pipeline.
  httpCalls.length = 0;
  await post(
    '/webhook',
    inbound('wamid.REALLISTING', 'Villa a louer Ngaliema 4 chambres 2500$/mois', AGENT_WA),
  );
  await settle();

  check('a real listing sent mid-survey is still stored as a listing', () => {
    const stored = dbService.findByWamid('wamid.REALLISTING');
    assert.ok(stored, 'the listing was swallowed by the open survey');
  });

  dbService.clearPendingAgentAction(AGENT_WA);

  propertyMatching.matchProperties = realMatchProperties;
  dbService.clearPendingAgentAction(AGENT_WA);

  // ===========================================================================
  // 21b. Agent answers from the web dashboard (respondFromDashboard)
  //
  //      The agent portal's Visites tab used to PATCH the status and stop: the
  //      customer heard nothing, first_response_at stayed NULL, and nothing
  //      told the admin console the agent had answered at all. Reported
  //      2026-09-15 after an agent confirmed four visits and no customer got a
  //      message. These pin the dashboard to the same loop as the buttons.
  // ===========================================================================

  console.log('\n21b. Agent answers from the web dashboard');

  const DASHBOARD_AGENT_ID = Number(ATTRIBUTED_LISTING.agent_id);
  const DASH_CUSTOMER = '243990111222';
  const DASH_OPS = '243800000001';
  const listingStubBefore21b = propertyRepo.getListingContactById;
  const matchBefore21b = propertyMatching.matchProperties;
  const opsBefore21b = process.env.OPS_WHATSAPP_NUMBER;
  propertyRepo.getListingContactById = async () => ATTRIBUTED_LISTING;
  propertyMatching.matchProperties = async () => ({
    data: [{ id: 404, title: 'Studio Gombe', price: 500, slug: 'studio-gombe-404' }],
  });
  process.env.OPS_WHATSAPP_NUMBER = DASH_OPS;
  const dashSendsTo = (wa) => httpCalls.filter((c) => c.data && String(c.data.to) === wa);
  const dashBody = (call) => JSON.stringify(call.data);
  const dashAnswer = (id, status, extra = {}) =>
    viewingNotifications.respondFromDashboard({ viewingRequestId: id, agentId: DASHBOARD_AGENT_ID, status, ...extra });

  // --- Confirm --------------------------------------------------------------

  const dashConfirm = freshViewingRequest('samedi 14h');
  dbService.setPendingAgentAction({ waId: AGENT_WA, kind: 'VIEWING_RESPONSE', viewingRequestId: dashConfirm.id });
  httpCalls.length = 0;
  const dashConfirmResult = await dashAnswer(dashConfirm.id, 'CONFIRMED');
  const dashConfirmedRow = dbService.getViewingRequest(dashConfirm.id);

  check('a dashboard Confirm sets CONFIRMED and tells the customer on WhatsApp', () => {
    assert.strictEqual(dashConfirmResult.ok, true);
    assert.strictEqual(dashConfirmedRow.status, 'CONFIRMED');
    assert.strictEqual(dashConfirmResult.tenantNotified, true);
    const toCustomer = dashSendsTo(DASH_CUSTOMER);
    assert.strictEqual(toCustomer.length, 1, 'exactly one message to the customer');
    assert.match(dashBody(toCustomer[0]), /confirm/i);
  });

  check('the agent is not messaged on WhatsApp about an answer they gave on the web', () =>
    assert.strictEqual(dashSendsTo(AGENT_WA).length, 0));

  check('the admin console can see it: response time, channel, customer notified', () => {
    assert.ok(dashConfirmedRow.first_response_at, 'first_response_at stamped — metrics and the SLA read it');
    assert.strictEqual(dashConfirmedRow.agent_response_via, 'DASHBOARD');
    assert.ok(dashConfirmedRow.customer_notified_at);
  });

  check("a dashboard confirmation pins the check-in to the customer's own parseable time", () =>
    assert.ok(dashConfirmedRow.scheduled_at));

  check('the WhatsApp question still open about that request is withdrawn', () =>
    assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA), undefined));

  httpCalls.length = 0;
  const dashConfirmAgain = await dashAnswer(dashConfirm.id, 'CONFIRMED');
  check('confirming twice sends nothing the second time', () => {
    assert.strictEqual(dashConfirmAgain.ok, true);
    assert.strictEqual(dashConfirmAgain.unchanged, true);
    assert.strictEqual(httpCalls.length, 0);
  });

  // --- Confirm with the agent's own date + time (the dashboard's picker) -----
  //
  // None of production's first six requests carried a parseable time, so a
  // dashboard confirmation that relied on requested_time pinned nothing and the
  // check-in, the agenda and the .ics had nothing to work from. The confirm
  // form now sends scheduled_at; these pin how the engine takes it.

  const dashPicked = freshViewingRequest('quand vous voulez');
  const pickedAt = new Date(Date.now() + 3 * 86400000);
  pickedAt.setUTCHours(13, 30, 0, 0); // 14h30 in Kinshasa
  const pickedIso = `${pickedAt.toISOString().slice(0, 10)}T14:30:00+01:00`;
  httpCalls.length = 0;
  const dashPickedResult = await dashAnswer(dashPicked.id, 'CONFIRMED', { scheduledAt: pickedIso });
  const dashPickedRow = dbService.getViewingRequest(dashPicked.id);
  check("a dashboard confirmation stores the agent's picked instant in UTC with a Z", () => {
    assert.strictEqual(dashPickedResult.ok, true);
    assert.strictEqual(dashPickedRow.status, 'CONFIRMED');
    assert.strictEqual(dashPickedRow.scheduled_at, new Date(pickedIso).toISOString());
    assert.match(dashPickedRow.scheduled_at, /T13:30:00\.000Z$/);
    assert.strictEqual(dashPickedResult.scheduledAt, dashPickedRow.scheduled_at);
  });
  check('the customer is told the agreed time, not their own vague phrase', () => {
    const toCustomer = dashSendsTo(DASH_CUSTOMER);
    assert.strictEqual(toCustomer.length, 1);
    assert.match(dashBody(toCustomer[0]), /14h30/);
    assert.doesNotMatch(dashBody(toCustomer[0]), /quand vous voulez/);
  });

  const dashPickedOverParse = freshViewingRequest('samedi 14h');
  await dashAnswer(dashPickedOverParse.id, 'CONFIRMED', { scheduledAt: pickedIso });
  check("the agent's pick wins over the customer's parseable phrase", () =>
    assert.strictEqual(dbService.getViewingRequest(dashPickedOverParse.id).scheduled_at, new Date(pickedIso).toISOString()));

  for (const [label, bad] of [
    ['a day with no hour', pickedIso.slice(0, 10)],
    ['a phrase with a day and no hour', 'demain'],
    ['garbage', 'bientôt'],
  ]) {
    const row = freshViewingRequest('samedi 14h');
    httpCalls.length = 0;
    const result = await dashAnswer(row.id, 'CONFIRMED', { scheduledAt: bad });
    check(`a dashboard confirmation with ${label} is refused and sends nothing`, () => {
      assert.strictEqual(result.ok, false);
      assert.strictEqual(result.reason, 'scheduled-at-invalid');
      assert.strictEqual(dbService.getViewingRequest(row.id).status, 'PENDING');
      assert.strictEqual(httpCalls.length, 0);
    });
  }

  const dashPast = freshViewingRequest('samedi 14h');
  httpCalls.length = 0;
  const dashPastResult = await dashAnswer(dashPast.id, 'CONFIRMED', { scheduledAt: '2026-01-05T10:00:00+01:00' });
  check('a visit cannot be confirmed for a time that has already gone by', () => {
    assert.strictEqual(dashPastResult.ok, false);
    assert.strictEqual(dashPastResult.reason, 'scheduled-at-past');
    assert.strictEqual(dbService.getViewingRequest(dashPast.id).status, 'PENDING');
    assert.strictEqual(httpCalls.length, 0);
  });

  const dashReschedIgnoresPick = freshViewingRequest('samedi 14h');
  await dashAnswer(dashReschedIgnoresPick.id, 'RESCHEDULED', { requestedTime: 'quand vous voulez', scheduledAt: pickedIso });
  check('scheduled_at is a confirmation field only — a reschedule still follows its free-text proposal', () =>
    assert.strictEqual(dbService.getViewingRequest(dashReschedIgnoresPick.id).scheduled_at, null));

  // --- The owner list carries what the agenda and the to-do list read -------

  {
    const { requestedSlotAt } = require('../services/visitSchedule');
    check("requestedSlotAt reads the customer's phrase against when they wrote it, so it can be overdue", () => {
      // Written on Monday 2026-09-14 at 08:00 UTC: "demain 14h" is Tuesday 14h Kinshasa.
      assert.strictEqual(requestedSlotAt('demain 14h', '2026-09-14 08:00:00'), '2026-09-15T13:00:00.000Z');
      assert.strictEqual(requestedSlotAt('demain', '2026-09-14 08:00:00'), null, 'a day with no hour is never a slot');
      assert.strictEqual(requestedSlotAt('', '2026-09-14 08:00:00'), null);
      assert.strictEqual(requestedSlotAt('demain 14h', null), null);
    });
    const owned = dbService.listViewingRequestsForOwner({ propertyIds: [303], limit: 200 });
    const pickedRow = owned.data.find((r) => r.id === dashPicked.id);
    check('the owner-scoped list returns scheduled_at and the response stamps', () => {
      assert.ok(pickedRow, 'the confirmed request is in its owner list');
      assert.strictEqual(pickedRow.scheduled_at, dashPickedRow.scheduled_at);
      assert.ok(pickedRow.first_response_at);
      assert.strictEqual(pickedRow.agent_response_via, 'DASHBOARD');
      assert.ok('customer_notified_at' in pickedRow);
    });
  }

  // --- Authorisation --------------------------------------------------------

  const dashStranger = freshViewingRequest();
  httpCalls.length = 0;
  const dashStrangerResult = await viewingNotifications.respondFromDashboard({
    viewingRequestId: dashStranger.id,
    agentId: 99999,
    status: 'CONFIRMED',
  });
  check("another agent's dashboard cannot answer the request", () => {
    assert.strictEqual(dashStrangerResult.ok, false);
    assert.strictEqual(dashStrangerResult.reason, 'not-this-requests-agent');
    assert.strictEqual(dbService.getViewingRequest(dashStranger.id).status, 'PENDING');
    assert.strictEqual(httpCalls.length, 0);
  });

  const dashOffline = freshViewingRequest();
  dbService.setViewingRouting(dashOffline.id, { agentId: DASHBOARD_AGENT_ID, routingType: 'DIRECT_WA' });
  propertyRepo.getListingContactById = async () => null;
  const dashOfflineResult = await dashAnswer(dashOffline.id, 'CONFIRMED');
  propertyRepo.getListingContactById = async () => ATTRIBUTED_LISTING;
  check('the agent stamped at notify time can still answer while Postgres is unreachable', () => {
    assert.strictEqual(dashOfflineResult.ok, true);
    assert.strictEqual(dbService.getViewingRequest(dashOffline.id).status, 'CONFIRMED');
  });

  const dashNotAgreed = freshViewingRequest();
  const dashBadCancel = await dashAnswer(dashNotAgreed.id, 'CANCELLED');
  check('a visit nobody agreed to cannot be CANCELLED — refusing it is a DECLINE', () => {
    assert.strictEqual(dashBadCancel.ok, false);
    assert.strictEqual(dashBadCancel.reason, 'invalid-transition');
    assert.strictEqual(dbService.getViewingRequest(dashNotAgreed.id).status, 'PENDING');
  });

  // --- Reschedule -----------------------------------------------------------

  const dashResched = freshViewingRequest('samedi 14h');
  httpCalls.length = 0;
  const dashReschedResult = await dashAnswer(dashResched.id, 'RESCHEDULED', { requestedTime: 'dimanche 10h' });
  check('a dashboard Reschedule stores the new slot and sends it to the customer', () => {
    assert.strictEqual(dashReschedResult.ok, true);
    const row = dbService.getViewingRequest(dashResched.id);
    assert.strictEqual(row.status, 'RESCHEDULED');
    assert.strictEqual(row.requested_time, 'dimanche 10h');
    const toCustomer = dashSendsTo(DASH_CUSTOMER);
    assert.strictEqual(toCustomer.length, 1);
    assert.match(dashBody(toCustomer[0]), /dimanche 10h/);
    assert.strictEqual(row.agent_response_via, 'DASHBOARD');
  });

  const dashNoTime = await dashAnswer(dashResched.id, 'RESCHEDULED', { requestedTime: '   ' });
  check('rescheduling needs a real slot', () =>
    assert.strictEqual(dashNoTime.reason, 'requested-time-required'));

  await dashAnswer(dashResched.id, 'RESCHEDULED', { requestedTime: 'quand vous voulez' });
  check('a new slot that names no instant clears the old check-in time', () =>
    assert.strictEqual(dbService.getViewingRequest(dashResched.id).scheduled_at, null));

  // --- Decline --------------------------------------------------------------

  const dashDecline = freshViewingRequest();
  httpCalls.length = 0;
  const dashDeclineResult = await dashAnswer(dashDecline.id, 'DECLINED');
  check('a dashboard Decline sends the customer real alternatives', () => {
    assert.strictEqual(dashDeclineResult.ok, true);
    assert.strictEqual(dashDeclineResult.alternatives, 1);
    const row = dbService.getViewingRequest(dashDecline.id);
    assert.strictEqual(row.status, 'DECLINED');
    assert.ok(row.customer_notified_at);
    const toCustomer = dashSendsTo(DASH_CUSTOMER);
    assert.strictEqual(toCustomer.length, 1);
    assert.match(dashBody(toCustomer[0]), /Studio Gombe/);
  });
  check('ops hears about a dashboard decline, and whether the customer was reached', () => {
    const toOps = dashSendsTo(DASH_OPS);
    assert.strictEqual(toOps.length, 1);
    assert.match(dashBody(toOps[0]), /tableau de bord/);
    assert.match(dashBody(toOps[0]), /Client prévenu/);
  });

  // --- Cancel ---------------------------------------------------------------

  const dashCancel = freshViewingRequest();
  await dashAnswer(dashCancel.id, 'CONFIRMED');
  httpCalls.length = 0;
  const dashCancelResult = await dashAnswer(dashCancel.id, 'CANCELLED');
  check('cancelling a confirmed visit tells the customer, with no alternatives pushed', () => {
    assert.strictEqual(dashCancelResult.ok, true);
    assert.strictEqual(dbService.getViewingRequest(dashCancel.id).status, 'CANCELLED');
    const toCustomer = dashSendsTo(DASH_CUSTOMER);
    assert.strictEqual(toCustomer.length, 1);
    assert.match(dashBody(toCustomer[0]), /annul/i);
    assert.doesNotMatch(dashBody(toCustomer[0]), /Studio Gombe/);
  });
  check('ops hears about a dashboard cancellation', () => {
    const toOps = dashSendsTo(DASH_OPS);
    assert.strictEqual(toOps.length, 1);
    assert.match(dashBody(toOps[0]), /annulée/);
  });

  // --- Through the real route -----------------------------------------------

  const dashRouteTarget = freshViewingRequest();
  const dashRouteOk = await adminRequest('POST', `/admin/viewing-requests/${dashRouteTarget.id}/agent-response`, {
    agent_id: DASHBOARD_AGENT_ID,
    status: 'CONFIRMED',
  });
  check('POST /admin/viewing-requests/:id/agent-response answers through the real route', () => {
    assert.strictEqual(dashRouteOk.status, 200);
    assert.strictEqual(dbService.getViewingRequest(dashRouteTarget.id).status, 'CONFIRMED');
  });

  const dashRouteForbidden = await adminRequest('POST', `/admin/viewing-requests/${freshViewingRequest().id}/agent-response`, {
    agent_id: 99999,
    status: 'CONFIRMED',
  });
  check('the route refuses an agent the request does not belong to (403)', () =>
    assert.strictEqual(dashRouteForbidden.status, 403));

  const dashRouteBadStatus = await adminRequest('POST', `/admin/viewing-requests/${dashRouteTarget.id}/agent-response`, {
    agent_id: DASHBOARD_AGENT_ID,
    status: 'COMPLETED',
  });
  check('the route refuses a status an agent cannot set (400)', () =>
    assert.strictEqual(dashRouteBadStatus.status, 400));

  const dashRouteUnknown = await adminRequest('POST', '/admin/viewing-requests/999999/agent-response', {
    agent_id: DASHBOARD_AGENT_ID,
    status: 'CONFIRMED',
  });
  check('an unknown request is a 404', () => assert.strictEqual(dashRouteUnknown.status, 404));

  // --- WhatsApp answers carry the same admin-visible stamps -----------------

  const waParity = freshViewingRequest('samedi 14h');
  await viewingNotifications.handleViewingButtonReply({ from: AGENT_WA, replyId: `viewing_accept:${waParity.id}` });
  check('a WhatsApp Accepter records its channel and that the customer was told', () => {
    const row = dbService.getViewingRequest(waParity.id);
    assert.strictEqual(row.agent_response_via, 'WHATSAPP');
    assert.ok(row.customer_notified_at);
  });
  dbService.clearPendingAgentAction(AGENT_WA);

  propertyRepo.getListingContactById = listingStubBefore21b;
  propertyMatching.matchProperties = matchBefore21b;
  if (opsBefore21b === undefined) delete process.env.OPS_WHATSAPP_NUMBER;
  else process.env.OPS_WHATSAPP_NUMBER = opsBefore21b;
  httpCalls.length = 0;

  // ===========================================================================
  // 22. Listing enquiry from the storefront's WhatsApp CTA
  //
  //     The message the site composes ("...Voir l'annonce :
  //     https://lukkaplace.com/listings/293") used to reach gpt-4o and come
  //     back as "pour vérifier la disponibilité, veuillez consulter
  //     directement l'annonce sur notre site" — sent to somebody who had
  //     just come from that page. These checks pin the two things that
  //     stopped it: the reply is produced without a model call at all, and
  //     a real human is told the enquiry exists.
  // ===========================================================================

  console.log('\n22. Listing enquiry (storefront WhatsApp CTA)');

  const listingEnquiry = require('../services/listingEnquiry');

  const ENQUIRY_WA = '243991234567';
  // Exactly what web/lib/whatsapp.js's buildWhatsAppMessage produces now.
  const ENQUIRY_TEXT = 'Bonjour, je vous contacte via Lukka Place au sujet de ce bien :\n'
    + 'Appartement à Limete — 1 100 $ / mois\n'
    + 'Réf. Petit Boulevard, 2ᵉ Rue Industrielle\n'
    + '\n'
    + 'Est-il toujours disponible ? Si oui, quand serait-il possible de le visiter ?\n'
    + '\n'
    + 'https://lukkaplace.com/listings/293';

  check('the real storefront message yields the listing id and the quoted reference', () => {
    const parsed = listingEnquiry.parseListingEnquiry(ENQUIRY_TEXT);
    assert.strictEqual(parsed.propertyId, 293);
    assert.strictEqual(parsed.reference, 'Petit Boulevard, 2ᵉ Rue Industrielle');
  });

  // A listing with no reference: the storefront writes no Réf line at all.
  check('a storefront message with no Réf line still resolves, with no reference', () => {
    const parsed = listingEnquiry.parseListingEnquiry(
      'Bonjour, je vous contacte via Lukka Place au sujet de ce bien :\n'
        + 'Appartement à Limete — 700 $ / mois\n\n'
        + 'Est-il toujours disponible ? Si oui, quand serait-il possible de le visiter ?\n\n'
        + 'https://lukkaplace.com/listings/286',
    );
    assert.strictEqual(parsed.propertyId, 286);
    assert.strictEqual(parsed.reference, null);
  });

  // Links pre-typed by the old builder are still sitting in people's chats.
  check('the previous storefront wording is still recognised', () => {
    const parsed = listingEnquiry.parseListingEnquiry(
      "Bonjour, je suis intéressé par l'annonce Ref: Petit Boulevard, 2ᵉ Rue "
        + 'Industrielle (Appartement à Limete) — 1 100 $ / mois. Est-elle toujours disponible ?\n'
        + "Voir l'annonce : https://lukkaplace.com/listings/293",
    );
    assert.strictEqual(parsed.propertyId, 293);
    assert.strictEqual(parsed.reference, 'Petit Boulevard, 2ᵉ Rue Industrielle');
  });

  check('a hyphenated reference is not cut at the hyphen', () =>
    assert.strictEqual(
      listingEnquiry.parseListingEnquiry('Réf. Ngiri-Ngiri\nhttps://lukkaplace.com/listings/5').reference,
      'Ngiri-Ngiri',
    ));

  check('an ordinary property advert is not mistaken for an enquiry', () =>
    assert.strictEqual(
      listingEnquiry.parseListingEnquiry('Villa a louer Ngaliema 4 chambres 2500$/mois'),
      null,
    ));

  // Host-anchored on purpose: an agent pasting a competitor's link must not
  // be answered as though they were asking about one of ours.
  check("a listing link on somebody else's domain is not one of ours", () =>
    assert.strictEqual(
      listingEnquiry.parseListingEnquiry('regarde https://example.com/listings/293'),
      null,
    ));

  check('a localhost link from QA is still recognised', () =>
    assert.strictEqual(
      listingEnquiry.parseListingEnquiry('http://localhost:3002/listings/42').propertyId,
      42,
    ));

  // --- The reply itself -----------------------------------------------------

  const ENQUIRY_LISTING = {
    id: '293',
    reference: 'Petit Boulevard, 2ᵉ Rue Industrielle',
    title: '2 chambres — Appartement à louer à Limete',
    slug: '2-chambres-appartement-a-louer-a-limete-293',
    commune: 'Limete',
    agent_id: '43',
    agent_phone: '243821122937',
    phone_verified_at: '2026-09-09T17:46:02.802Z',
    agent_name: 'Kkimmo',
  };

  check('the reply never sends the customer back to the page they came from', () => {
    const reply = listingEnquiry.customerReply({
      listing: ENQUIRY_LISTING, propertyId: 293, quotedReference: null, reached: true,
    });
    assert.match(reply, /vérifie la disponibilité auprès du bailleur/);
    assert.match(reply, /Souhaitez-vous programmer une visite/);
    // The exact shape of the old failure: telling them to go and look at the
    // listing on the website they had just come from.
    assert.doesNotMatch(reply, /consulter.*sur notre site/i);
    assert.doesNotMatch(reply, /site web/i);
  });

  check('when nobody was reached, no callback is promised', () => {
    const reply = listingEnquiry.customerReply({
      listing: ENQUIRY_LISTING, propertyId: 293, quotedReference: null, reached: false,
    });
    assert.doesNotMatch(reply, /recontactera/);
    assert.match(reply, /pas pu joindre/);
    // It has to leave them somewhere real instead.
    assert.match(reply, /lukkaplace\.com\/listings\//);
  });

  check('a listing with no reference code never reads "Ref: null"', () => {
    const reply = listingEnquiry.customerReply({
      listing: { ...ENQUIRY_LISTING, reference: null },
      propertyId: 293,
      quotedReference: null,
      reached: true,
    });
    assert.doesNotMatch(reply, /null/);
    assert.doesNotMatch(reply, /R[ée]f/);
    // Once, not "Ref: {title} ({title})" as the label fallback used to print it.
    assert.strictEqual(reply.split('2 chambres — Appartement à louer à Limete').length - 1, 1);
  });

  check('the reply names the reference once, beside the title', () =>
    assert.match(
      listingEnquiry.customerReply({ listing: ENQUIRY_LISTING, propertyId: 293, reached: true }),
      /le bien « 2 chambres — Appartement à louer à Limete » \(Réf\. Petit Boulevard, 2ᵉ Rue Industrielle\)/,
    ));

  // The old storefront fell back to the slug, and "Ref: 2-chambres-…" was
  // cut at the first hyphen — the alert then named the listing "2".
  check("a quoted slug never beats the listing's own title in the alert", () =>
    assert.strictEqual(
      listingEnquiry.listingLabel({ ...ENQUIRY_LISTING, reference: null }, 286, '2-chambres-appartement-a-louer-a-limete-286'),
      '2 chambres — Appartement à louer à Limete',
    ));

  // --- End to end, through the real route -----------------------------------

  const realEnquiryLookup = propertyRepo.getListingContactById;
  propertyRepo.getListingContactById = async (id) => (
    Number(id) === 293 ? ENQUIRY_LISTING : null
  );

  httpCalls.length = 0;
  const openaiCallsBeforeEnquiry = openaiCalls.length;
  await post('/webhook', inbound('wamid.ENQUIRY', ENQUIRY_TEXT, ENQUIRY_WA));
  await settle();

  check('the enquiry is answered without a single gpt-4o call', () =>
    assert.strictEqual(
      openaiCalls.length,
      openaiCallsBeforeEnquiry,
      'the enquiry still reached the extraction model',
    ));

  check('the listing agent is told, and the customer gets a reply', () => {
    const recipients = httpCalls.map((c) => c.data.to);
    assert.ok(recipients.includes('243821122937'), `agent not notified (sent to ${recipients})`);
    assert.ok(recipients.includes(ENQUIRY_WA), `customer not answered (sent to ${recipients})`);
  });

  check('the agent alert names the listing, the commune and the customer', () => {
    const toAgent = httpCalls.find((c) => c.data.to === '243821122937');
    const body = toAgent.data.text.body;
    assert.match(body, /Petit Boulevard/);
    assert.match(body, /Limete/);
    assert.match(body, new RegExp(`\\+${ENQUIRY_WA}`));
  });

  check('the enquiry is recorded as a real, distinguishable lead', () => {
    const leads = dbService.listLeads({ limit: 200 }).data
      .filter((l) => l.wa_id === ENQUIRY_WA);
    assert.strictEqual(leads.length, 1);
    assert.strictEqual(leads[0].source, 'listing-whatsapp-enquiry');
    assert.strictEqual(Number(leads[0].property_id), 293);
  });

  check('the enquiry was not also stored as a listing', () =>
    assert.strictEqual(dbService.findByWamid('wamid.ENQUIRY'), undefined));

  // --- The fall-through that keeps this safe --------------------------------
  //
  // A link naming a listing that is not live (pending moderation, retired,
  // or simply wrong) must not be answered with a promise about a property we
  // cannot confirm exists. It falls through to ordinary processing instead.

  httpCalls.length = 0;
  await post(
    '/webhook',
    inbound(
      'wamid.DEADLINK',
      'Villa a louer Ngaliema 4 chambres 2500$/mois — https://lukkaplace.com/listings/999999',
      '243991234568',
    ),
  );
  await settle();

  check('a link to a listing that is not live falls through to the intake path', () => {
    const stored = dbService.findByWamid('wamid.DEADLINK');
    assert.ok(stored, 'the message was swallowed on the strength of a URL alone');
  });

  propertyRepo.getListingContactById = realEnquiryLookup;
  // -------------------------------------------------------------------------
  // 23. Messaging infrastructure: templates that can reach a cold contact
  //
  // Two distinct bugs are pinned here.
  //
  // (a) sendInteractiveButtons is a SESSION message type. Meta will not
  //     deliver it outside the 24h window, so the whole agent feedback loop
  //     silently stops existing for anyone who has not messaged us recently.
  //     A template is the only way to put buttons in front of a cold contact,
  //     which is what the quick_reply component support is for.
  //
  // (b) AGENT_LEAD_MATCH_TEMPLATE and AGENT_OTP_TEMPLATE used to default to
  //     names Meta has never heard of, so every send paid a
  //     guaranteed-failing round trip (seven per lead dispatch) before
  //     falling back to the session message that was always going to be what
  //     actually sent — and that failure was indistinguishable in the logs
  //     from an APPROVED template failing to deliver.
  // -------------------------------------------------------------------------

  console.log('\n23. Messaging infrastructure (templates, quick replies, ops number)');

  const viewingNotif = require('../services/viewingNotifications');

  check('templateConfigured tells "unset" apart from "set"', () => {
    assert.strictEqual(chakra.templateConfigured(null), false);
    assert.strictEqual(chakra.templateConfigured(undefined), false);
    assert.strictEqual(chakra.templateConfigured(''), false);
    assert.strictEqual(chakra.templateConfigured('   '), false, 'whitespace is not a template name');
    assert.strictEqual(chakra.templateConfigured('viewing_request'), true);
  });

  httpCalls.length = 0;
  await chakra.sendTemplate('243850000123', 'viewing_request', {
    languageCode: 'fr',
    bodyParams: ['Marie', 'Villa Gombe', 'Jean', 'demain 14h', 'https://lukkaplace.com'],
    buttons: [
      { id: 'viewing_accept:47' },
      { id: 'viewing_reschedule:47' },
      { id: 'viewing_decline:47' },
    ],
  });

  check('a template carries its quick-reply buttons as real components', () => {
    const sent = httpCalls[httpCalls.length - 1].data;
    assert.strictEqual(sent.type, 'template');
    const buttons = sent.template.components.filter((c) => c.type === 'button');
    assert.strictEqual(buttons.length, 3, 'all three buttons must travel');
    assert.deepStrictEqual(
      buttons.map((b) => b.sub_type),
      ['quick_reply', 'quick_reply', 'quick_reply'],
    );
    // index must match the order the template declares its buttons in — a
    // mismatch is a 400, not a silently mislabelled button.
    assert.deepStrictEqual(buttons.map((b) => b.index), ['0', '1', '2']);
  });

  check('the payload is the SAME id the interactive path produces', () => {
    // This is what makes the loop work unchanged: the payload comes back on
    // the inbound webhook as interactive.button_reply.id either way, so
    // parseViewingButtonId needs no branch for "arrived via template".
    const sent = httpCalls[httpCalls.length - 1].data;
    const payloads = sent.template.components
      .filter((c) => c.type === 'button')
      .map((c) => c.parameters[0].payload);
    assert.deepStrictEqual(payloads, [
      'viewing_accept:47',
      'viewing_reschedule:47',
      'viewing_decline:47',
    ]);
    for (const payload of payloads) {
      assert.ok(viewingNotif.parseViewingButtonId(payload), payload + ' must still parse');
    }
  });

  check('the body parameters are untouched by the button support', () => {
    const sent = httpCalls[httpCalls.length - 1].data;
    const body = sent.template.components.find((c) => c.type === 'body');
    assert.deepStrictEqual(
      body.parameters.map((p) => p.text),
      ['Marie', 'Villa Gombe', 'Jean', 'demain 14h', 'https://lukkaplace.com'],
    );
  });

  httpCalls.length = 0;
  await chakra.sendTemplate('243850000123', 'agent_auth_otp', {
    bodyParams: ['123456'],
    otpCode: '123456',
  });
  check('the AUTHENTICATION copy-code button path is unchanged', () => {
    const sent = httpCalls[httpCalls.length - 1].data;
    const buttons = sent.template.components.filter((c) => c.type === 'button');
    assert.strictEqual(buttons.length, 1);
    assert.strictEqual(buttons[0].sub_type, 'url');
    assert.strictEqual(buttons[0].index, '0');
  });

  await checkAsync('otpCode and quick-reply buttons cannot be combined', async () => {
    // An AUTHENTICATION template's copy-code button already claims index 0.
    await assert.rejects(
      () => chakra.sendTemplate('243850000123', 't', { otpCode: '1', buttons: [{ id: 'x' }] }),
      /cannot combine otpCode with quick-reply/,
    );
  });

  await checkAsync("Meta's own quick-reply limits are enforced here, not discovered as a 400", async () => {
    await assert.rejects(
      () => chakra.sendTemplate('243850000123', 't', { buttons: [] }),
      /1-3 quick-reply buttons/,
    );
    await assert.rejects(
      () => chakra.sendTemplate('243850000123', 't', {
        buttons: [{ id: 'a' }, { id: 'b' }, { id: 'c' }, { id: 'd' }],
      }),
      /1-3 quick-reply buttons/,
    );
    await assert.rejects(
      () => chakra.sendTemplate('243850000123', 't', { buttons: [{ title: 'no id' }] }),
      /needs an id/,
    );
    await assert.rejects(
      () => chakra.sendTemplate('243850000123', 't', { buttons: [{ id: 'x'.repeat(129) }] }),
      /128-character limit/,
    );
  });

  check('an unconfigured lead-match template no longer defaults to a name Meta rejects', () => {
    // The whole point: seven guaranteed-failing round trips per lead is not a
    // fallback strategy, it is a tax. Asserted on the SOURCE rather than by
    // driving a dispatch, because ranking agents needs a live Postgres this
    // suite deliberately does not have.
    const dispatchSource = fs.readFileSync(
      path.join(__dirname, '..', 'services', 'leadDispatch.js'),
      'utf8',
    );
    assert.ok(
      /AGENT_LEAD_MATCH_TEMPLATE \|\| null/.test(dispatchSource),
      "leadDispatch must default the template name to null, not to 'agent_lead_match'",
    );
    assert.ok(
      /templateConfigured\(name\)/.test(dispatchSource),
      'leadDispatch must skip straight to the session message when no template is configured',
    );
  });

  // OPS_WHATSAPP_NUMBER is read at CALL time, so ops can be pointed at a
  // different handset without restarting the engine.
  const savedOpsNumber = process.env.OPS_WHATSAPP_NUMBER;
  check('the ops number is read at call time, not frozen at module load', () => {
    delete process.env.OPS_WHATSAPP_NUMBER;
    assert.strictEqual(viewingNotif.opsNumber(), null);

    process.env.OPS_WHATSAPP_NUMBER = '+243 81 555 0000';
    assert.strictEqual(
      viewingNotif.opsNumber(),
      '243815550000',
      'a formatted number must be normalised to digits, and picked up without a restart',
    );
  });
  check('an unset ops number is announced at boot, not at 2am', () => {
    delete process.env.OPS_WHATSAPP_NUMBER;
    assert.strictEqual(viewingNotif.warnIfOpsUnconfigured(), true);
    process.env.OPS_WHATSAPP_NUMBER = '243815550000';
    assert.strictEqual(viewingNotif.warnIfOpsUnconfigured(), false);
  });
  if (savedOpsNumber === undefined) delete process.env.OPS_WHATSAPP_NUMBER;
  else process.env.OPS_WHATSAPP_NUMBER = savedOpsNumber;
  // -------------------------------------------------------------------------
  // 24. The multi-job scheduler
  //
  // The tick used to be ten minutes and run one hardcoded weekly sweep. That
  // interval is why it could not host anything else: a 15-minute SLA checked
  // every 10 minutes fires between 15 and 25 minutes late, which is not a
  // 15-minute SLA.
  //
  // §18 above still drives the weekly sweep's own gate and must keep passing
  // unchanged — this section is about the runner around it.
  // -------------------------------------------------------------------------

  console.log('\n24. Multi-job scheduler dispatch');

  const sched = require('../services/scheduler');

  check('the tick is fine enough to enforce the tightest deadline on it', () => {
    const { SLA_MS } = require('../services/viewingSweeps');
    assert.strictEqual(sched.TICK_MS, 60 * 1000);
    assert.ok(
      sched.TICK_MS <= SLA_MS,
      'a tick coarser than the SLA it enforces cannot enforce it',
    );
  });

  check('the alert sweep, both speed-to-lead sweeps, the ops alert sweep, the analytics rollup and the commission run are registered', () => {
    const names = sched.JOBS.map((j) => j.name);
    assert.deepStrictEqual(names, [
      'search-alerts', 'viewing-contact-check', 'viewing-sla', 'viewing-proposal-followup', 'viewing-checkin', 'viewing-agent-done', 'chat-notify', 'ops-health-alerts', 'listing-stats-rollup', 'draft-auto-submit', 'trusted-auto-approve', 'agent-daily-digest',
      'listing-availability-check', 'market-snapshot', 'ops-desk-keepalive', 'sales-commissions', 'growth-daily', 'market-observations', 'move-request-followup', 'listing-auto-pause', 'lead-waves', 'push-fallback', 'visit-reminders', 'favorite-status', 'request-followup', 'instant-alerts', 'search-checkup', 'portal-daily', 'weekly-summary', 'monthly-market', 'sqlite-backup',
    ]);
  });

  check('a malformed job is refused rather than silently never running', () => {
    assert.throws(() => sched.registerJob({}), /needs \{ name, shouldRun/);
    assert.throws(() => sched.registerJob({ name: 'x', shouldRun: 1, run: 1 }), /needs \{ name/);
    assert.throws(
      () => sched.registerJob({ name: 'viewing-sla', shouldRun: () => false, run: async () => {} }),
      /already registered/,
      'a duplicate name would make job_runs ambiguous',
    );
  });

  await checkAsync('a job that is not due does not run and records nothing', async () => {
    let ran = false;
    const before = dbService.getLastJobRun('probe-not-due');
    const did = await sched.runJob(
      { name: 'probe-not-due', shouldRun: () => false, run: async () => { ran = true; } },
    );
    assert.strictEqual(did, false);
    assert.strictEqual(ran, false);
    assert.strictEqual(dbService.getLastJobRun('probe-not-due'), before);
  });

  await checkAsync('a due job runs and its success is recorded', async () => {
    const did = await sched.runJob(
      { name: 'probe-due', shouldRun: () => true, run: async () => ({ handled: 2 }) },
    );
    assert.strictEqual(did, true);
    const run = dbService.getLastJobRun('probe-due');
    assert.ok(run.succeeded_at, 'a successful run must advance succeeded_at');
    assert.match(run.detail, /handled/);
  });

  await checkAsync('a throwing job is recorded as a failure and does NOT advance succeeded_at', async () => {
    // Same rule §18 pins for the weekly sweep: a failure must not consume the
    // window, or one bad attempt skips the whole period.
    await sched.runJob(
      { name: 'probe-throws', shouldRun: () => true, run: async () => { throw new Error('boom'); } },
    );
    const run = dbService.getLastJobRun('probe-throws');
    assert.strictEqual(run.succeeded_at, null);
    assert.match(run.last_error, /boom/);
  });

  await checkAsync('a job whose shouldRun throws is skipped, not fatal', async () => {
    const did = await sched.runJob({
      name: 'probe-bad-gate',
      shouldRun: () => { throw new Error('gate exploded'); },
      run: async () => { throw new Error('must never be reached'); },
    });
    assert.strictEqual(did, false);
  });

  await checkAsync('one failing job never stops the jobs behind it', async () => {
    // The whole point of the registry: the SLA sweep throwing must not take
    // the post-visit check-in down with it.
    const order = [];
    const saved = sched.JOBS.splice(0, sched.JOBS.length);
    try {
      sched.JOBS.push(
        { name: 'probe-a', shouldRun: () => true, run: async () => { order.push('a'); throw new Error('a failed'); } },
        { name: 'probe-b', shouldRun: () => true, run: async () => { order.push('b'); } },
      );
      await sched.tick(new Date());
      assert.deepStrictEqual(order, ['a', 'b'], 'b must still run after a threw');
    } finally {
      sched.JOBS.splice(0, sched.JOBS.length, ...saved);
    }
  });

  // -------------------------------------------------------------------------
  // 25. The 15-minute unanswered-request SLA
  //
  // job_runs is keyed by job NAME and can only ever answer "did the sweep
  // run". "Have we already alerted on request #47" is a fact about the
  // request, and lives on the row — which is what these assertions are really
  // about.
  // -------------------------------------------------------------------------

  console.log('\n25. 15-minute unanswered-request SLA');

  const sweeps = require('../services/viewingSweeps');
  const OPS_WA = '243815550000';

  /**
   * A PENDING request, plus a lead carrying real requirements.
   *
   * Nothing is back-dated: every selector here takes `now`, so the tests
   * travel forward instead of rewriting created_at. That keeps them
   * independent of when the suite runs AND of SQLite's timestamp format.
   */
  function pendingViewingRequest() {
    const lead = dbService.createLead({
      wa_id: '243990111222',
      name: 'Henoc Mimbo',
      source: 'listing-visit-request',
      property_id: 303,
      transaction_type: 'location',
      commune: 'Gombe',
      price_max: 900,
      bedrooms: 2,
    });
    const request = dbService.createViewingRequest({
      leadId: lead.id,
      propertyId: 303,
      requestedTime: 'samedi 14h',
    });
    return { lead, request };
  }

  check('the SLA is fifteen minutes, and the check-in two hours', () => {
    assert.strictEqual(sweeps.SLA_MS, 15 * 60 * 1000);
    assert.strictEqual(sweeps.CHECKIN_AFTER_MS, 2 * 60 * 60 * 1000);
  });

  // A request created now is not yet late.
  const slaFresh = pendingViewingRequest();
  check('a request inside the SLA window is not selected', () => {
    const due = dbService.listViewingRequestsAwaitingSla(sweeps.SLA_MS, new Date().toISOString());
    assert.ok(
      !due.some((r) => r.id === slaFresh.request.id),
      'a request made a moment ago must not be escalated',
    );
  });

  check('a request past the SLA is selected, with its lead joined in', () => {
    const future = new Date(Date.now() + 20 * 60 * 1000).toISOString();
    const due = dbService.listViewingRequestsAwaitingSla(sweeps.SLA_MS, future);
    const mine = due.find((r) => r.id === slaFresh.request.id);
    assert.ok(mine, 'a request older than the SLA must be picked up');
    // The customer's number lives on the lead, never on the request.
    assert.strictEqual(mine.lead_wa_id, '243990111222');
    assert.strictEqual(mine.lead_transaction_type, 'location');
    assert.strictEqual(mine.lead_price_max, 900);
  });

  // --- The sweep itself -----------------------------------------------------

  const realMatch = propertyMatching.matchProperties;
  const matchArgs = [];
  propertyMatching.matchProperties = async (criteria) => {
    matchArgs.push(criteria);
    return {
      data: [
        { id: 401, title: 'Appartement 2 ch — Gombe', price: 850, slug: 'appt-gombe' },
        { id: 303, title: 'Le bien déjà demandé', price: 800, slug: 'deja' },
        { id: 402, title: 'Studio — Gombe', price: 700, slug: 'studio-gombe' },
      ],
      total: 3,
      widened: false,
      error: false,
    };
  };
  const realContactLookup = propertyRepo.getListingContactById;
  propertyRepo.getListingContactById = async () => ({
    id: 303, title: 'Villa Kkimmo', reference: 'LKP-303', commune: 'Gombe',
    agent_id: 91, agent_phone: '243821122937', phone_verified_at: '2026-08-01T09:00:00.000Z',
    agent_name: 'Marie',
  });

  process.env.OPS_WHATSAPP_NUMBER = OPS_WA;
  httpCalls.length = 0;
  const slaFuture = new Date(Date.now() + 20 * 60 * 1000);
  const slaResult = await sweeps.runSlaSweep(slaFuture);

  check('the sweep escalates the overdue request', () => {
    assert.ok(slaResult.alerted >= 1, 'at least the aged request must be alerted');
  });

  check('ops is told, and the customer gets alternatives', () => {
    const tos = httpCalls.map((c) => c.data.to);
    assert.ok(tos.includes(OPS_WA), 'ops must receive the escalation');
    assert.ok(tos.includes('243990111222'), 'the customer must hear something');
  });

  check("the alternatives match what the customer actually asked for", () => {
    // The decline path passed only the commune, so a rental shopper could be
    // offered a sale. The lead already carries all of this.
    const last = matchArgs[matchArgs.length - 1];
    assert.strictEqual(last.transactionType, 'location');
    assert.strictEqual(last.commune, 'Gombe');
    assert.strictEqual(last.priceMax, 900);
    assert.strictEqual(last.bedsMin, 2);
  });

  check('the property they are waiting on is never offered back to them', () => {
    const toClient = httpCalls.find((c) => c.data.to === '243990111222').data.text.body;
    assert.ok(!/Le bien déjà demandé/.test(toClient), 'the requested listing must be excluded');
    assert.match(toClient, /Appartement 2 ch/);
  });

  check('the ops alert says WHY the agent did not answer', () => {
    // "never received it, unverified number" and "received it and ignored it"
    // need different responses and must not read the same.
    const toOps = httpCalls.find((c) => c.data.to === OPS_WA).data.text.body;
    assert.match(toOps, /a bien été alerté/i);
  });

  check('the request stays PENDING — response rate must stay measurable', () => {
    const after = dbService.getViewingRequest(slaFresh.request.id);
    assert.strictEqual(after.status, 'PENDING', 'the agent can still accept it');
    assert.ok(after.sla_alerted_at, 'the escalation is stamped on the row, not in job_runs');
  });

  httpCalls.length = 0;
  const slaSecond = await sweeps.runSlaSweep(new Date(Date.now() + 40 * 60 * 1000));
  check('the escalation fires once and only once', () => {
    // job_runs cannot express this at all: it holds one row per job NAME, so
    // per-request idempotence has to live on the request.
    const stillDue = dbService.listViewingRequestsAwaitingSla(
      sweeps.SLA_MS,
      new Date(Date.now() + 40 * 60 * 1000).toISOString(),
    );
    assert.ok(
      !stillDue.some((r) => r.id === slaFresh.request.id),
      'an already-alerted request must never be selected again',
    );
    assert.ok(dbService.getViewingRequest(slaFresh.request.id).sla_alerted_at);
  });

  // -------------------------------------------------------------------------
  // 26. The 2-hour post-visit check-in
  // -------------------------------------------------------------------------

  console.log('\n26. Post-visit check-in');

  const CUSTOMER_WA = '243990111222';

  function confirmedVisit(scheduledAtIso) {
    const lead = dbService.createLead({
      wa_id: CUSTOMER_WA, name: 'Henoc Mimbo', source: 'listing-visit-request', property_id: 303,
    });
    const req = dbService.createViewingRequest({
      leadId: lead.id, propertyId: 303, requestedTime: 'samedi 14h',
    });
    dbService.updateViewingRequest(req.id, { status: 'CONFIRMED' });
    if (scheduledAtIso) dbService.setViewingScheduledAt(req.id, scheduledAtIso);
    return { lead, request: dbService.getViewingRequest(req.id) };
  }

  const visitNow = new Date('2026-09-20T12:00:00.000Z');
  const visited = confirmedVisit(visitNow.toISOString());

  check('a visit that has only just happened is not asked about yet', () => {
    const due = dbService.listViewingRequestsDueForCheckin(
      sweeps.CHECKIN_AFTER_MS,
      new Date(visitNow.getTime() + 60 * 60 * 1000).toISOString(),
    );
    assert.ok(
      !due.some((r) => r.id === visited.request.id),
      'one hour after the slot is too early — the visit may still be running',
    );
  });

  check('a visit two hours old is due', () => {
    const due = dbService.listViewingRequestsDueForCheckin(
      sweeps.CHECKIN_AFTER_MS,
      new Date(visitNow.getTime() + 2 * 60 * 60 * 1000 + 1000).toISOString(),
    );
    assert.ok(due.some((r) => r.id === visited.request.id));
  });

  const noSlot = confirmedVisit(null);
  check('a confirmed visit with no agreed instant is NEVER asked about', () => {
    // Asking "how was your visit?" about a visit that may not have happened is
    // worse than not asking. requested_time is free text and cannot be counted
    // from.
    const due = dbService.listViewingRequestsDueForCheckin(
      sweeps.CHECKIN_AFTER_MS,
      new Date(Date.now() + 365 * 24 * 3600 * 1000).toISOString(),
    );
    assert.ok(!due.some((r) => r.id === noSlot.request.id));
  });

  httpCalls.length = 0;
  const checkinAt = new Date(visitNow.getTime() + 3 * 60 * 60 * 1000);
  const checkinResult = await sweeps.runCheckinSweep(checkinAt);

  check('the check-in reaches the customer, not the agent', () => {
    assert.ok(checkinResult.sent >= 1);
    const tos = httpCalls.map((c) => c.data.to);
    assert.ok(tos.includes(CUSTOMER_WA), 'the person who attended is the one asked');
    assert.ok(!tos.includes('243821122937'), 'the agent is not asked how their own visit went');
  });

  check('it asks the question in French and offers the three real answers', () => {
    const sent = httpCalls.find((c) => c.data.to === CUSTOMER_WA);
    const body = sent.data.interactive
      ? sent.data.interactive.body.text
      : sent.data.text.body;
    assert.match(body, /Comment s'est passée votre visite/);
    if (sent.data.interactive) {
      const titles = sent.data.interactive.action.buttons.map((b) => b.reply.title);
      assert.deepStrictEqual(titles, ['👍 Bien', '👎 Déçu', '⚠️ Agent absent']);
    }
  });

  check('the check-in is stamped so it is sent once, not once a minute', () => {
    assert.ok(dbService.getViewingRequest(visited.request.id).checkin_sent_at);
    const again = dbService.listViewingRequestsDueForCheckin(
      sweeps.CHECKIN_AFTER_MS, checkinAt.toISOString(),
    );
    assert.ok(!again.some((r) => r.id === visited.request.id));
  });

  // --- The customer's answer ------------------------------------------------

  check('a check-in button id names both the answer and the request', () => {
    assert.deepStrictEqual(
      sweeps.parseCheckinButtonId('visit_feedback_good:7'),
      { action: 'good', viewingRequestId: 7 },
    );
    assert.strictEqual(sweeps.parseCheckinButtonId('viewing_accept:7'), null,
      "the agent loop's buttons must fall through, not be swallowed here");
    assert.strictEqual(viewingNotifications.parseViewingButtonId('visit_feedback_good:7'), null,
      'and the reverse, so the two handlers cannot eat each other');
  });

  httpCalls.length = 0;
  const goodOutcome = await sweeps.handleCheckinButtonReply({
    from: CUSTOMER_WA,
    replyId: `visit_feedback_good:${visited.request.id}`,
  });

  check('👍 is recorded against the request', () => {
    assert.strictEqual(goodOutcome.handled, true);
    assert.strictEqual(dbService.getViewingRequest(visited.request.id).checkin_response, 'GOOD');
  });

  check('a completed visit finally reaches VIEWING_COMPLETED', () => {
    // The status has existed in LEAD_STATUSES since it was written and no code
    // path could reach it until now.
    assert.strictEqual(dbService.getLead(visited.lead.id).status, 'VIEWING_COMPLETED');
  });

  await checkAsync('somebody else cannot answer for the customer', async () => {
    const other = confirmedVisit(visitNow.toISOString());
    const refused = await sweeps.handleCheckinButtonReply({
      from: '243999000111',
      replyId: `visit_feedback_good:${other.request.id}`,
    });
    assert.strictEqual(refused.ignored, 'not-this-requests-customer');
    assert.strictEqual(dbService.getViewingRequest(other.request.id).checkin_response, null);
  });

  const absent = confirmedVisit(visitNow.toISOString());
  dbService.setPendingCustomerAction({
    waId: CUSTOMER_WA, kind: 'VISIT_FEEDBACK', viewingRequestId: absent.request.id,
  });
  httpCalls.length = 0;
  const typedOutcome = await sweeps.handleCustomerTextReply({ from: CUSTOMER_WA, text: '3' });

  check('a typed 3 is accepted exactly as a tap on "Agent non présent"', () => {
    assert.strictEqual(typedOutcome.handled, true);
    assert.strictEqual(
      dbService.getViewingRequest(absent.request.id).checkin_response,
      'AGENT_ABSENT',
    );
  });

  check('a no-show escalates to ops the same day', () => {
    const toOps = httpCalls.filter((c) => c.data.to === OPS_WA);
    assert.ok(toOps.length >= 1, 'ops must hear about an agent who did not turn up');
    assert.match(toOps[toOps.length - 1].data.text.body, /Agent non présent/);
  });

  await checkAsync('an ordinary message while a check-in is open falls through to intake', async () => {
    // The same posture the decline survey takes: a real property advert must
    // never be eaten because a questionnaire happened to be open.
    dbService.setPendingCustomerAction({
      waId: CUSTOMER_WA, kind: 'VISIT_FEEDBACK', viewingRequestId: absent.request.id,
    });
    const passthrough = await sweeps.handleCustomerTextReply({
      from: CUSTOMER_WA,
      text: 'Villa a louer Ngaliema 4 chambres 2500$',
    });
    assert.strictEqual(passthrough.handled, false);
  });

  dbService.clearPendingCustomerAction(CUSTOMER_WA);
  propertyMatching.matchProperties = realMatch;
  propertyRepo.getListingContactById = realContactLookup;
  delete process.env.OPS_WHATSAPP_NUMBER;

  // -------------------------------------------------------------------------
  // 27. French slot parsing (services/visitSchedule.js)
  //
  // Pure, and takes `now`, so none of this depends on when the suite runs.
  // -------------------------------------------------------------------------

  console.log('\n27. French slot parsing');

  const { parseFrenchSlot, formatSlotFr } = require('../services/visitSchedule');
  // Friday 2026-09-11, 09:00 in Kinshasa (UTC+1).
  const FRI = new Date('2026-09-11T08:00:00Z');

  check('a real slot becomes a real instant, in UTC', () => {
    const slot = parseFrenchSlot('demain 14h', FRI);
    // 14:00 Kinshasa on Saturday = 13:00 UTC.
    assert.strictEqual(slot.iso, '2026-09-12T13:00:00.000Z');
    assert.match(slot.iso, /Z$/, 'never a local offset — the sweep compares these as text');
  });

  check('a part of the day is a real time, not a missing one', () => {
    assert.strictEqual(parseFrenchSlot('samedi matin', FRI).iso, '2026-09-12T09:00:00.000Z');
    assert.strictEqual(parseFrenchSlot('ce soir', FRI).iso, '2026-09-11T17:00:00.000Z');
  });

  check('"midi" inside "après-midi" does not win', () => {
    // Most-specific-first, the same rule parseDeclineReason follows.
    assert.strictEqual(parseFrenchSlot('cet après-midi', FRI).iso, '2026-09-11T14:00:00.000Z');
  });

  check('an explicit hour beats the part of the day', () => {
    assert.strictEqual(parseFrenchSlot('samedi matin 11h', FRI).iso, '2026-09-12T10:00:00.000Z');
  });

  check('a day with no hour is REFUSED rather than guessed at', () => {
    // Inventing 9am would produce a confident-looking slot nobody agreed to,
    // and the check-in would then fire against it.
    assert.strictEqual(parseFrenchSlot('demain', FRI), null);
    assert.strictEqual(parseFrenchSlot('samedi', FRI), null);
    assert.strictEqual(parseFrenchSlot('la semaine prochaine', FRI), null);
  });

  check('nothing usable is null, never a crash', () => {
    for (const input of [null, undefined, '', '   ', 'bonjour', '????']) {
      assert.strictEqual(parseFrenchSlot(input, FRI), null, `input ${JSON.stringify(input)}`);
    }
  });

  check('a weekday resolves forward, never to a slot that has passed', () => {
    // "vendredi" typed ON a Friday means NEXT Friday. An agent naming a
    // weekday is proposing a future appointment, and resolving it to a few
    // hours ago would schedule a check-in for a visit nobody can attend.
    assert.strictEqual(parseFrenchSlot('vendredi 14h', FRI).iso, '2026-09-18T13:00:00.000Z');
    // A date that has already gone by is refused outright rather than rolled.
    assert.strictEqual(parseFrenchSlot('01/09 à 10h', FRI), null);
  });

  check('accents and separators do not change the answer', () => {
    const a = parseFrenchSlot('SAMEDI À 14H30', FRI);
    const b = parseFrenchSlot('samedi a 14:30', FRI);
    assert.strictEqual(a.iso, b.iso);
    assert.strictEqual(a.iso, '2026-09-12T13:30:00.000Z');
  });

  check('the slot is read back with a full date, never "demain"', () => {
    // This message can be read a day after it was sent, and "demain" would
    // then confirm the wrong day.
    const text = formatSlotFr(parseFrenchSlot('demain 14h', FRI).iso);
    assert.match(text, /samedi 12 septembre à 14h00/);
    assert.ok(!/demain/.test(text));
  });



  // -------------------------------------------------------------------------
  // 28. Direct-to-agent routing, WhatsApp price capture, agent performance
  //     (migrations/20260913_lead_routing_and_price_capture.sql)
  //
  //     A closing price is the one figure the market export exists to hold,
  //     so the parser is pinned in both directions: what it must read, and —
  //     just as important — what it must refuse (an advert, francs, a figure
  //     the model made up). Routing is pinned on what actually happened, and
  //     every rate the leaderboard shows is asserted against its SQL.
  // -------------------------------------------------------------------------

  console.log('\n28. Lead routing, WhatsApp price capture, agent performance');

  const priceExtraction = require('../services/priceExtraction');
  const agentPerformance = require('../services/agentPerformance');
  const realContactLookup28 = propertyRepo.getListingContactById;
  const realAgentLookup28 = propertyRepo.getAgentContactById;
  const realModelExtractor = priceExtraction.extractPriceWithModel;
  const LISTED = { ...ATTRIBUTED_LISTING, price: '750' };
  propertyRepo.getListingContactById = async () => LISTED;

  // --- 28a. Reading a closing price ----------------------------------------

  await checkAsync('a bare figure is saved as-is, exactly as the anchored parser always did', async () => {
    for (const [text, amount] of [['700', 700], ['1 100 $', 1100], ['1.200 USD', 1200], ['80', 80]]) {
      const r = await priceExtraction.parseAgentPriceResponse(text);
      assert.deepStrictEqual([r.amount, r.source, r.needsConfirmation], [amount, 'exact', false], text);
    }
  });

  await checkAsync('one amount inside a short sentence is read — and must be confirmed', async () => {
    const r = await priceExtraction.parseAgentPriceResponse('vendu à 700 dollars');
    assert.deepStrictEqual([r.amount, r.source, r.needsConfirmation], [700, 'regex', true]);
  });

  await checkAsync('a year beside the price is not mistaken for it (the spec regex read "2026")', async () => {
    assert.strictEqual((await priceExtraction.parseAgentPriceResponse('loué en septembre 2026 pour 650$')).amount, 650);
  });

  await checkAsync('"1,5k" is 1500', async () => {
    assert.strictEqual((await priceExtraction.parseAgentPriceResponse('1,5k')).amount, 1500);
  });

  await checkAsync('a property advert is never read as a price', async () => {
    const r = await priceExtraction.parseAgentPriceResponse('Appartement 3 chambres à Gombe 800$');
    assert.deepStrictEqual([r.amount, r.reason], [null, 'not-an-answer']);
  });

  await checkAsync('francs are refused, never converted', async () => {
    assert.strictEqual((await priceExtraction.parseAgentPriceResponse('500 000 FC')).reason, 'cdf');
  });

  await checkAsync('"depuis 3 mois" carries no price', async () => {
    assert.strictEqual((await priceExtraction.parseAgentPriceResponse('depuis 3 mois')).amount, null);
  });

  await checkAsync('number words go to the model, and its answer still needs confirming', async () => {
    priceExtraction.extractPriceWithModel = async () => ({ amount_usd: 700, currency: 'USD' });
    const r = await priceExtraction.parseAgentPriceResponse('sept cents dollars');
    assert.deepStrictEqual([r.amount, r.source, r.needsConfirmation], [700, 'llm', true]);
  });

  await checkAsync('the model may choose among the numbers in the text, never add one', async () => {
    priceExtraction.extractPriceWithModel = async () => ({ amount_usd: 900, currency: 'USD' });
    const invented = await priceExtraction.parseAgentPriceResponse('entre 700 et 750');
    assert.deepStrictEqual([invented.amount, invented.reason], [null, 'model-unsupported']);
    priceExtraction.extractPriceWithModel = async () => ({ amount_usd: 750, currency: 'USD' });
    assert.strictEqual((await priceExtraction.parseAgentPriceResponse('entre 700 et 750')).amount, 750);
    priceExtraction.extractPriceWithModel = async () => ({ amount_usd: 500000, currency: 'CDF' });
    assert.strictEqual((await priceExtraction.parseAgentPriceResponse('cinq cent mille')).amount, null);
  });

  check('the delta is sold minus listed, and that as a percentage of listed', () => {
    assert.deepStrictEqual(priceExtraction.computePriceDelta(750, 700), { deltaUsd: -50, deltaPct: -6.67 });
    assert.deepStrictEqual(priceExtraction.computePriceDelta(0, 700), { deltaUsd: null, deltaPct: null });
    assert.deepStrictEqual(priceExtraction.computePriceDelta(null, 700), { deltaUsd: null, deltaPct: null });
  });

  // --- 28b. The capture flow on WhatsApp -----------------------------------

  const captureTarget = freshViewingRequest();
  await viewingNotifications.handleViewingButtonReply({ from: AGENT_WA, replyId: `viewing_decline:${captureTarget.id}` });
  await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: '1' });

  check("an agent's decline is stored as a code, attributed to the agent", () => {
    const row = dbService.getViewingRequest(captureTarget.id);
    assert.strictEqual(row.decline_reason_code, 'PROPERTY_NO_LONGER_AVAILABLE');
    assert.strictEqual(row.decline_reason_by, 'AGENT');
  });

  check('the decline stamped a first response, for latency', () =>
    assert.ok(dbService.getViewingRequest(captureTarget.id).first_response_at));

  httpCalls.length = 0;
  const readBack = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: 'vendu à 700 dollars' });

  check('a price read out of a sentence is read back, and nothing is written yet', () => {
    assert.strictEqual(readBack.action, 'closing-price-confirm-asked');
    assert.strictEqual(readBack.amount, 700);
    const pending = dbService.getPendingAgentAction(AGENT_WA);
    assert.strictEqual(pending.kind, 'CLOSING_PRICE_CONFIRM');
    assert.strictEqual(pending.amount, 700);
    assert.match(httpCalls.find((c) => c.data.to === AGENT_WA).data.text.body, /Nous avons compris : 700 \$/);
  });

  httpCalls.length = 0;
  const confirmedPrice = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: 'Oui' });

  check('OUI writes the close, tagged as a WhatsApp agent reply', () => {
    assert.strictEqual(confirmedPrice.action, 'closing-price-recorded');
    assert.strictEqual(confirmedPrice.amount, 700);
    assert.strictEqual(confirmedPrice.source, 'WHATSAPP_AGENT_REPLY');
    assert.strictEqual(confirmedPrice.recorded, false, 'no database in this suite — reported honestly');
    assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA), undefined);
  });

  check('the receipt states the real gap against the asking price', () => {
    assert.strictEqual(confirmedPrice.deltaPct, -6.67);
    const body = httpCalls.find((c) => c.data.to === AGENT_WA).data.text.body;
    assert.match(body, /Prix conclu : 700 \$/);
    assert.match(body, /Prix affiché : 750 \$ \(écart : −6,7 %\)/);
  });

  const recaptureTarget = freshViewingRequest();
