      assert.deepStrictEqual(sent50.map((s) => s.to), ['243811111111', '243822222222']);
      assert.strictEqual((await ma50.alertPendingListing(listing50)).skipped, 'already-alerted');
      assert.strictEqual(sent50.length, 2);
