  // ---------------------------------------------------------------------------
  // §67 Growth launch (2026-10-27): customer signup on WhatsApp, the morning run
  // ---------------------------------------------------------------------------
  console.log('\n§67 Customer signup on WhatsApp and the growth morning run');
  {
    const customerOnboarding = require('../services/customerOnboarding');
    const growthDaily = require('../services/growthDaily');

    check('only the pre-typed wording is a signup; the code is read, "parrainage" is never matched', () => {
      assert.strictEqual(customerOnboarding.isSignupMessage('Inscription Lukka Place'), true);
      assert.strictEqual(customerOnboarding.isSignupMessage('  inscription sur Lukka Place — Code : NADIA01'), true);
      assert.strictEqual(customerOnboarding.isSignupMessage('Bonjour, inscription Lukka Place'), false);
      assert.strictEqual(customerOnboarding.isSignupMessage('Appartement à louer Gombe, inscription Lukka Place'), false);
      assert.strictEqual(customerOnboarding.codeIn('Inscription Lukka Place — Code : nadia01'), 'NADIA01');
      assert.strictEqual(customerOnboarding.codeIn('Inscription Lukka Place'), null);
      const webhook = fs.readFileSync(path.join(__dirname, '..', 'routes', 'webhook.js'), 'utf8');
      assert.ok(webhook.indexOf('handleCustomerSignupMessage') < webhook.indexOf('salesReferral.handleReferralMessage'),
        'the signup branch runs before the sales referral one');
    });

    // A fake Postgres client holding the statements this path issues.
    function fakePool67({ existing = false, partner = null } = {}) {
      const seen = [];
      const client = {
        async query(sql, params = []) {
          seen.push({ sql: sql.replace(/\s+/g, ' ').trim(), params });
          if (/^SELECT id FROM customers WHERE phone/.test(sql)) return { rows: existing ? [{ id: 77 }] : [] };
          if (/INSERT INTO customers/.test(sql)) return { rows: [{ id: 501 }] };
          if (/FROM partners p LEFT JOIN agents/.test(sql.replace(/\s+/g, ' '))) return { rows: partner ? [partner] : [] };
          return { rows: [], rowCount: 1 };
        },
        release() {},
      };
      return { seen, pool: { connect: async () => client } };
    }

    await checkAsync('a new number gets a verified account, a hashed single-use link, the partner credit and its acquisition row', async () => {
      const { seen, pool } = fakePool67({ partner: { id: 4, code: 'NADIA01', kind: 'creator', agent_phone: null } });
      const result = await customerOnboarding.createCustomerFromWhatsApp({ waId: '+243 899 067 001', code: 'NADIA01' }, pool);
      assert.strictEqual(result.created, true);
      assert.strictEqual(result.partnerCode, 'NADIA01');
      const insert = seen.find((q) => q.sql.startsWith('INSERT INTO customers'));
      assert.strictEqual(insert.params[0], '243899067001');
      assert.match(insert.sql, /phone_verified_at, activation_token_hash/);
      assert.notStrictEqual(insert.params[1], result.token, 'only the hash is stored');
      assert.strictEqual(insert.params[1], require('crypto').createHash('sha256').update(result.token).digest('hex'));
      assert.ok(seen.some((q) => /INSERT INTO partner_conversions/.test(q.sql) && q.params[0] === 4));
      assert.ok(seen.some((q) => /INSERT INTO account_acquisitions/.test(q.sql) && /'whatsapp'/.test(q.sql)));
      assert.ok(seen.some((q) => q.sql === 'COMMIT'));
    });

    await checkAsync('an agent\'s own code never credits their own number; an existing account is only pointed to its login', async () => {
      const own = fakePool67({ partner: { id: 5, code: 'MARIE01', kind: 'agent', agent_phone: '243899067002' } });
      const result = await customerOnboarding.createCustomerFromWhatsApp({ waId: '243899067002', code: 'MARIE01' }, own.pool);
      assert.strictEqual(result.partnerCode, null);
      assert.ok(!own.seen.some((q) => /INSERT INTO partner_conversions/.test(q.sql)));

      const again = fakePool67({ existing: true });
      const replies = [];
      const handled = await customerOnboarding.handleCustomerSignupMessage(
        { from: '243899067003', text: 'Inscription Lukka Place' },
        { pool: again.pool, send: async (to, text) => { replies.push(text); } },
      );
      assert.strictEqual(handled.handled, true);
      assert.ok(!again.seen.some((q) => q.sql.startsWith('INSERT INTO customers')));
      assert.match(replies[0], /déjà un compte/);
    });

    await checkAsync('the morning run asks web, sends the summary to the owners, and fails when the credits failed', async () => {
      const savedSecret = process.env.CRON_SECRET;
      process.env.CRON_SECRET = 'test-secret';
      try {
        const sent = [];
        const fetchImpl = async (url, options) => {
          assert.match(url, /\/api\/cron\/growth-daily$/);
          assert.strictEqual(options.headers.Authorization, 'Bearer test-secret');
          return { ok: true, json: async () => ({ ok: true, credits: { credited: 2 }, summary: { text: 'Lukka Place — hier' } }) };
        };
        const result = await growthDaily.run({ fetchImpl, send: async (to, text) => { sent.push([to, text]); }, recipients: () => ['243800000001', '243800000002'] });
        assert.strictEqual(result.sent, 2);
        assert.strictEqual(sent[0][1], 'Lukka Place — hier');

        const failing = async () => ({ ok: true, json: async () => ({ ok: false, creditsError: 'boom', summary: { text: 'x' } }) });
        await assert.rejects(() => growthDaily.run({ fetchImpl: failing, send: async () => {}, recipients: () => [] }), /referral credits failed/);
      } finally {
        if (savedSecret === undefined) delete process.env.CRON_SECRET;
        else process.env.CRON_SECRET = savedSecret;
      }
    });
  }

  // ---------------------------------------------------------------------------
  // §68 Referral announcement when a verified agent writes in (2026-11-03)
  // ---------------------------------------------------------------------------
  console.log('\n§68 Referral announcement when a verified agent writes in');
  {
    const referralAnnounce = require('../services/referralAnnounce');
    const savedOnWrite = process.env.REFERRAL_ANNOUNCE_ON_WRITE;
    const savedSecret68 = process.env.CRON_SECRET;
    process.env.REFERRAL_ANNOUNCE_ON_WRITE = '';
    process.env.CRON_SECRET = 'test-secret';
    const agent = async () => ({ registered: true, agentId: 41 });
    try {
      await checkAsync('a verified agent is passed to web with their previous message time, once', async () => {
        referralAnnounce.resetReferralAnnounceCache();
        const calls = [];
        const fetchImpl = async (url, options) => {
          calls.push([url, options]);
          return { ok: true, json: async () => ({ status: 'sent' }) };
        };
        const first = await referralAnnounce.announceIfDue({ from: '243800000041', previousInboundAt: '2026-11-01T08:00:00.000Z', identify: agent, fetchImpl });
        assert.strictEqual(first.status, 'sent');
        assert.match(calls[0][0], /\/api\/internal\/referral-announce$/);
        assert.strictEqual(calls[0][1].headers.Authorization, 'Bearer test-secret');
        assert.deepStrictEqual(JSON.parse(calls[0][1].body), { agentId: 41, previousInboundAt: '2026-11-01T08:00:00.000Z' });
        const again = await referralAnnounce.announceIfDue({ from: '243800000041', identify: agent, fetchImpl, now: Date.now() + 2 * referralAnnounce.RECHECK_MS });
        assert.strictEqual(again.status, 'skipped', 'web said it is done: never asked again in this process');
        assert.strictEqual(calls.length, 1);
      });

      await checkAsync('a sender who is not a verified agent, the desk / relay, or the switch off never reaches web', async () => {
        referralAnnounce.resetReferralAnnounceCache();
        let asked = 0;
        const fetchImpl = async () => { asked += 1; return { ok: true, json: async () => ({ status: 'sent' }) }; };
        const stranger = await referralAnnounce.announceIfDue({ from: '243800000042', identify: async () => ({ registered: false, agentId: null }), fetchImpl });
        assert.strictEqual(stranger.status, 'not-an-agent');
        const desk = await referralAnnounce.announceIfDue({ from: '243800000043', identify: agent, fetchImpl, isExcluded: () => true });
        assert.strictEqual(desk.status, 'excluded');
        process.env.REFERRAL_ANNOUNCE_ON_WRITE = 'off';
        const off = await referralAnnounce.announceIfDue({ from: '243800000044', identify: agent, fetchImpl });
        assert.strictEqual(off.status, 'off');
        process.env.REFERRAL_ANNOUNCE_ON_WRITE = '';
        assert.strictEqual(asked, 0);
      });

      await checkAsync('one check per number per 12 h while web is unreachable; a failure never throws', async () => {
        referralAnnounce.resetReferralAnnounceCache();
        const down = async () => { throw new Error('ECONNREFUSED'); };
        const t0 = Date.now();
        assert.strictEqual((await referralAnnounce.announceIfDue({ from: '243800000045', identify: agent, fetchImpl: down, now: t0 })).status, 'failed');
        assert.strictEqual((await referralAnnounce.announceIfDue({ from: '243800000045', identify: agent, fetchImpl: down, now: t0 + 60_000 })).status, 'skipped');
        assert.strictEqual((await referralAnnounce.announceIfDue({ from: '243800000045', identify: agent, fetchImpl: down, now: t0 + referralAnnounce.RECHECK_MS + 1 })).status, 'failed');
      });

      check('the webhook schedules it from the inbound loop, after reading the previous message time, and goes on', () => {
        const source = fs.readFileSync(path.join(__dirname, '..', 'routes', 'webhook.js'), 'utf8');
        const loop = source.slice(source.indexOf('for (const message of messages)'));
        const prev = loop.indexOf('previousInboundAt = lastInboundAt(message.from)');
        const record = loop.indexOf('recordInbound(message.from)');
        const schedule = loop.indexOf('scheduleReferralAnnouncement(');
        const enqueue = loop.indexOf('enqueueMessage(message)');
        assert.ok(prev > 0 && prev < record, 'the previous time is read before it is overwritten');
        assert.ok(schedule > record && schedule < enqueue, 'scheduled before the message is processed, never instead of it');
        assert.ok(referralAnnounce.ANNOUNCE_DELAY_MS >= 30_000, 'it lands after the reply to what the agent sent');
      });
    } finally {
      referralAnnounce.resetReferralAnnounceCache();
      process.env.REFERRAL_ANNOUNCE_ON_WRITE = savedOnWrite;
      if (savedSecret68 === undefined) delete process.env.CRON_SECRET;
      else process.env.CRON_SECRET = savedSecret68;
    }
  }

  // ---------------------------------------------------------------------------
  // §69 Profile enquiries reach the agent; unverified agents are told (2026-11-03)
  // ---------------------------------------------------------------------------
  console.log('\n§69 Profile enquiries reach the agent; unverified agents are told');
  {
    const profileEnquiry = require('../services/agentProfileEnquiry');
    const repo69 = require('../services/propertyRepository');
    const chakra69 = require('../services/chakra');
    const onboarding69 = require('../services/agentOnboarding');
    const saved69 = { agent: repo69.getAgentContactById, text: chakra69.sendWhatsAppMessage, ops: process.env.OPS_WHATSAPP_NUMBER };
    const sent69 = [];
    chakra69.sendWhatsAppMessage = async (to, body) => { sent69.push({ to, body }); return {}; };
    process.env.OPS_WHATSAPP_NUMBER = '243846962654';
    const verified = {
      agent_id: 60, agent_name: 'Immo Kin', agent_phone: '243906500060', phone_verified_at: '2026-10-01', direct_routing_enabled: true, deleted: false,
    };
    const lead69 = () => dbService.createLead({
      wa_id: '243895000069', name: 'Client Test', source: 'agent-profile-inquiry', assigned_agent: 'Immo Kin',
      requirements_summary: 'Type : Appartement\nBudget : 500 $\nJe cherche à Gombe',
    });
    try {
      await checkAsync('a verified agent is alerted, the lead is assigned to them, and the desk gets a copy', async () => {
        sent69.length = 0;
        repo69.getAgentContactById = async () => verified;
        const lead = lead69();
        const result = await profileEnquiry.notifyAgentProfileEnquiry({ lead, agentId: 60 });
        assert.strictEqual(result.agentNotified, true);
        assert.strictEqual(result.opsNotified, true);
        assert.strictEqual(dbService.getLead(lead.id).agent_id, 60, 'in the agent\'s Demandes inbox');
        const toAgent = sent69.find((m) => m.to === '243906500060');
        assert.ok(toAgent, 'the agent was messaged');
        assert.match(toAgent.body, /\+243895000069/);
        assert.match(toAgent.body, /Je cherche à Gombe/);
        assert.match(toAgent.body, new RegExp(`/compte/agent/demandes\\?lead=${lead.id}`));
        const desk = sent69.find((m) => m.to === '243846962654');
        assert.match(desk.body, /ne nous a pas écrit depuis 24 h/, 'no inbound on record: the desk is told it probably did not land');
      });

      await checkAsync('inside the 24 h window the desk is told the agent was alerted', async () => {
        sent69.length = 0;
        repo69.getAgentContactById = async () => verified;
        require('../services/sessionWindow').recordInbound('243906500060');
        await profileEnquiry.notifyAgentProfileEnquiry({ lead: lead69(), agentId: 60 });
        assert.match(sent69.find((m) => m.to === '243846962654').body, /Agent prévenu sur WhatsApp/);
      });

      await checkAsync('an unverified, routing-off or deleted agent is never messaged; the desk is told to act', async () => {
        for (const contact of [
          { ...verified, phone_verified_at: null },
          { ...verified, direct_routing_enabled: false },
          { ...verified, deleted: true },
          null,
        ]) {
          sent69.length = 0;
          repo69.getAgentContactById = async () => contact;
          const result = await profileEnquiry.notifyAgentProfileEnquiry({ lead: lead69(), agentId: 60 });
          assert.strictEqual(result.agentNotified, false);
          assert.ok(!sent69.some((m) => m.to === '243906500060'));
          assert.match(sent69.find((m) => m.to === '243846962654').body, /Agent NON prévenu/);
        }
      });

      check('POST /leads hands a profile enquiry with an agent_id to the notifier, and web sends the id', () => {
        const admin = fs.readFileSync(path.join(__dirname, '..', 'routes', 'admin.js'), 'utf8');
        const route = admin.slice(admin.indexOf("router.post('/leads'"), admin.indexOf("router.get('/leads/open'"));
        assert.match(route, /agent_id: agentIdRaw/);
        assert.match(route, /notifyAgentProfileEnquiryInBackground\(\{ lead, agentId: profileAgentId \}\)/);
        const web = fs.readFileSync(path.join(__dirname, '..', 'web', 'app', '(portfolio)', 'agents', '[id]', 'actions.js'), 'utf8');
        assert.match(web, /agentId: agent\.id/);
      });

      check('an unverified agent account gets a note pointing at login, never a verification by message', () => {
        const withPassword = onboarding69.unverifiedAccountNote({ id: 103, phone_verified_at: null, password_hash: 'x' });
        assert.match(withPassword, /pas encore vérifié/);
        assert.match(withPassword, /\/compte\/agent\/connexion/);
        assert.match(onboarding69.unverifiedAccountNote({ id: 103, phone_verified_at: null, password_hash: null }), /\+243 846 962 654/);
        assert.strictEqual(onboarding69.unverifiedAccountNote({ id: 1, phone_verified_at: '2026-01-01' }), null);
        assert.strictEqual(onboarding69.unverifiedAccountNote({ id: 1, phone_verified_at: null, deleted_at: '2026-10-18' }), null);
        assert.strictEqual(onboarding69.unverifiedAccountNote(null), null);
        assert.strictEqual(onboarding69.senderIdentityFrom({ id: 103, phone_verified_at: null }).registered, false, 'still nothing attributed');
        const webhook = fs.readFileSync(path.join(__dirname, '..', 'routes', 'webhook.js'), 'utf8');
        assert.match(webhook, /suffixKind = 'unverified'/);
      });
    } finally {
      repo69.getAgentContactById = saved69.agent;
      chakra69.sendWhatsAppMessage = saved69.text;
      if (saved69.ops === undefined) delete process.env.OPS_WHATSAPP_NUMBER;
      else process.env.OPS_WHATSAPP_NUMBER = saved69.ops;
    }
  }

  // ---------------------------------------------------------------------------
  // §70 The quartier keeps a quartier, the reference keeps the landmark (2026-11-03)
  // ---------------------------------------------------------------------------
  console.log('\n§70 The quartier keeps a quartier, the reference keeps the landmark');
  {
    const loc70 = require('../services/locations');
    const tidy = (commune, quartier, reference) => {
      const { quartier: q, reference: r, how } = loc70.tidyListingLocation({ commune, quartier, reference });
      return { quartier: q, reference: r, how };
    };

    check('a landmark typed as the quartier moves to the reference (admin screenshot, Kintambo)', () => {
      assert.deepStrictEqual(tidy('Kintambo', 'Maison communale de Kintambo, sur avenue', 'MAISON COMMUNALE'), {
        quartier: null, reference: 'Maison communale de Kintambo, sur avenue', how: 'moved-to-reference',
      });
      assert.deepStrictEqual(tidy('Kintambo', 'Maison communale', null), {
        quartier: null, reference: 'Maison communale', how: 'moved-to-reference',
      });
    });

    check('a quartier named in the reference fills an empty quartier (admin screenshot, Ngaliema)', () => {
      assert.deepStrictEqual(tidy('Ngaliema', null, 'Mbiza pigeon Référence maternité'), {
        quartier: 'Binza Pigeon', reference: 'Mbiza pigeon Référence maternité', how: 'found-in-reference',
      });
    });

    check('a phrase holding a quartier keeps the quartier and moves the whole phrase', () => {
      assert.deepStrictEqual(tidy('Ngaliema', 'Binza Pigeon, réf. maternité', null), {
        quartier: 'Binza Pigeon', reference: 'Binza Pigeon, réf. maternité', how: 'found-in-quartier',
      });
      // A different landmark already in the reference is kept beside it.
      assert.strictEqual(tidy('Ngaliema', 'derrière église Pigeon', 'Station Total').reference, 'Station Total, derrière église Pigeon');
    });

    check('a listing code in the reference is never overwritten — the phrase stays put', () => {
      assert.deepStrictEqual(tidy('Ngaliema', 'Binza Pigeon, réf. maternité', 'LKP-2026-0091'), {
        quartier: 'Binza Pigeon, réf. maternité', reference: 'LKP-2026-0091', how: null,
      });
    });

    check('only the stated commune is searched — never a citywide match', () => {
      // Righini is Lemba's; read for Gombe it names nothing.
      assert.strictEqual(tidy('Gombe', null, 'vers Righini').quartier, null);
      assert.strictEqual(tidy('Lemba', null, 'vers Righini').quartier, 'Righini');
      // Ordinary words and names after "avenue" are not quartiers inside a text.
      assert.strictEqual(tidy('Kintambo', null, 'École petits lutins').quartier, null);
      assert.strictEqual(tidy('Ngaliema', null, 'avenue Kalamu').quartier, null);
      // Two different quartiers named: no pick.
      assert.strictEqual(loc70.quartierNamedIn('entre Macampagne et Binza Pigeon', 'Ngaliema'), null);
    });

    check('a short name is canonicalised or kept as written, never moved', () => {
      assert.strictEqual(tidy('Ngaliema', 'Pigeon', null).quartier, 'Binza Pigeon');
      assert.strictEqual(tidy('Ngaliema', 'ma campagne', null).quartier, 'Macampagne');
      assert.strictEqual(tidy('Ngaliema', 'Mont Fleury', null).quartier, 'Mont-Fleury');
      assert.deepStrictEqual(tidy('Ngaliema', 'GB', null), { quartier: 'GB', reference: null, how: null });
      // Not in Kintambo's official list and not a sourced alias: kept, not invented.
      assert.deepStrictEqual(tidy('Kintambo', 'Jamaïque', null), { quartier: 'Jamaïque', reference: null, how: null });
      // No commune: nothing to search within.
      assert.deepStrictEqual(tidy(null, 'Maison communale', null), { quartier: 'Maison communale', reference: null, how: null });
    });

    check('inferListingLocation applies it after a commune is stated or deduced', () => {
      const stated = loc70.inferListingLocation({ commune: 'Ngaliema', quartier: null, reference: 'Mbiza pigeon Référence maternité' });
      assert.strictEqual(stated.quartier, 'Binza Pigeon');
      assert.strictEqual(stated.locationTidied, 'found-in-reference');
      const deduced = loc70.inferListingLocation({ quartier: 'Maison communale de Kintambo, sur avenue' });
      assert.strictEqual(deduced.commune, 'Kintambo');
      assert.strictEqual(deduced.quartier, null);
      assert.strictEqual(deduced.reference, 'Maison communale de Kintambo, sur avenue');
    });

    check('a correction clears the quartier only when the tidy says so', () => {
      const draft = dbService.insertListing(
        {
          intent: 'listing', transaction_type: 'location', property_type: 'appartement',
          commune: 'Kintambo', quartier: 'Maison communale de Kintambo', price: 700, currency: 'USD',
          missing_fields: [], confidence: 0.8,
        },
        '243810000770',
        { wamid: 'wamid.TIDY70' },
      );
      dbService.applyListingCorrection(draft.id, { quartier: null, price: 650 }, '650$');
      assert.strictEqual(dbService.getListing(draft.id).quartier, 'Maison communale de Kintambo');
      dbService.applyListingCorrection(
        draft.id,
        { quartier: null, reference: 'Maison communale de Kintambo', quartier_cleared: true },
        'ok',
      );
      const row = dbService.getListing(draft.id);
      assert.strictEqual(row.quartier, null);
      assert.strictEqual(row.reference, 'Maison communale de Kintambo');
    });

    check('the publish sync tidies the same way', () => {
      const row = postgresService.normaliseRowLocation({ commune: 'ngaliema', quartier: null, reference: 'Mbiza pigeon réf maternité' });
      assert.strictEqual(row.commune, 'Ngaliema');
      assert.strictEqual(row.quartier, 'Binza Pigeon');
    });

    check('the backfill plans the same change, and nothing for a clean row', () => {
      const { planRow } = require('./backfill-quartier-landmarks');
      assert.deepStrictEqual(planRow({ commune: 'Kintambo', quartier: 'Maison communale de Kintambo, sur avenue', reference: 'MAISON COMMUNALE' }), {
        how: 'moved-to-reference', quartier: null, reference: 'Maison communale de Kintambo, sur avenue',
      });
      assert.strictEqual(planRow({ commune: 'Ngaliema', quartier: 'Binza Pigeon', reference: 'Maternité' }), null);
      // A close spelling is never written back over stored text.
      assert.strictEqual(planRow({ commune: 'Mont-Ngafula', quartier: 'Mbudi', reference: null }), null);
    });

    check('a short official name counts inside a phrase; one place spelled twice is not stacked', () => {
      assert.strictEqual(tidy('Ngaliema', 'Derrière l’Hôpital de la Borne, UPN', 'Hôpital Laborne').quartier, 'UPN');
      assert.strictEqual(tidy('Limete', '14e Rue Industrielle', '14eme Rue industriel').reference, '14eme Rue industriel');
    });

    check('the prompt no longer sends landmarks to the quartier field', () => {
      assert.ok(!openaiService.SYSTEM_PROMPT.includes('La référence précise va dans "quartier"'));
      assert.match(openaiService.SYSTEM_PROMPT, /"quartier" reçoit un NOM DE LIEU seulement/);
    });

    check('the web admin editor picks the quartier from the commune\'s list', () => {
      const editor = fs.readFileSync(path.join(__dirname, '..', 'web', 'app', 'admin', 'listings', '[id]', 'AdminListingEditor.js'), 'utf8');
      assert.match(editor, /<QuartierPicker commune=\{commune\} locations=\{locations\}/);
      assert.doesNotMatch(editor, /<input name="quartier"/);
    });
  }

  // ---------------------------------------------------------------------------
  // §71 Customer → agent interactions: desk introductions and the counts (2026-11-04)
  // ---------------------------------------------------------------------------
  console.log('\n§71 Customer → agent interactions: desk introductions and the counts');
  {
    const intro71 = require('../services/teamIntroduction');
    const since71 = new Date(Date.now() - 60 * 60 * 1000).toISOString();
    const before71 = dbService.getInteractionCounts({ since: since71 });
    const total71 = (c) => [...c.leads, ...c.viewings].reduce((sum, r) => sum + r.count, 0);

    check('a desk introduction is a lead in the agent\'s inbox, never dispatched, with how and who', () => {
      const result = intro71.recordIntroduction({
        wa_id: '+243 895 000 071', name: 'Client 71', agent_id: '71', assigned_agent: 'Commissionnaire 71',
        property_id: '310', channel: 'phone', note: 'Appelé par le bureau', recorded_by: 'Desk', agent_contacted: true,
      });
      assert.strictEqual(result.ok, true);
      const lead = dbService.getLead(result.lead.id);
      assert.strictEqual(lead.source, 'team-introduction');
      assert.strictEqual(lead.wa_id, '243895000071');
      assert.strictEqual(lead.agent_id, 71);
      assert.strictEqual(lead.assigned_agent, 'Commissionnaire 71');
      assert.strictEqual(lead.property_id, 310);
      assert.strictEqual(lead.contact_channel, 'phone');
      assert.strictEqual(lead.recorded_by, 'Desk');
      assert.strictEqual(lead.status, 'CONTACTED', 'the team knows the agent already reached the customer');
      assert.strictEqual(lead.commune, null, 'no commune: leadDispatch never pushes it to other agencies');
    });

    check('without "already contacted" it waits at NEW for the agent to mark it', () => {
      const result = intro71.recordIntroduction({ wa_id: '243895000072', agent_id: 71, channel: 'whatsapp' });
      assert.strictEqual(result.ok, true);
      assert.strictEqual(result.lead.status, 'NEW');
      assert.strictEqual(result.lead.property_id, null);
    });

    check('a bad phone, no agent, a bad listing id or an unknown channel is refused', () => {
      assert.strictEqual(intro71.recordIntroduction({ wa_id: '12', agent_id: 71, channel: 'phone' }).error, 'invalid-phone');
      assert.strictEqual(intro71.recordIntroduction({ wa_id: '243895000073', channel: 'phone' }).error, 'agent-required');
      assert.strictEqual(intro71.recordIntroduction({ wa_id: '243895000073', agent_id: 71, property_id: 'abc', channel: 'phone' }).error, 'invalid-property');
      assert.strictEqual(intro71.recordIntroduction({ wa_id: '243895000073', agent_id: 71, channel: 'sms' }).error, 'invalid-channel');
    });

    check('the counts hold introductions, enquiries and visit requests, but not multi-agency searches', () => {
      dbService.createLead({ wa_id: '243895000074', source: 'listing-whatsapp-enquiry', property_id: 293 });
      dbService.createLead({ wa_id: '243895000075', source: 'site', commune: 'Gombe' });
      const visitLead = dbService.createLead({ wa_id: '243895000076', source: 'listing-visit-request', property_id: 294 });
      const vr = dbService.createViewingRequest({ leadId: visitLead.id, propertyId: 294, requestedTime: 'demain' });
      dbService.setViewingRouting(vr.id, { agentId: 72, routingType: 'DIRECT_WA' });

      const after = dbService.getInteractionCounts({ since: since71 });
      assert.strictEqual(total71(after) - total71(before71), 4, '2 introductions + 1 enquiry + 1 visit; the "site" search is not one');
      const intro = after.leads.filter((r) => r.source === 'team-introduction' && r.agentId === 71);
      assert.strictEqual(intro.reduce((s, r) => s + r.count, 0), 2);
      assert.strictEqual(intro.reduce((s, r) => s + r.contacted, 0), 1);
      assert.ok(after.leads.some((r) => r.source === 'listing-whatsapp-enquiry' && r.propertyId === 293 && r.agentId === null),
        'a listing-only row keeps its listing so web can find the agent');
      assert.ok(after.viewings.some((r) => r.agentId === 72 && r.propertyId === 294));
      assert.ok(!after.leads.some((r) => r.source === 'listing-visit-request'), 'a visit is counted once, through viewing_requests');
    });

    check('the routes are mounted', () => {
      const src = fs.readFileSync(path.join(__dirname, '..', 'routes', 'admin.js'), 'utf8');
      assert.match(src, /router\.get\('\/interaction-counts'/);
      assert.match(src, /router\.post\('\/team-introductions'/);
    });
  }

  // ---------------------------------------------------------------------------
  // §72 Market observations: asking prices from outside our own listings (2026-11-04)
  // ---------------------------------------------------------------------------
  console.log('\n§72 Market observations: group captures and listing sites');
  {
    const market72 = require('../services/marketObservations');
    const http72 = require('../services/marketSources/http');
    const text72 = require('../services/marketSources/text');
    const imcongo72 = require('../services/marketSources/imcongo');
    const alain72 = require('../services/marketSources/alainRealty');
    const smart72 = require('../services/marketSources/smartimmo');
    const immo72 = require('../services/marketSources/immo24');
    const group72 = require('../services/marketSources/whatsappGroup');

    check('robots.txt: the * group is read, Crawl-delay is honoured, the longest rule wins and Allow wins a tie', () => {
      const rules = http72.parseRobots('User-agent: Bytespider\nDisallow: /\n\nUser-agent: *\nCrawl-delay: 10\nDisallow: /wp-admin/\nAllow: /wp-admin/admin-ajax.php\nDisallow: /*?add-to-cart=\n');
      assert.strictEqual(rules.crawlDelayMs, 10000);
      assert.strictEqual(http72.robotsAllows(rules, '/bien/x/'), true, 'Bytespider\'s Disallow: / is not ours');
      assert.strictEqual(http72.robotsAllows(rules, '/wp-admin/edit.php'), false);
      assert.strictEqual(http72.robotsAllows(rules, '/wp-admin/admin-ajax.php'), true);
      assert.strictEqual(http72.robotsAllows(rules, '/shop/?add-to-cart=3'), false);
    });

    await checkAsync('the fetcher never requests a disallowed path and spaces requests by the site\'s Crawl-delay', async () => {
      const requested = [];
      const waits = [];
      const fetcher = http72.createFetcher({
        minIntervalMs: 3000,
        sleepImpl: async (ms) => { waits.push(ms); },
        fetchImpl: async (url, init) => {
          requested.push(url);
          assert.match(init.headers['User-Agent'], /LukkaPlaceMarketBot/);
          const body = url.endsWith('/robots.txt') ? 'User-agent: *\nCrawl-delay: 10\nDisallow: /private/' : '<html>ok</html>';
          return new Response(body, { status: 200 });
        },
      });
      await fetcher.text('https://example.test/list');
      await assert.rejects(() => fetcher.text('https://example.test/private/x'), (err) => err.code === 'ROBOTS_DISALLOWED');
      await fetcher.text('https://example.test/list2');
      assert.deepStrictEqual(requested, ['https://example.test/robots.txt', 'https://example.test/list', 'https://example.test/list2']);
      assert.ok(waits.length >= 1 && waits.every((ms) => ms > 3000 && ms <= 10000), `waits follow the 10 s Crawl-delay: ${waits}`);
    });

    check('amounts, periods, furnished and purpose are read the way Kinshasa adverts write them', () => {
      assert.strictEqual(text72.parseAmount('2 000'), 2000);
      assert.strictEqual(text72.parseAmount('$4,000'), 4000);
      assert.strictEqual(text72.parseAmount('3.500'), 3500);
      assert.strictEqual(text72.parseAmount('210000.00'), 210000);
      assert.strictEqual(text72.periodFromText('/ mois'), 'mois');
      assert.strictEqual(text72.periodFromText('200 $ / jour'), 'jour');
      assert.strictEqual(text72.periodFromText('12 000 $ par an'), 'an');
      assert.strictEqual(text72.isFurnished('Appartement 2 chambres non meublée'), false);
      assert.strictEqual(text72.isFurnished('Bel appartement meublé'), true);
      assert.strictEqual(text72.isFurnished('Appartement'), null);
      assert.strictEqual(text72.purposeFromText('biens immobiliers à louer'), 'rent');
      assert.strictEqual(text72.purposeFromText('À louer et à vendre'), null, 'both → not guessed');
    });

    check('kinds: non-residential words win, so "appartement ou bureau" is never a home', () => {
      assert.strictEqual(market72.kindFromText('Appartement ou bureau 3 chambres'), 'bureau');
      assert.strictEqual(market72.kindFromText('Maison Unifamiliale'), 'maison');
      assert.strictEqual(market72.kindFromText('Appartment'), 'appartement');
      assert.strictEqual(market72.kindFromText('House Maison à louer à Limete'), 'maison');
      assert.strictEqual(market72.kindFromText('Villa à louer'), 'villa');
      assert.strictEqual(market72.kindFromText('Concession Portuaire'), 'terrain');
      assert.strictEqual(market72.kindFromText('dépôt de garantie 3 mois'), null, '"dépôt" is a deposit here, not a warehouse');
    });

    check('places resolve through services/locations.js, unique answers only', () => {
      assert.strictEqual(market72.resolvePlace('Kinshasa - Limete'), 'Limete');
      assert.strictEqual(market72.resolvePlace('Gombe, Kinshasa, Democratic Republic of the Congo'), 'Gombe');
      assert.strictEqual(market72.resolvePlace('GB'), 'Ngaliema', 'the owner-confirmed alias');
      assert.strictEqual(market72.resolvePlace('Quelque part près du fleuve'), null, 'never guessed');
      assert.strictEqual(market72.resolvePlace('Funa'), null, 'a name in two communes is not picked');
    });

    check('cleaning: francs, short stays and impossible rents are kept but excluded; yearly rents are monthly', () => {
      const base = { source: 'imcongo', source_ref: 'x', purpose: 'rent', property_kind: 'appartement', beds: 2, commune: 'Limete' };
      assert.strictEqual(market72.normaliseObservation({ ...base, price: 1200, price_period: 'an' }).monthly_usd, 100);
      assert.strictEqual(market72.normaliseObservation({ ...base, price: 200, price_period: 'jour' }).excluded_reason, 'short_stay');
      assert.strictEqual(market72.normaliseObservation({ ...base, price: 900000, currency: 'FC' }).excluded_reason, 'currency_cdf');
      assert.strictEqual(market72.normaliseObservation({ ...base, price: 210000 }).excluded_reason, 'price_out_of_range');
      assert.strictEqual(market72.normaliseObservation({ ...base, price: 10 }).excluded_reason, 'price_out_of_range');
      const ok = market72.normaliseObservation({ ...base, price: 650, beds: null });
      assert.strictEqual(ok.excluded_reason, null);
      assert.strictEqual(ok.monthly_usd, 650);
      assert.strictEqual(ok.beds, null, 'an unknown bedroom count stays unknown, never 0');
      assert.strictEqual(market72.normaliseObservation({ ...base, property_kind: 'maison', price: 630, beds: 0 }).beds, null, '"0 chambres" on a house is a blank field');
      assert.strictEqual(market72.normaliseObservation({ ...base, property_kind: 'studio', price: 300, beds: 0 }).beds, 0);
      assert.strictEqual(ok.commune, 'Limete');
      assert.strictEqual(ok.city, 'Kinshasa');
      assert.throws(() => market72.normaliseObservation({ ...base, source: 'zillow' }), /unknown market source/);
    });

    check('a refresh keeps an exclusion a team member made by hand', () => {
      assert.match(market72.UPSERT_SQL, /ON CONFLICT \(source, source_ref\) DO UPDATE/);
      assert.match(market72.UPSERT_SQL, /excluded_reason LIKE 'manual:%'/);
      assert.match(market72.UPSERT_SQL, /posted_at = COALESCE\(market_observations\.posted_at/);
    });

    check('IMCongo: one result page gives price, period, bedrooms, commune and reference per advert', () => {
      const html = `<div><span>A louer</span><span>200 $ / jour</span><span>3 chambre(s)</span>
        <a href="immo-congo-900_appartement_meuble_a_louer_kinshasa_ngaliema-immo-fr.html">Appartement Meublé - Quartier Basoko</a>
        <span>N° de référence: 900</span><span>3 chambre(s)</span><span>Kinshasa - Ngaliema</span><span>Voir</span></div>
        <div><span>A louer</span><span>2 000 $ / mois</span><span>3 chambre(s)</span>
        <a href="immo-congo-901_appartement_a_louer_kinshasa_limete-immo-fr.html">Appartement - Quartier Résidentiel</a>
        <span>N° de référence: 901</span><span>3 chambre(s)</span><span>Kinshasa - Limete</span><span>Voir</span></div>`;
      const rows = imcongo72.parseListPage(html, { kind: 'appartement', purpose: 'rent' });
      assert.strictEqual(rows.length, 2);
      assert.deepStrictEqual(
        rows.map((r) => [r.source_ref, r.price, r.price_period, r.beds, r.commune, r.furnished]),
        [['900', 200, 'jour', 3, 'Ngaliema', true], ['901', 2000, 'mois', 3, 'Limete', null]],
      );
      assert.match(rows[1].source_url, /^https:\/\/www\.imcongo\.com\/immo-congo-901_/);
      assert.match(imcongo72.listUrl(4, 'rent'), /congo-a-louer-recherche-4___0_100_KINSHASA/);
    });

    const mediacongo72 = require('../services/marketSources/mediacongo');
    const mcItem = (ref, title, where, date, price) => `<!-- START ANNONCE ITEM -->
      <a class="annonce_item " href="annonce-mediacongo-${ref}_immobilier_vente_location_x.html">
      <div class="annonce_for_text"><h2>${title}</h2>
      <span class="annonceref">Référence : <strong>AN1&nbsp;${ref}</strong></span>
      <span class="where"> ${where} </span> <span class="views"> 26 vues </span><br>
      <span class="publie">Publié le ${date}</span></div>
      <div class="annonce_price">${price}</div></a>`;

    check('MediaCongo: a list item gives reference, commune, post date and price', () => {
      const html = [
        mcItem('397754', 'NGALIEMA/BINZA PIGEON : 3 APPARTEMENTS DISPONIBLES', 'KINSHASA  - Ngaliema', '02.11.2026', '1 300&nbsp;$'),
        mcItem('397753', 'VILLA À VENDRE À GOMBE', 'KINSHASA  - Gombe', '02.11.2026', '2 500 000&nbsp;$'),
        mcItem('397700', 'MAISON A LOUER', 'BOMA  - Kalamu', '01.11.2026', '400&nbsp;$'),
      ].join('\n');
      const items = mediacongo72.parseListPage(html);
      assert.deepStrictEqual(
        items.map((i) => [i.ref, i.city, i.commune, i.postedAt.slice(0, 10), i.price, i.currency]),
        [['397754', 'kinshasa', 'Ngaliema', '2026-11-02', 1300, 'USD'], ['397753', 'kinshasa', 'Gombe', '2026-11-02', 2500000, 'USD'], ['397700', 'boma', 'Kalamu', '2026-11-01', 400, 'USD']],
      );
      assert.match(items[0].url, /^https:\/\/www\.mediacongo\.net\/annonce-mediacongo-397754_/);
      // A sale is stored from the list; outside Kinshasa the commune is never read as Kinshasa's.
      const sale = market72.normaliseObservation({ ...mediacongo72.toObservation(items[1]), source: 'mediacongo' });
      assert.deepStrictEqual([sale.purpose, sale.price_period, sale.commune, sale.excluded_reason], ['sale', 'total', 'Gombe', null]);
      const boma = mediacongo72.toObservation(items[2]);
      assert.strictEqual(boma.commune, null);
      assert.strictEqual(boma.place_text, null);
    });

    check('MediaCongo: the advert\'s Type field decides the kind, not a "parcelle" in its title (397762)', () => {
      const [item] = mediacongo72.parseListPage(mcItem('397762', 'NGALIEMA/PIGEON : Des Appartements de 3 chambres dans une parcelle avec lot de concession', 'KINSHASA - Ngaliema', '02.11.2026', '1 000&nbsp;$'));
      const page = '<div class="annonce_data"><div class="annonce_data_type">Offre :</div><div class="annonce_data_value">Location</div></div>'
        + '<div class="annonce_data"><div class="annonce_data_type">Type :</div><div class="annonce_data_value">Appartement</div></div>'
        + '<div class="annonce_data"><div class="annonce_data_type">Chambre(s) :</div><div class="annonce_data_value">3</div></div>';
      const row = market72.normaliseObservation({ ...mediacongo72.toObservation(item, page), source: 'mediacongo' });
      assert.deepStrictEqual([row.purpose, row.property_kind, row.beds, row.monthly_usd], ['rent', 'appartement', 3, 1000]);
    });

    check('MediaCongo: the advert page\'s live fields win, never the commented-out block', () => {
      const [item] = mediacongo72.parseListPage(mcItem('397754', 'NGALIEMA/BINZA PIGEON : 3 APPARTEMENTS DISPONIBLES', 'KINSHASA  - Ngaliema', '02.11.2026', '1 300&nbsp;$'));
      const page = `<!-- START ÀNNONCE DATA
        <div class="for_annonce_data">
        <div class="annonce_data"><div class="annonce_data_type">Type d’offre :</div><div class="annonce_data_value"> Vente</div></div>
        <div class="annonce_data"><div class="annonce_data_type">Nombre de chambres :</div><div class="annonce_data_value">4</div></div>
        </div>
        <!-- END ÀNNONCE DATA -->
        <div class="for_annonce_data">
        <div class="annonce_data"><div class="annonce_data_type">Offre :</div><div class="annonce_data_value"> Location </div></div>
        <div class="annonce_data"><div class="annonce_data_type">Type :</div><div class="annonce_data_value"> Appartement </div></div>
        <div class="annonce_data"><div class="annonce_data_type">Chambre(s) :</div><div class="annonce_data_value"> 3 </div></div>
        </div>
        <script type="application/ld+json">{"@type":"Product","description":"Loyer: 1300$ garantie 4+1","offers":{"@type":"Offer","priceCurrency":"USD","price":"1300.00"}}</script>`;
      const raw = mediacongo72.toObservation(item, page);
      assert.deepStrictEqual([raw.purpose, raw.beds, raw.price, raw.price_period], ['rent', 3, 1300, 'mois']);
      const row = market72.normaliseObservation({ ...raw, source: 'mediacongo' });
      assert.deepStrictEqual([row.property_kind, row.beds, row.monthly_usd, row.commune, row.excluded_reason], ['appartement', 3, 1300, 'Ngaliema', null]);
      assert.strictEqual(mediacongo72.postedAt('Publié le 31.12.2025'), '2025-12-31T12:00:00.000Z');
      assert.match(mediacongo72.listUrl(2), /categories-cat-114_immobilier_vente_location-page-2\.html$/);
    });

    await checkAsync('MediaCongo: walks back to 2026, reads advert pages for rentals only, marks known adverts seen', async () => {
      const pages = {
        1: [mcItem('3', 'APPARTEMENT A LOUER', 'KINSHASA - Limete', '04.11.2026', '500&nbsp;$'),
          mcItem('2', 'PARCELLE À VENDRE', 'KINSHASA - Lemba', '03.11.2026', '90 000&nbsp;$'),
          mcItem('1', 'STUDIO A LOUER', 'KINSHASA - Gombe', '02.11.2026', '700&nbsp;$')].join(''),
        2: [mcItem('0', 'MAISON A LOUER', 'KINSHASA - Kalamu', '01.01.2026', '450&nbsp;$'),
          mcItem('-', 'X', 'KINSHASA - Kalamu', '31.12.2025', '1&nbsp;$')].join(''),
        3: mcItem('9', 'VIEILLE ANNONCE A LOUER', 'KINSHASA - Kalamu', '30.12.2025', '300&nbsp;$'),
        4: mcItem('8', 'NEVER READ', 'KINSHASA - Kalamu', '01.06.2025', '300&nbsp;$'),
      };
      const fetched = [];
      const fetcher = {
        requests: 0,
        async text(url) {
          fetched.push(url);
          const page = /page-(\d+)\.html$/.exec(url)?.[1] || (/categories-cat-114/.test(url) ? '1' : null);
          if (page) return pages[page] || '';
          return '<div class="annonce_data"><div class="annonce_data_type">Offre :</div><div class="annonce_data_value">Location</div></div><div class="annonce_data"><div class="annonce_data_type">Chambre(s) :</div><div class="annonce_data_value">2</div></div>';
        },
      };
      const result = await mediacongo72.collect({ since: '2026-01-01T00:00:00Z', knownRefs: new Set(['1']), fetcher });
      assert.ok(!fetched.some((u) => /page-4/.test(u)), 'stops one page past the last 2026 advert');
      assert.ok(fetched.some((u) => /page-3/.test(u)));
      assert.deepStrictEqual(result.stillListed, ['1']);
      assert.deepStrictEqual(result.observations.map((o) => o.source_ref).sort(), ['0', '2', '3']);
      assert.ok(!fetched.some((u) => /annonce-mediacongo-2_/.test(u)), 'a sale is stored from the list');
      assert.strictEqual(result.observations.find((o) => o.source_ref === '3').beds, 2);
    });

    check('Alain Realty: status, price, bedrooms and place come from the advert page', () => {
      const html = `<body class="single-property postid-17973"><h1 class="rh_page__title">APPARTEMENT 2 CHAMBRES NON MEUBLÉE À LOUER</h1>
        <p class="rh_page__property_address"> Gombe, Kinshasa, Democratic Republic of the Congo </p>
        <div class="rh_page__property_price"><p class="status"> biens immobiliers à louer </p><p class="price "> $4,000 / mois </p></div>
        <div class="rh_property__meta prop_bedrooms"><span class="rh_meta_titles">Chambres</span><div><svg><path d="M1 2"/></svg><span class="figure"> 2 </span></div></div></body>`;
      const raw = alain72.parsePropertyPage(html, { url: 'https://alain-realty.net/bien/x/', lastmod: '2026-09-19T19:05:41+00:00' });
      const row = market72.normaliseObservation({ ...raw, source: 'alain_realty' });
      assert.deepStrictEqual([row.source_ref, row.purpose, row.property_kind, row.beds, row.monthly_usd, row.commune, row.furnished], ['17973', 'rent', 'appartement', 2, 4000, 'Gombe', false]);
      const map = alain72.parseSitemap('<url><loc>https://alain-realty.net/bien/a/</loc><lastmod>2026-10-01</lastmod></url><url><loc>https://alain-realty.net/bien/</loc></url>');
      assert.deepStrictEqual(map.map((e) => e.url), ['https://alain-realty.net/bien/a/'], 'the archive page is not an advert');
    });

    check('SmartImmo: the UUIDv7 dates an advert; schema.org data gives the rest', () => {
      assert.strictEqual(smart72.uuidV7Time('01a1a71c-10e1-7a40-8764-d95ed494eb7e').slice(0, 4), '2026');
      assert.strictEqual(smart72.uuidV7Time('3f2504e0-4f89-41d3-9a0c-0305e82c3301'), null, 'a v4 uuid has no date');
      const entries = smart72.parseSitemap(`<loc>https://www.smartimmo-app.com/fr/annonce/maison-limete-kinshasa-5-chambres-01a1a71c-10e1-7a40-8764-d95ed494eb7e</loc>
        <loc>https://www.smartimmo-app.com/en/annonce/maison-limete-kinshasa-5-chambres-01a1a71c-10e1-7a40-8764-d95ed494eb7e</loc>`);
      assert.strictEqual(entries.length, 1, 'the English twin is the same advert');
      assert.strictEqual(entries[0].slugKind, 'maison');
      const ld = { '@context': 'https://schema.org', '@graph': [{ '@type': 'Apartment', name: 'Appartement à louer à Lemba, Kinshasa', description: 'Appartement • 2 chambre(s) • Prix : 450.00 USD / mois.', address: { addressLocality: 'Kinshasa', addressRegion: 'Lemba' }, numberOfBedrooms: 2, offers: { price: '450.00', priceCurrency: 'USD' } }] };
      const raw = smart72.parseListingPage(`<script type="application/ld+json">${JSON.stringify(ld)}</script>`, entries[0]);
      const row = market72.normaliseObservation({ ...raw, source: 'smartimmo' });
      assert.deepStrictEqual([row.purpose, row.property_kind, row.beds, row.monthly_usd, row.commune], ['rent', 'appartement', 2, 450, 'Lemba']);
      assert.strictEqual(smart72.parseListingPage('<html></html>', entries[0]), null);
    });

    check('Immo24: the REST item maps through its taxonomies; "visites tous les jours" is not a day rate', () => {
      const tax = { property_status: { 28: 'A Louer' }, property_type: { 16: 'Appartment' }, property_city: { 36: 'Kinshasa' }, property_area: { 106: 'Gombe' } };
      const raw = immo72.toObservation({
        id: 17870, date_gmt: '2026-11-02T09:15:11', link: 'https://immo24.cd/property/x/',
        title: { rendered: 'À louer à Kinshasa-Gombé Appartement 3 Chb' },
        content: { rendered: '<p>Appartement Meublé, visites tous les jours.</p><p>Prix : 3500$ le mois</p>' },
        property_status: [28], property_type: [16], property_city: [36], property_area: [106],
        property_meta: { fave_property_price: ['3500'], fave_property_bedrooms: ['3'] },
      }, tax);
      const row = market72.normaliseObservation({ ...raw, source: 'immo24' });
      assert.deepStrictEqual([row.source_ref, row.purpose, row.property_kind, row.beds, row.monthly_usd, row.commune, row.furnished, row.excluded_reason],
        ['17870', 'rent', 'appartement', 3, 3500, 'Gombe', true, null]);
      assert.strictEqual(row.posted_at, '2026-11-02T09:15:11.000Z');
    });

    await checkAsync('group captures: every capture with a price, never one from an excluded group', async () => {
      const insert = dbService.db.prepare(`INSERT INTO listings (wa_id, transaction_type, property_type, commune, quartier, price, currency, price_period, bedrooms, furnished, remote_property_id, parsed_json, created_at)
        VALUES (@wa, @t, @type, @commune, @q, @price, 'USD', @period, @beds, @furn, @remote, @json, '2026-11-01 10:00:00')`);
      const ok = insert.run({ wa: '243999384203', t: 'location', type: 'appartement', commune: 'Limete', q: 'Industriel', price: 450, period: 'mois', beds: 2, furn: 0, remote: 662, json: JSON.stringify({ source: 'whatsapp-group', group_jid: '120363344702370143@g.us' }) }).lastInsertRowid;
      const vitesse = insert.run({ wa: '243834915639', t: 'location', type: 'appartement', commune: 'Gombe', q: null, price: 900, period: 'mois', beds: 2, furn: null, remote: null, json: JSON.stringify({ source: 'whatsapp-group', group_jid: '120363424833758385@g.us' }) }).lastInsertRowid;
      const banned = insert.run({ wa: '243834915640', t: 'location', type: 'appartement', commune: 'Gombe', q: null, price: 950, period: 'mois', beds: 2, furn: null, remote: null, json: JSON.stringify({ source: 'whatsapp-group', group_jid: '120363000000000099@g.us' }) }).lastInsertRowid;
      const own = insert.run({ wa: '243810000000', t: 'location', type: 'appartement', commune: 'Gombe', q: null, price: 900, period: 'mois', beds: 2, furn: null, remote: null, json: JSON.stringify({ source: 'whatsapp' }) }).lastInsertRowid;
      const savedExcluded = process.env.MARKET_EXCLUDED_GROUP_JIDS;
      process.env.MARKET_EXCLUDED_GROUP_JIDS = '120363000000000099@g.us';
      let observations;
      try { ({ observations } = await group72.collect({ since: '2026-01-01T00:00:00Z' })); } finally {
        if (savedExcluded === undefined) delete process.env.MARKET_EXCLUDED_GROUP_JIDS; else process.env.MARKET_EXCLUDED_GROUP_JIDS = savedExcluded;
      }
      const refs = observations.map((o) => o.source_ref);
      assert.ok(refs.includes(`listing:${ok}`));
      assert.ok(!refs.includes(`listing:${banned}`), 'a group in MARKET_EXCLUDED_GROUP_JIDS is never read');
      assert.ok(refs.includes(`listing:${vitesse}`), 'Vitesse maximale 5/5 counts since its authorisation (2026-11-04)');
      assert.deepStrictEqual(market72.EXCLUDED_GROUP_JIDS, []);
      assert.ok(!refs.includes(`listing:${own}`), 'an agent\'s own WhatsApp listing is not a group capture');
      const row = market72.normaliseObservation({ ...observations.find((o) => o.source_ref === `listing:${ok}`), source: 'whatsapp_group' });
      assert.deepStrictEqual([row.property_id, row.purpose, row.property_kind, row.beds, row.monthly_usd, row.commune, row.furnished], [662, 'rent', 'appartement', 2, 450, 'Limete', false]);
      assert.strictEqual(group72.kindOf({ property_type: 'parcelle', parcelle_subtype: 'Maison Type Locataire', bedrooms: 2 }), 'maison');
      assert.strictEqual(group72.kindOf({ property_type: 'parcelle', parcelle_subtype: 'Terrain Nu' }), 'terrain');
    });

    check('the nightly job is registered, starts in the background and can be switched off', () => {
      assert.ok(sched.JOBS.some((j) => j.name === market72.JOB_NAME));
      const before = process.env.MARKET_COLLECTION;
      process.env.MARKET_COLLECTION = 'off';
      try { assert.strictEqual(market72.collectionDue(new Date('2026-11-05T01:30:00Z')), false); } finally {
        if (before === undefined) delete process.env.MARKET_COLLECTION; else process.env.MARKET_COLLECTION = before;
      }
      const src = fs.readFileSync(path.join(__dirname, '..', 'services', 'marketObservations.js'), 'utf8');
      assert.match(src, /run: async \(\) => startCollectionInBackground\(\)/, 'a collection never holds the scheduler tick');
      assert.deepStrictEqual(market72.COLLECTED_SOURCES, ['whatsapp_group', 'immo24', 'imcongo', 'alain_realty', 'smartimmo', 'mediacongo']);
      assert.ok(!market72.COLLECTED_SOURCES.includes('zwandako') && !market72.COLLECTED_SOURCES.includes('facebook'),
        'their terms forbid automated collection: entered by hand only');
    });

    check('a hand-copied batch (Zwandako, 2026-11-05) loads as rents with commune, quartier and an age', () => {
      const { rowsFromFile } = require('./import-market-observations');
      const rows = rowsFromFile(path.join(__dirname, 'data', 'zwandako-2026-11-05.json'));
      assert.strictEqual(rows.length, 99);
      assert.ok(rows.every((r) => r.source === 'zwandako' && r.purpose === 'rent' && r.price_period === 'mois'));
      const upn = rows.find((r) => r.source_ref === 'location-dun-appartement-a-ngaliema-upn');
      assert.deepStrictEqual([upn.commune, upn.quartier, upn.beds, upn.monthly_usd, upn.posted_at], ['Ngaliema', 'Binza UPN', 2, 500, '2026-11-05T12:00:00.000Z']);
      const old = rows.find((r) => r.source_ref === 'maison-a-louer-ngaliema-kinshasa-7');
      assert.strictEqual(old.posted_at, '2026-07-08T12:00:00.000Z', '"4 months ago" = 120 days before the entry date');
      // A listing naming two communes ("Masina, ngaliema") is stored without one, never guessed.
      assert.strictEqual(rows.find((r) => r.source_ref === 'appartement-a-louer-masiala-kinshasa').commune, null);
      assert.ok(!rows.some((r) => r.excluded_reason), 'every price is a plausible monthly rent');
      assert.throws(() => rowsFromFile(path.join(__dirname, '..', 'package.json')), /hand-entered source|columns|Cannot read/);
    });

    check('the migration creates both tables closed to PostgREST', () => {
      const sql = fs.readFileSync(path.join(__dirname, '..', 'migrations', '20261104_market_observations.sql'), 'utf8');
      assert.match(sql, /CREATE TABLE IF NOT EXISTS market_observations/);
      assert.match(sql, /UNIQUE \(source, source_ref\)/);
      assert.match(sql, /REVOKE ALL ON market_observations FROM anon, authenticated/);
      // MediaCongo widened the CHECK later; that migration restates the whole list.
      const widened = fs.readFileSync(path.join(__dirname, '..', 'migrations', '20261104_market_source_mediacongo.sql'), 'utf8');
      assert.match(widened, /DROP CONSTRAINT IF EXISTS market_observations_source_check/);
      for (const source of market72.SOURCES) assert.ok(widened.includes(`'${source}'`), `CHECK lists ${source}`);
    });
  }

