  // §81 "Mon déménagement": the 24 h promise and the next step after a visit (2026-11-07)
  // ---------------------------------------------------------------------------
  console.log('\n§81 a move request no agency answered in 24 h reaches the ops desk, once');
  {
    const follow81 = require('../services/moveFollowup');
    const sweeps81 = require('../services/viewingSweeps');
    const savedDesk81 = process.env.OPS_WHATSAPP_NUMBER;
    const savedFlag81 = process.env.MOVE_FOLLOWUP;
    try {
      process.env.OPS_WHATSAPP_NUMBER = '243846962654';
      delete process.env.MOVE_FOLLOWUP;
      const now81 = Date.parse('2026-11-09T12:00:00Z');
      const ts81 = (ms) => follow81.sqliteTs(ms);
      const mk81 = (hoursAgo, extra = {}) => {
        const lead = dbService.createLead({ wa_id: `24390000081${hoursAgo}`, source: 'move-project', commune: 'Gombe', move_story: 'Projet : nouveau travail', ...extra });
        dbService.db.prepare('UPDATE leads SET created_at = ? WHERE id = ?').run(ts81(now81 - hoursAgo * 3600_000), lead.id);
        return lead.id;
      };
      const due81 = mk81(25);
      const fresh81 = mk81(5);
      const old81 = mk81(24 * 9);
      const other81 = dbService.createLead({ wa_id: '243900000819', source: 'guest-search-request', commune: 'Gombe' }).id;
      dbService.db.prepare('UPDATE leads SET created_at = ? WHERE id = ?').run(ts81(now81 - 30 * 3600_000), other81);

      await checkAsync('only a move request 24 h–7 days old with no agency answer is due', async () => {
        const ids = follow81.dueLeads(now81).map((l) => l.id);
        assert.ok(ids.includes(due81));
        assert.ok(!ids.includes(fresh81), 'under 24 h is not due');
        assert.ok(!ids.includes(old81), 'older than 7 days is not chased');
        assert.ok(!ids.includes(other81), 'only move-project requests carry the promise');
      });
      await checkAsync('the desk is told once, with the story, and the row is stamped', async () => {
        const sent = [];
        const r1 = await follow81.runMoveFollowups({ now: now81, send: async (to, text) => { sent.push({ to, text }); return 'session'; } });
        assert.ok(r1.sent >= 1);
        const mine = sent.find((s) => s.text.includes(`/admin/leads/${due81}`));
        assert.ok(mine && mine.to === '243846962654');
        assert.match(mine.text, /Projet : nouveau travail/);
        const r2 = await follow81.runMoveFollowups({ now: now81, send: async () => 'session' });
        assert.ok(!follow81.dueLeads(now81).some((l) => l.id === due81), 'never twice');
        assert.ok(r2.due === 0 || !sent.slice(1).some((s) => s.text.includes(`/admin/leads/${due81}`)));
      });
      await checkAsync('an agency proposal means nobody needs chasing', async () => {
        const answered = mk81(26);
        dbService.db.prepare('INSERT INTO lead_proposals (lead_id, agent_id, property_id) VALUES (?, ?, ?)').run(answered, 1, 1);
        assert.ok(!follow81.dueLeads(now81).some((l) => l.id === answered));
      });
      await checkAsync('MOVE_FOLLOWUP=off sends nothing', async () => {
        mk81(27);
        process.env.MOVE_FOLLOWUP = 'off';
        const r = await follow81.runMoveFollowups({ now: now81, send: async () => { throw new Error('must not send'); } });
        assert.deepStrictEqual(r, { due: 0, sent: 0, nobody: 0 });
      });
      check('the job checks every 15 minutes and is registered before the backup', () => {
        assert.strictEqual(follow81.moveFollowupJob.shouldRun(new Date('2026-11-09T12:15:00Z')), true);
        assert.strictEqual(follow81.moveFollowupJob.shouldRun(new Date('2026-11-09T12:16:00Z')), false);
      });
      check('after a visit that did not work out, real alternatives — or the honest thanks', () => {
        assert.strictEqual(sweeps81.falloffNextText([]), sweeps81.FALLOFF_THANKS || sweeps81.falloffNextText([]));
        const text = sweeps81.falloffNextText([{ id: 7, title: 'Appartement 2 ch', price: 600 }]);
        assert.match(text, /Voici d'autres biens qui correspondent à votre recherche/);
        assert.match(text, /\/listings\/7/);
        assert.doesNotMatch(sweeps81.falloffNextText([]), /Voici/);
      });
    } finally {
      if (savedDesk81 === undefined) delete process.env.OPS_WHATSAPP_NUMBER; else process.env.OPS_WHATSAPP_NUMBER = savedDesk81;
      if (savedFlag81 === undefined) delete process.env.MOVE_FOLLOWUP; else process.env.MOVE_FOLLOWUP = savedFlag81;
    }
  }

  // §82 Direct contact: the agent reached the customer from their own phone (2026-11-07)
  // ---------------------------------------------------------------------------
  // Reported 2026-11-07: an agent answered a customer on WhatsApp from their own
  // phone and our side showed no reply. That chat is invisible to us, so the
  // agent is asked after 2 hours, and the dashboard and desk can record it.
  console.log('\n§82 a direct contact the agent tells us about is recorded and stops the escalation');
  {
    const sweeps82 = require('../services/viewingSweeps');
    const repoBefore82 = propertyRepo.getListingContactById;
    const flagBefore82 = process.env.VIEWING_CONTACT_CHECK;
    const sqlTs82 = (msAgo) => new Date(Date.now() - msAgo).toISOString().replace('T', ' ').replace(/\.\d+Z$/, '');
    const mk82 = (minutesAgo, routingType = 'DIRECT_WA') => {
      const r = freshViewingRequest('samedi 14h');
      dbService.setViewingRouting(r.id, { agentId: 43, routingType });
      dbService.db.prepare('UPDATE viewing_requests SET created_at = ? WHERE id = ?').run(sqlTs82(minutesAgo * 60_000), r.id);
      return r.id;
    };
    const sendsTo82 = (wa) => httpCalls.filter((c) => c.data && String(c.data.to) === wa);
    const mentions82 = (calls, text) => calls.filter((c) => JSON.stringify(c.data).includes(text));
    try {
      propertyRepo.getListingContactById = async () => ATTRIBUTED_LISTING;
      delete process.env.VIEWING_CONTACT_CHECK;

      check('the alert tells the agent we cannot see their own chats with the customer', () => {
        const text = viewingNotifications.agentMessage({
          listing: ATTRIBUTED_LISTING,
          lead: { name: 'A', wa_id: '243990111222' },
          viewingRequest: { requested_time: 'samedi' },
          propertyId: 303,
        });
        assert.match(text, /nous ne voyons pas vos échanges/);
      });
      check('the contact check has three buttons within 20 characters, ids naming the request', () => {
        const buttons = viewingNotifications.contactCheckButtons(9);
        assert.strictEqual(buttons.length, 3);
        for (const b of buttons) assert.ok([...b.title].length <= 20, b.title);
        assert.deepStrictEqual(viewingNotifications.parseViewingButtonId(buttons[0].id), { action: 'contact_wa', viewingRequestId: 9 });
        assert.deepStrictEqual(viewingNotifications.parseViewingButtonId(buttons[2].id), { action: 'contact_not', viewingRequestId: 9 });
      });

      const due82 = mk82(121);
      const fresh82 = mk82(60);
      const stale82 = mk82(25 * 60);
      const escalated82 = mk82(121);
      dbService.markSlaAlerted(escalated82);
      const central82 = mk82(121, 'CENTRAL_FALLBACK');
      check('due after 2 hours, only where a verified agent was alerted directly', () => {
        assert.strictEqual(sweeps82.CONTACT_CHECK_MS, 2 * 60 * 60 * 1000);
        const ids = dbService.listViewingRequestsDueForContactCheck(sweeps82.CONTACT_CHECK_MS, undefined, sweeps82.CONTACT_CHECK_MAX_AGE_MS).map((r) => r.id);
        assert.ok(ids.includes(due82));
        assert.ok(!ids.includes(fresh82), 'not before 2 hours');
        assert.ok(ids.includes(escalated82), 'the check comes after the 15-minute escalation, so an escalated request is still asked');
        assert.ok(!ids.includes(stale82), 'never about a request older than 24 hours');
        assert.ok(!ids.includes(central82), 'nobody to ask on a central fallback');
      });

      httpCalls.length = 0;
      await sweeps82.runContactCheckSweep();
      const asked82 = mentions82(sendsTo82(AGENT_WA), `viewing_contact_wa:${due82}`);
      check('the sweep asks the agent once, with the contact buttons, and stamps the row', () => {
        assert.strictEqual(asked82.length, 1);
        assert.match(JSON.stringify(asked82[0].data), /Avez-vous déjà contacté le client/);
        assert.ok(dbService.getViewingRequest(due82).contact_check_sent_at);
      });
      httpCalls.length = 0;
      await sweeps82.runContactCheckSweep();
      check('never asked twice', () =>
        assert.strictEqual(mentions82(sendsTo82(AGENT_WA), `viewing_contact_wa:${due82}`).length, 0));

      const stranger82 = await viewingNotifications.handleViewingButtonReply({ from: '243999000111', replyId: `viewing_contact_wa:${due82}` });
      check('a stranger tapping the button records nothing', () => {
        assert.strictEqual(stranger82.handled, true);
        assert.strictEqual(dbService.getViewingRequest(due82).direct_contact_at, null);
      });

      httpCalls.length = 0;
      const yes82 = await viewingNotifications.handleViewingButtonReply({ from: AGENT_WA, replyId: `viewing_contact_wa:${due82}` });
      const yesRow82 = dbService.getViewingRequest(due82);
      check('"Oui, WhatsApp" records the contact and who said it, and leaves status and latency alone', () => {
        assert.strictEqual(yes82.action, 'direct-contact');
        assert.ok(yesRow82.direct_contact_at);
        assert.strictEqual(yesRow82.direct_contact_channel, 'whatsapp');
        assert.strictEqual(yesRow82.direct_contact_by, 'AGENT_WHATSAPP');
        assert.strictEqual(yesRow82.status, 'PENDING');
        assert.strictEqual(yesRow82.first_response_at, null, 'not an answer through our loop: no invented latency');
        assert.strictEqual(sendsTo82(AGENT_WA).length, 1, 'the agent is thanked');
        assert.strictEqual(sendsTo82('243990111222').length, 0, 'the customer is not messaged');
      });
      check('a recorded direct contact is never escalated by the SLA sweep', () => {
        dbService.db.prepare('UPDATE viewing_requests SET created_at = ? WHERE id = ?').run(sqlTs82(20 * 60_000), due82);
        assert.ok(!dbService.listViewingRequestsAwaitingSla(sweeps82.SLA_MS).some((r) => r.id === due82));
      });

      const notYet82 = mk82(121);
      httpCalls.length = 0;
      await viewingNotifications.handleViewingButtonReply({ from: AGENT_WA, replyId: `viewing_contact_not:${notYet82}` });
      check('"Pas encore" records nothing, re-sends the visit buttons, and the escalation still comes', () => {
        assert.strictEqual(dbService.getViewingRequest(notYet82).direct_contact_at, null);
        assert.strictEqual(mentions82(sendsTo82(AGENT_WA), `viewing_accept:${notYet82}`).length, 1);
        dbService.db.prepare('UPDATE viewing_requests SET created_at = ? WHERE id = ?').run(sqlTs82(16 * 60_000), notYet82);
        assert.ok(dbService.listViewingRequestsAwaitingSla(sweeps82.SLA_MS).some((r) => r.id === notYet82));
      });

      const typed82 = mk82(121);
      dbService.setPendingAgentAction({ waId: AGENT_WA, kind: 'CONTACT_CHECK', viewingRequestId: typed82 });
      const typedOut82 = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: '2' });
      check('a typed "2" answers the numbered fallback: contacted by phone', () => {
        assert.strictEqual(typedOut82.handled, true);
        assert.strictEqual(dbService.getViewingRequest(typed82).direct_contact_channel, 'phone');
        // §88: the contact check is settled and "is the visit fixed?" is now the open question.
        const next = dbService.getPendingAgentAction(AGENT_WA);
        assert.strictEqual(next.kind, 'VIEWING_RESPONSE');
        assert.strictEqual(next.viewing_request_id, typed82);
      });

      const desk82 = mk82(30);
      const dash82 = mk82(30);
      httpCalls.length = 0;
      await checkAsync('the desk and the agent dashboard can record it, and nobody is messaged', async () => {
        const desk = await viewingNotifications.recordDirectContact({ viewingRequestId: desk82, channel: 'whatsapp', by: 'DESK' });
        assert.deepStrictEqual(desk, { ok: true, recorded: true });
        assert.strictEqual(dbService.getViewingRequest(desk82).direct_contact_by, 'DESK');
        const again = await viewingNotifications.recordDirectContact({ viewingRequestId: desk82, channel: 'phone', by: 'DESK' });
        assert.strictEqual(again.recorded, false, 'the first record stands');
        assert.strictEqual(dbService.getViewingRequest(desk82).direct_contact_channel, 'whatsapp');
        const wrong = await viewingNotifications.recordDirectContact({ viewingRequestId: dash82, channel: 'phone', by: 'AGENT_DASHBOARD', agentId: 999 });
        assert.strictEqual(wrong.reason, 'not-this-requests-agent');
        const right = await viewingNotifications.recordDirectContact({ viewingRequestId: dash82, channel: 'phone', by: 'AGENT_DASHBOARD', agentId: 43 });
        assert.strictEqual(right.ok, true);
        assert.strictEqual(dbService.getViewingRequest(dash82).direct_contact_by, 'AGENT_DASHBOARD');
        assert.strictEqual(httpCalls.length, 0);
      });
      await checkAsync('a bad channel or a closed request is refused', async () => {
        const r = mk82(30);
        assert.strictEqual((await viewingNotifications.recordDirectContact({ viewingRequestId: r, channel: 'pigeon', by: 'DESK' })).reason, 'invalid-channel');
        dbService.updateViewingRequest(r, { status: 'DECLINED' });
        assert.strictEqual((await viewingNotifications.recordDirectContact({ viewingRequestId: r, channel: 'phone', by: 'DESK' })).reason, 'request-closed');
      });
      check('the interaction counts read a direct contact as contacted', () => {
        const counts = dbService.getInteractionCounts({ since: '2000-01-01' });
        const viewings = counts.viewings || [];
        const contacted = viewings.reduce((sum, row) => sum + Number(row.contacted || 0), 0);
        assert.ok(contacted >= 4, `contacted=${contacted}`);
      });
      check('the owner list (agent dashboard) carries the direct-contact fields', () => {
        const page = dbService.listViewingRequestsForOwner({ propertyIds: [303], limit: 200 });
        const row = page.data.find((r) => r.id === dash82);
        assert.ok(row && row.direct_contact_at && row.direct_contact_by === 'AGENT_DASHBOARD');
      });
      await checkAsync('VIEWING_CONTACT_CHECK=off asks nobody', async () => {
        mk82(122);
        process.env.VIEWING_CONTACT_CHECK = 'off';
        httpCalls.length = 0;
        const r = await sweeps82.runContactCheckSweep();
        assert.strictEqual(r.disabled, true);
        assert.strictEqual(httpCalls.length, 0);
        assert.strictEqual(sweeps82.contactCheckJob.shouldRun(), false);
      });
    } finally {
      propertyRepo.getListingContactById = repoBefore82;
      if (flagBefore82 === undefined) delete process.env.VIEWING_CONTACT_CHECK;
      else process.env.VIEWING_CONTACT_CHECK = flagBefore82;
    }
  }

  // §83 "Changer de numéro": a customer moves the account to a new number (2026-11-08)
  // ---------------------------------------------------------------------------
  console.log('\n§83 the customer phone-change migration is additive and closed to the anon key');
  {
    const sql83 = fs.readFileSync(path.join(__dirname, '..', 'migrations', '20261108_customer_phone_change.sql'), 'utf8');
    check('every new customers column is ADD COLUMN IF NOT EXISTS', () => {
      for (const col of ['phone_change_to', 'phone_change_code_hash', 'phone_change_expires_at', 'phone_change_attempts', 'phone_change_sends', 'phone_change_window_at']) {
        assert.ok(sql83.includes(`ADD COLUMN IF NOT EXISTS ${col}`), col);
      }
    });
    check('customer_phone_history cascades with the account and has RLS on, anon revoked', () => {
      assert.match(sql83, /CREATE TABLE IF NOT EXISTS customer_phone_history/);
      assert.match(sql83, /REFERENCES customers \(id\) ON DELETE CASCADE/);
      assert.match(sql83, /ALTER TABLE customer_phone_history ENABLE ROW LEVEL SECURITY/);
      assert.match(sql83, /REVOKE ALL ON customer_phone_history FROM anon, authenticated/);
    });
    check('nothing in the migration rewrites or drops existing customer data', () => {
      // "ON DELETE CASCADE" is the history's foreign key, not a delete.
      assert.doesNotMatch(sql83.replace(/ON DELETE CASCADE/g, ''), /\bDROP\b|\bUPDATE\b|\bDELETE\b/i);
    });
  }

  // §84 One paste = prices AND agents, one agent list (2026-11-08)
  // ---------------------------------------------------------------------------
  console.log('\n§84 a pasted advert feeds the price guide and the ONE agent list (market_prospects)');
  {
    const mp84 = require('../services/marketProspects');
    const imp84 = require('./import-market-observations');
    // Read inside the checks: the VPS engine dir has no web/ (those checks fail there by construction).
    const webFile84 = (...parts) => fs.readFileSync(path.join(__dirname, '..', 'web', ...parts), 'utf8');
    const norm84 = (s) => s.replace(/\s+/g, ' ').trim();
    const template84 = (src, name) => {
      const m = src.match(new RegExp(`const ${name} = \`([\\s\\S]*?)\`;`));
      assert.ok(m, `${name} not found`);
      return norm84(m[1]);
    };

    check('engine and web write a prospect with the same upsert and link (duplicated module pair)', () => {
      assert.strictEqual(norm84(mp84.UPSERT_PROSPECT_SQL), template84(webFile84('lib', 'marketProspects.js'), 'UPSERT_PROSPECT_SQL'));
      assert.strictEqual(norm84(mp84.LINK_SQL), template84(webFile84('lib', 'marketProspects.js'), 'LINK_SQL'));
      assert.match(mp84.UPSERT_PROSPECT_SQL, /name = COALESCE\(market_prospects\.name, EXCLUDED\.name\)/, 'a later paste never overwrites the team');
    });

    check('engine prospectPhone is web prospectPhone', () => {
      const body = (src) => norm84(src.match(/function prospectPhone\(value\) \{([\s\S]*?)\n\}/)[1]);
      assert.strictEqual(body(fs.readFileSync(path.join(__dirname, '..', 'services', 'marketProspects.js'), 'utf8')), body(webFile84('lib', 'marketProspectRules.js')));
      assert.strictEqual(mp84.prospectPhone('0812 345 678'), '243812345678');
      assert.strictEqual(mp84.prospectPhone('+243 99 123 4567'), '243991234567');
      assert.strictEqual(mp84.prospectPhone('812345678'), '243812345678');
      assert.strictEqual(mp84.prospectPhone('1500'), null, 'a price is not a number to call');
    });

    const file84 = path.join(require('os').tmpdir(), `lukka-fb-paste-${process.pid}.json`);
    fs.writeFileSync(file84, JSON.stringify({
      source: 'facebook',
      entered: '2026-11-08',
      columns: ['slug', 'kind', 'price', 'beds', 'commune', 'quartier', 'daysAgo', 'phone', 'name', 'agency', 'url', 'purpose'],
      rows: [
        ['fb-1', 'appartement', 600, 2, 'Ngaliema', 'Binza UPN', 1, '0812 345 678', 'Jean Immo', null, 'https://www.facebook.com/groups/1/posts/2', null],
        ['fb-2', 'maison', 900, 3, 'Limete', null, 2, '+243 812 345 678', null, 'Immo Plus', null, null],
        ['fb-3', 'appartement', 450, 1, 'Gombe', null, 0, '', null, null, null, null],
        ['fb-4', 'villa', 250000, 4, 'Ngaliema', null, 3, '0991234567', 'Marie', null, null, 'sale'],
      ],
    }));
    try {
      check('the chat import reads prices as before and posters only from rows with a number', () => {
        const rows = imp84.rowsFromFile(file84);
        assert.strictEqual(rows.length, 4);
        assert.ok(rows.every((r) => !('phone' in r) && !JSON.stringify(r).includes('812345678')), 'no phone in market_observations');
        const sale = rows.find((r) => r.source_ref === 'fb-4');
        assert.deepStrictEqual([sale.purpose, sale.price_period], ['sale', 'total']);
        assert.strictEqual(rows.find((r) => r.source_ref === 'fb-1').source_url, 'https://www.facebook.com/groups/1/posts/2');
        const posters = imp84.prospectsFromFile(file84);
        assert.deepStrictEqual(posters.map((p) => [p.ref, p.phone]), [['fb-1', '243812345678'], ['fb-2', '243812345678'], ['fb-4', '243991234567']]);
      });

      check('one entry per number; only adverts new to this import are counted', () => {
        const grouped = mp84.groupProspects(imp84.prospectsFromFile(file84), new Set(['fb-2', 'fb-4']));
        assert.strictEqual(grouped.length, 2);
        const jean = grouped.find((p) => p.phone === '243812345678');
        assert.deepStrictEqual([jean.name, jean.agency, jean.adverts, jean.refs], ['Jean Immo', 'Immo Plus', 1, ['fb-1', 'fb-2']]);
        assert.strictEqual(jean.url, 'https://www.facebook.com/groups/1/posts/2');
      });

      check('a typo in a phone stops the import instead of dropping the agent', () => {
        const bad = JSON.parse(fs.readFileSync(file84, 'utf8'));
        bad.rows[0][7] = '12';
        fs.writeFileSync(file84, JSON.stringify(bad));
        assert.throws(() => imp84.prospectsFromFile(file84), /fb-1: '12' is not a phone number/);
      });
    } finally {
      fs.rmSync(file84, { force: true });
    }

    await checkAsync('saveProspects upserts each poster with the source and links its stored adverts', async () => {
      const calls = [];
      const client = {
        async query(sql, params) {
          calls.push({ sql: norm84(sql), params });
          if (sql === mp84.OBSERVATION_IDS_SQL) return { rows: [{ id: '11', source_ref: 'fb-1' }, { id: '12', source_ref: 'fb-2' }] };
          if (sql === mp84.UPSERT_PROSPECT_SQL) return { rows: [{ id: '7', created: params[0] === '243812345678' }] };
          return { rows: [{ prospect_id: 7 }], rowCount: 1 };
        },
      };
      const result = await mp84.saveProspects(client, [
        { phone: '243812345678', name: 'Jean Immo', agency: null, url: null, adverts: 2, refs: ['fb-1', 'fb-2'] },
        { phone: '243991234567', name: 'Marie', agency: null, url: null, adverts: 0, refs: ['fb-9'] },
      ], { source: 'facebook' });
      assert.deepStrictEqual(result, { prospectsNew: 1, prospectsUpdated: 1, linked: 2 });
      assert.deepStrictEqual(calls[1].params, ['243812345678', 'Jean Immo', null, ['facebook'], null, 2, null]);
      assert.deepStrictEqual(calls.filter((c) => /market_prospect_adverts/.test(c.sql)).map((c) => c.params), [[7, 11], [7, 12]]);
    });

    check('the import stores prices and posters in ONE transaction', () => {
      const src = fs.readFileSync(path.join(__dirname, 'import-market-observations.js'), 'utf8');
      const begin = src.indexOf("client.query('BEGIN')");
      assert.ok(begin > 0 && begin < src.indexOf('storeObservations(rows, { pool: client })'));
      assert.ok(src.indexOf('saveProspects(client') < src.indexOf("client.query('COMMIT')"));
      assert.match(src, /client\.query\('ROLLBACK'\)/);
    });

    check('the older Facebook list is merged into market_prospects without touching the team\'s rows', () => {
      const sql = fs.readFileSync(path.join(__dirname, '..', 'migrations', '20261108_merge_facebook_prospects.sql'), 'utf8');
      assert.match(sql, /INSERT INTO market_prospects/);
      assert.match(sql, /ON CONFLICT \(phone\) DO NOTHING/);
      assert.match(sql, /to_regclass\('public\.facebook_prospects'\) IS NULL/);
      assert.doesNotMatch(sql, /\bDROP\b|\bDELETE\b|\bTRUNCATE\b|UPDATE\s+market_prospects/i);
      assert.match(sql, /WHEN 'registered'\s+THEN 'signed'/);
    });

    check('every web writer of agents uses market_prospects; nothing writes facebook_prospects any more', () => {
      const fb = fs.readFileSync(path.join(__dirname, '..', 'web', 'lib', 'facebookProspects.js'), 'utf8');
      assert.match(fb, /import \{ UPSERT_PROSPECT_SQL \} from '\.\/marketProspects'/);
      assert.doesNotMatch(fb, /INSERT INTO facebook_prospects/);
      const exportScript = fs.readFileSync(path.join(__dirname, '..', 'web', 'scripts', 'export-facebook-leads.mjs'), 'utf8');
      assert.match(exportScript, /FROM market_prospects/);
      const oldPage = fs.readFileSync(path.join(__dirname, '..', 'web', 'app', 'admin', 'prospects', 'paste', 'page.js'), 'utf8');
      assert.match(oldPage, /redirect\('\/admin\/market-data\/marche#coller'\)/);
    });

    check('an undated advert keeps posted_at NULL, and an unstated furnishing stays unknown', () => {
      const file = path.join(require('os').tmpdir(), `lukka-undated-${process.pid}.json`);
      fs.writeFileSync(file, JSON.stringify({
        source: 'other',
        entered: '2026-11-08',
        columns: ['slug', 'kind', 'price', 'beds', 'commune', 'quartier', 'daysAgo', 'furnished'],
        rows: [
          ['u-1', 'appartement', 900, 2, 'Bandalungwa', null, null, false],
          ['u-2', 'appartement', 2900, 1, 'Ngaliema', null, '', true],
          ['u-3', 'appartement', 700, 2, 'Ngaliema', null, 2, null],
        ],
      }));
      try {
        const rows = imp84.rowsFromFile(file);
        assert.deepStrictEqual(rows.map((r) => r.posted_at), [null, null, '2026-11-06T12:00:00.000Z'], 'no date is never "today"');
        assert.deepStrictEqual(rows.map((r) => r.furnished), [false, true, null], 'not stated is not "unfurnished"');
      } finally {
        fs.rmSync(file, { force: true });
      }
    });
  }

  // §85 "Un client vous contacte": the agent is told the moment a customer taps (2026-11-08)
  // ---------------------------------------------------------------------------
  // A tap on a verified agent's WhatsApp / Appeler button opens a chat we never
  // see. Owner request 2026-11-08: let the agent know straight away, and ask
  // whether they answered — the only way that conversation becomes visible.
  console.log('\n§85 a customer tap on an agent\'s button alerts that agent at once, and their answer is kept');
  {
    const tap83 = require('../services/contactTapAlert');
    const repoListing83 = propertyRepo.getListingContactById;
    const repoAgent83 = propertyRepo.getAgentContactById;
    const flag83 = process.env.CONTACT_TAP_ALERT;
    const toAgent83 = () => httpCalls.filter((c) => c.data && String(c.data.to) === AGENT_WA);
    let listing83 = ATTRIBUTED_LISTING;
    let agent83 = { agent_id: 43, deleted: false };
    try {
      delete process.env.CONTACT_TAP_ALERT;
      propertyRepo.getListingContactById = async () => listing83;
      propertyRepo.getAgentContactById = async () => agent83;

      check('the buttons fit WhatsApp\'s 20 characters and never collide with the viewing buttons', () => {
        for (const kind of tap83.KINDS) {
          for (const b of tap83.buttons(7, kind)) assert.ok([...b.title].length <= 20, b.title);
        }
        assert.deepStrictEqual(tap83.parseTapButtonId('contact_tap_replied:7'), { answer: 'REPLIED', alertId: 7 });
        assert.strictEqual(tap83.parseTapButtonId('viewing_accept:7'), null);
        assert.strictEqual(viewingNotifications.parseViewingButtonId('contact_tap_replied:7'), null);
      });

      httpCalls.length = 0;
      const first83 = await tap83.alertAgentOfTap({ propertyId: 8301, kind: 'whatsapp', visitorKey: 'v-83a' });
      check('a WhatsApp tap alerts the listing\'s agent at once, naming the listing, with the two buttons', () => {
        assert.strictEqual(first83.sent, true);
        assert.strictEqual(first83.channel, 'buttons');
        const sent = toAgent83();
        assert.strictEqual(sent.length, 1);
        const body = JSON.stringify(sent[0].data);
        assert.match(body, /Un client vous contacte/);
        assert.match(body, /« WhatsApp »/);
        assert.match(body, new RegExp(`contact_tap_replied:${first83.alertId}`));
        assert.match(body, new RegExp(`contact_tap_nothing:${first83.alertId}`));
        assert.doesNotMatch(body, /vous a écrit/, 'a tap is not a message');
      });

      httpCalls.length = 0;
      const again83 = await tap83.alertAgentOfTap({ propertyId: 8301, kind: 'whatsapp', visitorKey: 'v-83a' });
      const other83 = await tap83.alertAgentOfTap({ propertyId: 8301, kind: 'whatsapp', visitorKey: 'v-83b' });
      check('a repeat tap is not re-sent: same visitor 24 h, same listing 30 min', () => {
        assert.deepStrictEqual(again83, { sent: false, reason: 'duplicate-visitor' });
        assert.deepStrictEqual(other83, { sent: false, reason: 'recent-alert' });
        assert.strictEqual(toAgent83().length, 0);
      });

      httpCalls.length = 0;
      const call83 = await tap83.alertAgentOfTap({ propertyId: 8302, kind: 'call', visitorKey: 'v-83c' });
      check('an "Appeler" tap tells the agent a call is coming', () => {
        assert.strictEqual(call83.sent, true);
        const body = JSON.stringify(toAgent83()[0].data);
        assert.match(body, /« Appeler »/);
        assert.match(body, /On s'est parlé/);
      });

      await checkAsync('the shared agent gates apply: unverified, routing off, deleted, not public', async () => {
        listing83 = { ...ATTRIBUTED_LISTING, phone_verified_at: null };
        assert.strictEqual((await tap83.alertAgentOfTap({ propertyId: 8303, kind: 'whatsapp' })).reason, 'numéro agent non vérifié');
        listing83 = { ...ATTRIBUTED_LISTING, direct_routing_enabled: false };
        assert.match((await tap83.alertAgentOfTap({ propertyId: 8304, kind: 'whatsapp' })).reason, /routage direct désactivé/);
        listing83 = ATTRIBUTED_LISTING;
        agent83 = { agent_id: 43, deleted: true };
        assert.strictEqual((await tap83.alertAgentOfTap({ propertyId: 8305, kind: 'whatsapp' })).reason, 'agent-deleted');
        agent83 = { agent_id: 43, deleted: false };
        listing83 = null;
        assert.strictEqual((await tap83.alertAgentOfTap({ propertyId: 8306, kind: 'whatsapp' })).reason, 'listing-not-public');
        listing83 = ATTRIBUTED_LISTING;
        assert.strictEqual((await tap83.alertAgentOfTap({ propertyId: 8307, kind: 'sms' })).reason, 'invalid-kind');
      });

      await checkAsync('CONTACT_TAP_ALERT=off sends nothing', async () => {
        process.env.CONTACT_TAP_ALERT = 'off';
        httpCalls.length = 0;
        assert.deepStrictEqual(await tap83.alertAgentOfTap({ propertyId: 8308, kind: 'whatsapp' }), { sent: false, reason: 'disabled' });
        assert.strictEqual(httpCalls.length, 0);
        delete process.env.CONTACT_TAP_ALERT;
      });

      const stranger83 = await tap83.handleTapButtonReply({ from: '243999000111', replyId: `contact_tap_replied:${first83.alertId}` });
      check('only the alerted agent can answer', () => {
        assert.strictEqual(stranger83.ignored, 'not-this-agent');
        assert.strictEqual(dbService.getContactTapAlert(first83.alertId).answer, null);
      });
      httpCalls.length = 0;
      const replied83 = await tap83.handleTapButtonReply({ from: AGENT_WA, replyId: `contact_tap_replied:${first83.alertId}` });
      const late83 = await tap83.handleTapButtonReply({ from: AGENT_WA, replyId: `contact_tap_nothing:${first83.alertId}` });
      check('"J\'ai répondu" is stored with its time, the agent is thanked, and the first answer stands', () => {
        assert.strictEqual(replied83.recorded, true);
        const row = dbService.getContactTapAlert(first83.alertId);
        assert.strictEqual(row.answer, 'REPLIED');
        assert.ok(row.answered_at);
        assert.strictEqual(late83.recorded, false);
        assert.ok(toAgent83().length >= 1, 'thanked');
      });
      await tap83.handleTapButtonReply({ from: AGENT_WA, replyId: `contact_tap_nothing:${call83.alertId}` });

      check('the interaction counts carry the alerts and the answers', () => {
        const counts = dbService.getInteractionCounts({ since: '2000-01-01' });
        const rows = counts.contactTaps.filter((r) => r.propertyId === 8301 || r.propertyId === 8302);
        const wa = rows.find((r) => r.kind === 'whatsapp');
        const call = rows.find((r) => r.kind === 'call');
        assert.deepStrictEqual({ alerted: wa.alerted, replied: wa.replied }, { alerted: 1, replied: 1 });
        assert.deepStrictEqual({ alerted: call.alerted, nothing: call.nothing }, { alerted: 1, nothing: 1 });
      });

      check('the webhook routes these buttons to the tap handler', () => {
        const src = fs.readFileSync(path.join(__dirname, '..', 'routes', 'webhook.js'), 'utf8');
        assert.match(src, /handleTapButtonReply\(\{ from, replyId: buttonReplyId \}\)/);
      });
    } finally {
      propertyRepo.getListingContactById = repoListing83;
      propertyRepo.getAgentContactById = repoAgent83;
      if (flag83 === undefined) delete process.env.CONTACT_TAP_ALERT;
      else process.env.CONTACT_TAP_ALERT = flag83;
    }
  }

  // §86 A typed reply to a TEMPLATE visit alert is not lost (2026-11-09)
  // ---------------------------------------------------------------------------
  // Request #19: the alert went out as demande_visite_agent_v2 (a link button,
  // no Accepter), the agent answered on WhatsApp, and the text went to listing
  // intake — the request stayed PENDING and escalated.
  console.log('\n§86 an agent\'s typed answer to a template visit alert reaches the visit');
  {
    const tpl86 = process.env.VIEWING_REQUEST_TEMPLATE;
    const repo86 = propertyRepo.getListingContactById;
    const alert86 = async () => {
      const r = freshViewingRequest('lundi 9 novembre à 16h15');
      dbService.clearPendingAgentAction(AGENT_WA);
      await viewingNotifications.notifyViewingRequest({
        viewingRequest: r,
        lead: { name: 'Henoc Mimbo', wa_id: '243990111222' },
      });
      return r.id;
    };
    try {
      process.env.VIEWING_REQUEST_TEMPLATE = 'demande_visite_agent_v2';
      propertyRepo.getListingContactById = async () => ATTRIBUTED_LISTING;

      check('a plain yes is an accept; a no, a "but", a figure or a stranger sentence is not', () => {
        for (const yes of ['ok', 'Ok je confirme', "C'est bon pour la visite", "d'accord", 'Oui 👍', 'Je suis disponible', 'Confirmé merci boss', '✅']) {
          assert.ok(viewingNotifications.isPlainAccept(yes), yes);
        }
        for (const no of ['pas disponible', 'non', 'ok mais demain', 'déjà loué', 'ok à 17h', 'comment faire ?', 'parfait', 'merci', 'je ne peux pas', 'autre créneau']) {
          assert.ok(!viewingNotifications.isPlainAccept(no), no);
        }
      });

      const accepted86 = await alert86();
      check('a template alert claims the agent\'s next message for that request', () => {
        const pending = dbService.getPendingAgentAction(AGENT_WA);
        assert.strictEqual(pending.kind, 'VIEWING_ALERT');
        assert.strictEqual(pending.viewing_request_id, accepted86);
      });
      httpCalls.length = 0;
      const ok86 = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: 'Ok je confirme' });
      check('"Ok je confirme" confirms the visit and tells the customer', () => {
        assert.strictEqual(ok86.handled, true);
        assert.strictEqual(ok86.action, 'accept');
        assert.strictEqual(dbService.getViewingRequest(accepted86).status, 'CONFIRMED');
        assert.ok(httpCalls.some((c) => c.data && String(c.data.to) === '243990111222'), 'customer messaged');
      });

      const unclear86 = await alert86();
      httpCalls.length = 0;
      const ask86 = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: 'Comment faire ?' });
      check('an unclear short reply is asked once, with the three answers, and nothing is decided', () => {
        assert.strictEqual(ask86.handled, true);
        assert.strictEqual(ask86.action, 'clarify');
        assert.strictEqual(dbService.getViewingRequest(unclear86).status, 'PENDING');
        assert.ok(httpCalls.some((c) => JSON.stringify(c.data || {}).includes(`viewing_accept:${unclear86}`)), 'buttons name the request');
        assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA).kind, 'VIEWING_RESPONSE');
      });
      const one86 = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: '1' });
      check('then a typed 1 accepts it', () => {
        assert.strictEqual(one86.action, 'accept');
        assert.strictEqual(dbService.getViewingRequest(unclear86).status, 'CONFIRMED');
      });

      const advert86 = await alert86();
      const listing86 = await viewingNotifications.handleAgentTextReply({
        from: AGENT_WA,
        text: 'Maison à louer Limete 3 chambres 400$ garantie 3 mois',
      });
      const photo86 = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: 'Villa Gombe', hasMedia: true });
      check('an advert or a captioned photo falls through to intake and the claim stays', () => {
        assert.strictEqual(listing86.handled, false);
        assert.strictEqual(photo86.handled, false);
        assert.strictEqual(dbService.getViewingRequest(advert86).status, 'PENDING');
        assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA).kind, 'VIEWING_ALERT');
      });

      const answered86 = await alert86();
      dbService.updateViewingRequest(answered86, { status: 'CONFIRMED' });
      const late86 = await viewingNotifications.handleAgentTextReply({ from: AGENT_WA, text: 'ok' });
      check('a request answered elsewhere is not re-answered by a late "ok"', () => {
        assert.strictEqual(late86.handled, false);
        assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA), undefined);
      });

      check('the webhook passes media to the typed handler and logs what was written', () => {
        const src = fs.readFileSync(path.join(__dirname, '..', 'routes', 'webhook.js'), 'utf8');
        assert.match(src, /handleAgentTextReply\(\{ from, text, hasMedia: mediaRefs\.length > 0 \}\)/);
        assert.match(src, /message\.text \? ` : "\$\{String\(message\.text\)/);
      });
    } finally {
      dbService.clearPendingAgentAction(AGENT_WA);
      propertyRepo.getListingContactById = repo86;
      if (tpl86 === undefined) delete process.env.VIEWING_REQUEST_TEMPLATE;
      else process.env.VIEWING_REQUEST_TEMPLATE = tpl86;
    }
  }

  // §87 The desk confirms a visit the agent agreed outside our loop (2026-11-09)
  // ---------------------------------------------------------------------------
  // Request #19: the agent said "Oui, WhatsApp" to the contact check, and the
  // visit could only stay PENDING — nobody could record that it was on.
  console.log('\n§87 the desk can confirm a visit at the agreed time, and the customer is told');
  {
    const repo87 = propertyRepo.getListingContactById;
    const now87 = new Date('2026-11-09T17:00:00Z');
    try {
      propertyRepo.getListingContactById = async () => ATTRIBUTED_LISTING;
      const r87 = freshViewingRequest('lundi 9 novembre à 16h15');
      const noTime87 = await viewingNotifications.confirmFromDesk({ viewingRequestId: r87.id, now: now87 });
      const past87 = await viewingNotifications.confirmFromDesk({ viewingRequestId: r87.id, scheduledAt: '2026-11-09T10:00:00+01:00', now: now87 });
      check('no agreed time, or a time already gone, confirms nothing', () => {
        assert.strictEqual(noTime87.reason, 'scheduled-at-required');
        assert.strictEqual(past87.reason, 'scheduled-at-past');
        assert.strictEqual(dbService.getViewingRequest(r87.id).status, 'PENDING');
      });

      dbService.setPendingAgentAction({ waId: AGENT_WA, kind: 'VIEWING_ALERT', viewingRequestId: r87.id });
      httpCalls.length = 0;
      const ok87 = await viewingNotifications.confirmFromDesk({ viewingRequestId: r87.id, scheduledAt: '2026-11-10T10:00:00+01:00', now: now87 });
      const row87 = dbService.getViewingRequest(r87.id);
      check('CONFIRMED at the agreed instant; customer and agent told; not counted as the agent\'s response', () => {
        assert.strictEqual(ok87.ok, true);
        assert.strictEqual(row87.status, 'CONFIRMED');
        assert.strictEqual(new Date(row87.scheduled_at).toISOString(), '2026-11-10T09:00:00.000Z');
        assert.strictEqual(ok87.tenantNotified, true);
        assert.strictEqual(ok87.agentNotified, true);
        assert.ok(httpCalls.some((c) => c.data && String(c.data.to) === '243990111222'), 'customer messaged');
        assert.ok(httpCalls.some((c) => c.data && String(c.data.to) === AGENT_WA && JSON.stringify(c.data).includes("confirmée par l'équipe")), 'agent told');
        assert.strictEqual(row87.first_response_at, null, 'no invented response latency');
        assert.strictEqual(dbService.getPendingAgentAction(AGENT_WA), undefined, 'an open WhatsApp question about it is closed');
      });

      httpCalls.length = 0;
      const again87 = await viewingNotifications.confirmFromDesk({ viewingRequestId: r87.id, scheduledAt: '2026-11-10T10:00:00+01:00', now: now87 });
      const declined87 = freshViewingRequest('demain');
      dbService.updateViewingRequest(declined87.id, { status: 'DECLINED' });
      const closed87 = await viewingNotifications.confirmFromDesk({ viewingRequestId: declined87.id, scheduledAt: '2026-11-10T10:00:00+01:00', now: now87 });
      check('a second click sends nothing; a declined request cannot be confirmed', () => {
        assert.strictEqual(again87.unchanged, true);
        assert.strictEqual(httpCalls.length, 0);
        assert.strictEqual(closed87.reason, 'invalid-transition');
      });

      check('the admin route and the console action exist', () => {
        const route = fs.readFileSync(path.join(__dirname, '..', 'routes', 'admin.js'), 'utf8');
        assert.match(route, /router\.post\('\/viewing-requests\/:id\/desk-confirm'/);
        const actionsFile = path.join(__dirname, '..', 'web', 'app', 'admin', 'viewings', 'actions.js');
        if (fs.existsSync(actionsFile)) {
          assert.match(fs.readFileSync(actionsFile, 'utf8'), /action: 'viewing\.desk_confirm'/);
        }
      });
    } finally {
      dbService.clearPendingAgentAction(AGENT_WA);
      propertyRepo.getListingContactById = repo87;
    }
  }

